#!/usr/bin/env python3
"""Linter regression tests.

For each in-scope linter, this module constructs a minimal synthetic
fixture appropriate to each linter's target surface (Markdown for the
corpus linters, Python source for the gate-94/95 code linters) that
should trigger exactly one rule, invokes the
linter against the fixture, and asserts the linter exits non-zero.

The tests catch a class of defect that no other gate in the audit
programme catches: a regression in the linter's own detection logic.
If a refactor weakens a regex or breaks an exemption list, the corpus
may still happen to be clean (no false positives), but the linter no
longer detects the violation class it exists to detect. A failing
positive test produces an unambiguous signal that the linter itself
is broken.

Scope is now complete: every linter in the audit programme has at
least one positive test in this module. Several linters additionally
have negative tests (fixture that should NOT be flagged) and
environmental tests (exit code 2 when a required register is
absent); see ``.claude/skills/corpus-management/tests/README.md`` for the full coverage policy.
Infrastructure-coupled linters that earlier docstrings listed as out
of scope (orphan, citation-verification freshness, tooling-provenance
freshness, library-version monotonicity, gate-name parity,
structural-index, CHANGELOG link-coverage, review-cadence) all have
dedicated test classes; see the class enumeration at the bottom of
this file.

Stdlib-only Python 3.14 (unittest, tempfile, subprocess).
"""

from __future__ import annotations

import io
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

try:
    import idna as _idna_probe  # noqa: F401 (availability probe for idna-dependent gate-22 tests)
    _HAS_IDNA = True
except ImportError:
    _HAS_IDNA = False

REPO_ROOT = Path(__file__).resolve().parents[4]
SKILL_ROOT = Path(__file__).resolve().parents[1]
# First parts that name a skill-relative path: a path that starts with one of
# these, or a bare tool file name, joins SKILL_ROOT; any other relative path
# (.claude/..., .github/, .web/, governance/, the corpus directories, the
# top-level files) joins REPO_ROOT.
_SKILL_PARTS = frozenset({
    "tools", "src", "specs", "tests", "registers", "docs", "data",
    "procedures", "defaults", "SKILL.md", "rule-index.md", "adopter-config.json",
})


def _resolve_path(rel) -> Path:
    """Resolve a path given in either form to the same file.

    An absolute path is returned unchanged; the repository path form
    (.claude/skills/corpus-management/tools/x.py) joins REPO_ROOT; the
    skill-relative form (tools/x.py) joins SKILL_ROOT."""
    p = Path(rel)
    if p.is_absolute():
        return p
    parts = p.parts
    if parts and (parts[0] in _SKILL_PARTS
                  or (len(parts) == 1 and p.suffix in (".py", ".sh"))):
        return SKILL_ROOT / p
    return REPO_ROOT / p
if str(SKILL_ROOT / "tools") not in sys.path:
    sys.path.insert(0, str(SKILL_ROOT / "tools"))
if str(SKILL_ROOT) not in sys.path:
    sys.path.insert(sys.path.index(str(SKILL_ROOT / "tools")) + 1, str(SKILL_ROOT))
import lint_common as _lint_common  # noqa: E402  (.claude/skills/corpus-management/tools/ is on sys.path above)
# The suite's fixture scratch is the tree the linters' opt-in walk prunes
# (lint_common.TEST_SCRATCH_ROOT, tests/tmp at the repository root). It must stay
# outside .claude, which DEFAULT_EXEMPT_DIRS exempts even for an explicit argument
# (under .claude, the linters under test would scan 0 files).
FIXTURE_DIR = REPO_ROOT.joinpath(*_lint_common.TEST_SCRATCH_ROOT)
# Find the pack once at load, so every later sys.path snapshot already holds it.
import aiqt_bootstrap  # noqa: E402  (.claude/skills/corpus-management/tools/ is on sys.path above)
aiqt_bootstrap.ensure_on_path()


# The skill's tools directory at its shipped layout path relative to the
# repository root (.claude/skills/corpus-management/tools), derived from this
# file's own location. A fixture that runs a copy of a tool places it here:
# lint_common anchors REPO_ROOT four directories above the tool
# (Path(__file__).resolve().parents[4]), and the hooks and runners invoke the
# tools by this repository path, so a flat <fixture>/tools/ copy anchors
# outside the fixture repository.
SKILL_TOOLS_REL = (SKILL_ROOT / "tools").relative_to(REPO_ROOT)


def fixture_tools(root, *names):
    """The tools directory at the shipped layout path inside the fixture
    repository at ``root``, created if absent, holding byte copies of this
    skill's own ``names`` tools. Returns that directory."""
    tools = Path(root) / SKILL_TOOLS_REL
    tools.mkdir(parents=True, exist_ok=True)
    for name in names:
        (tools / name).write_bytes((SKILL_ROOT / "tools" / name).read_bytes())
    return tools


# The repository's committed AIQT pin record (.claude/aiqt/PIN.toml), derived
# from this file's own location through REPO_ROOT.
AIQT_PIN = REPO_ROOT / ".claude" / "aiqt" / "PIN.toml"


def fixture_aiqt_pin(root):
    """Byte copy of this repository's committed AIQT pin record at the same
    repository path inside the fixture repository at ``root``; returns it.
    A copied aiqt_bootstrap.py anchors its repository four directories above
    itself (the fixture root) and admits an AIQT_PACK_ROOT override only
    against that repository's .claude/aiqt/PIN.toml, read through real
    directories and a regular file (aiqt_bootstrap._repository_pin_path), so a
    fixture that runs a copied tool with the override needs the pin there."""
    target = Path(root) / AIQT_PIN.relative_to(REPO_ROOT)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(AIQT_PIN.read_bytes())
    return target


def fixture_git_environment():
    """This process's environment with every GIT_* variable dropped and
    global/system git config ignored, so a repository-local variable a
    caller leaks (a pre-commit hook's GIT_INDEX_FILE, a GIT_DIR) or an
    external git configuration cannot redirect a fixture repository's git
    commands."""
    env = {k: v for k, v in os.environ.items() if not k.startswith("GIT_")}
    env.update(GIT_CONFIG_NOSYSTEM="1", GIT_CONFIG_GLOBAL=os.devnull)
    return env


def hermetic_environment(home, tmpdir, **extra):
    """The whole environment of a fixture's guard, report or git, built here
    and not inherited: PATH is the one value taken from this process (it
    finds bash, git and python3); HOME and TMPDIR are the fixture's own
    directories, git reads no global or system configuration, and extra adds
    what the caller sets. Unlike fixture_git_environment, no other variable
    of this process (a store, a git setting or a fixture control variable)
    reaches the fixture."""
    env = {"PATH": os.environ.get("PATH", os.defpath), "HOME": str(home),
           "TMPDIR": str(tmpdir), "GIT_CONFIG_GLOBAL": os.devnull,
           "GIT_CONFIG_NOSYSTEM": "1"}
    env.update(extra)
    return env


