class CrossFileSectionRefTests(LinterTestCase):
    """.claude/skills/corpus-management/tools/lint-cross-file-section-refs.py (gate 62)

    The adjacent-link class: a §N reference with a markdown link to the
    target in the same clause must name a real numbered heading OR a
    line-initial inline clause (the canonical section model's citable
    non-heading identifiers) in the resolved target.
    """

    TARGET_BODY = (
        VALID_METADATA.replace("## Purpose", "## 1. Purpose")
        + "\n\n## 2. Scope\n\n2.1 The requirement statement this fixture makes citable.\n"
    )

    def test_stale_cross_file_ref_flagged(self) -> None:
        self.make_fixture("standard-xref-target.md", self.TARGET_BODY)
        citer = (
            VALID_METADATA
            + "\n\nSee [the target](standard-xref-target.md) §9.9 for the missing detail.\n"
        )
        fixture = self.make_fixture("standard-xref-citer.md", citer)
        result = run_linter(".claude/skills/corpus-management/tools/lint-cross-file-section-refs.py", fixture)
        self.assertLinterFails(result, "9.9")

    def test_resolving_heading_and_inline_clause_refs_pass(self) -> None:
        self.make_fixture("standard-xref-target.md", self.TARGET_BODY)
        citer = (
            VALID_METADATA
            + "\n\nSee [the target](standard-xref-target.md) §2 for scope and"
            + " [the target](standard-xref-target.md) §2.1 for the clause.\n"
        )
        fixture = self.make_fixture("standard-xref-citer.md", citer)
        result = run_linter(".claude/skills/corpus-management/tools/lint-cross-file-section-refs.py", fixture)
        self.assertEqual(
            result.returncode,
            0,
            f"resolving refs should pass.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}",
        )

    def test_stale_reference_in_table_cell_fails(self) -> None:
        self.make_fixture("standard-xref-target.md", self.TARGET_BODY)
        citer = VALID_METADATA + (
            "\n\n| Control | Detail |\n| --- | --- |\n"
            "| A | [target](standard-xref-target.md) §9.9 |\n"
        )
        fixture = self.make_fixture("standard-xref-citer.md", citer)
        result = run_linter(".claude/skills/corpus-management/tools/lint-cross-file-section-refs.py", fixture)
        self.assertLinterFails(result, "9.9")

    def test_resolving_reference_in_table_cell_passes(self) -> None:
        self.make_fixture("standard-xref-target.md", self.TARGET_BODY)
        citer = VALID_METADATA + (
            "\n\n| Control | Detail |\n| --- | --- |\n"
            "| A | [target](standard-xref-target.md) §2.1 |\n"
        )
        fixture = self.make_fixture("standard-xref-citer.md", citer)
        result = run_linter(".claude/skills/corpus-management/tools/lint-cross-file-section-refs.py", fixture)
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

    def test_escaped_and_code_span_pipes_stay_in_cell(self) -> None:
        self.make_fixture("standard-xref-target.md", self.TARGET_BODY)
        citer = VALID_METADATA + (
            "\n\n| Control | Detail |\n| --- | --- |\n"
            "| A | [target](standard-xref-target.md) \\| §9.9 |\n"
            "| B | [target](standard-xref-target.md) `a|b` §9.8 |\n"
        )
        fixture = self.make_fixture("standard-xref-citer.md", citer)
        result = run_linter(".claude/skills/corpus-management/tools/lint-cross-file-section-refs.py", fixture)
        self.assertLinterFails(result, "9.9")
        self.assertIn("9.8", result.stdout)

    def test_link_in_another_table_cell_does_not_bind(self) -> None:
        self.make_fixture("standard-xref-target.md", self.TARGET_BODY)
        citer = VALID_METADATA + (
            "\n\n| Control | Detail |\n| --- | --- |\n"
            "| [target](standard-xref-target.md) | §9.9 |\n"
        )
        fixture = self.make_fixture("standard-xref-citer.md", citer)
        result = run_linter(".claude/skills/corpus-management/tools/lint-cross-file-section-refs.py", fixture)
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

    def test_local_table_section_before_following_link_is_not_cross_file(self) -> None:
        self.make_fixture("standard-xref-target.md", self.TARGET_BODY)
        citer = VALID_METADATA + (
            "\n\n## 8. Exceptions\n\n| Role | Detail |\n| --- | --- |\n"
            "| Owner | Section 8 exception path ([policy](standard-xref-target.md) §2) |\n"
        )
        fixture = self.make_fixture("standard-xref-citer.md", citer)
        result = run_linter(".claude/skills/corpus-management/tools/lint-cross-file-section-refs.py", fixture)
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

    def test_table_local_exception_requires_description_and_close(self) -> None:
        # The target lacks section 8, so a row the local-section exception
        # does not cover is read as a citation of the target and fails.
        self.make_fixture("t.md", self.TARGET_BODY + "\n\n## 4. Other\n")
        for line, should_fail in (
            ("| Owner | §8 ([t](t.md)) |", True),
            ("| Owner | Section 8 ([t](t.md)) |", True),
            ("| Owner | §8 of the target ([t](t.md)) |", True),
            ("| Owner | Section 8 exception path ([policy](t.md) §2) |", False),
            ("| Owner | Section 8 exception path ([policy](t.md) §2 |", True),
            # A nested parenthetical inside a closed exception path is
            # balanced, so the path is closed and the row stays local.
            ("| Owner | Section 8 exception path ([policy](t.md) (see §2)) |", False),
        ):
            with self.subTest(line=line):
                citer = VALID_METADATA + f"\n\n## 8. Exceptions\n\n{line}\n"
                fixture = self.make_fixture("standard-table-exception-cross-ref.md", citer)
                result = run_linter(".claude/skills/corpus-management/tools/lint-cross-file-section-refs.py", fixture)
                if should_fail:
                    self.assertLinterFails(result, "§8")
                else:
                    self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        # The target now holds section 8, so a row read as a citation of the
        # target resolves (the first row shows it); a row whose exception
        # path leaves its parenthesis unclosed still fails, by its own refusal.
        self.make_fixture("t.md", self.TARGET_BODY + "\n\n## 4. Other\n\n## 8. Exceptions\n")
        for line, should_fail in (
            ("| Owner | §8 ([t](t.md)) |", False),
            ("| Owner | Section 8 exception path ([policy](t.md) §2) |", False),
            ("| Owner | Section 8 exception path ([policy](t.md) §2 |", True),
            ("| Owner | Section 8 exception path ([policy](t.md) (see §2)) |", False),
            # The link target "(t.md)" and the nested parenthetical close,
            # but nothing closes the parenthesis opened before the link.
            ("| Owner | Section 8 exception path ([policy](t.md) (see §2) |", True),
        ):
            with self.subTest(line=line, target_holds_section_8=True):
                citer = VALID_METADATA + f"\n\n## 8. Exceptions\n\n{line}\n"
                fixture = self.make_fixture("standard-table-exception-cross-ref.md", citer)
                result = run_linter(".claude/skills/corpus-management/tools/lint-cross-file-section-refs.py", fixture)
                if should_fail:
                    self.assertLinterFails(result, "§8")
                    self.assertIn("no closing parenthesis", result.stdout)
                else:
                    self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

    def test_of_the_policy_table_residual_passes(self) -> None:
        self.make_fixture("t.md", self.TARGET_BODY)
        citer = VALID_METADATA + "\n\n## 8. Exceptions\n\n| Owner | §8 of the policy ([t](t.md)) |\n"
        fixture = self.make_fixture("standard-cross-file-residual.md", citer)
        result = run_linter(".claude/skills/corpus-management/tools/lint-cross-file-section-refs.py", fixture)
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

    def test_table_row_without_leading_pipe_residual_is_reported(self) -> None:
        # Documented residual: the local-section exception applies only to a
        # line beginning with a pipe, so for that exception this valid row is
        # read as prose, while its cells are still split and checked.
        self.make_fixture("t.md", self.TARGET_BODY)
        citer = VALID_METADATA + (
            "\n\n## 8. Exceptions\n\nRole | Detail\n--- | ---\n"
            "Owner | Section 8 exception path ([policy](t.md) §2)\n"
        )
        fixture = self.make_fixture("standard-cross-file-residual.md", citer)
        result = run_linter(".claude/skills/corpus-management/tools/lint-cross-file-section-refs.py", fixture)
        self.assertLinterFails(result, "§8")
        self.assertNotIn("§2 ", result.stdout)

    def test_local_prose_section_before_following_link_is_checked(self) -> None:
        self.make_fixture("standard-xref-target.md", self.TARGET_BODY)
        citer = (VALID_METADATA + "\n\n## 8. Exceptions\n\n"
                 + "See Section 8 of [t](standard-xref-target.md) for details.\n")
        fixture = self.make_fixture("standard-xref-citer.md", citer)
        self.assertLinterFails(run_linter(".claude/skills/corpus-management/tools/lint-cross-file-section-refs.py", fixture), "§8")

    def test_unmatched_and_code_backticks_do_not_join_table_cells(self) -> None:
        self.make_fixture("standard-xref-target.md", self.TARGET_BODY)
        citer = (VALID_METADATA + "\n\n| Note | Target | Reference |\n"
                 + "| --- | --- | --- |\n"
                 + "| stray ` tick | [t](standard-xref-target.md) | §9 |\n"
                 + "| `C:\\` | [t](standard-xref-target.md) | §9 |\n")
        fixture = self.make_fixture("standard-xref-citer.md", citer)
        result = run_linter(".claude/skills/corpus-management/tools/lint-cross-file-section-refs.py", fixture)
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)


