    def test_pr_2697_replay_against_historical_register(self) -> None:
        # In the earlier repository a pull request added these two sentences (abridged from
        # its compliance/annex-nis-2-implementation.md line 29) with no register row for
        # either instrument. This fixed register fixture lacks both numbers regardless of
        # later rows.
        prose = (
            "An entity of a type in Annex I is an essential entity where it exceeds the ceilings "
            "for medium-sized enterprises provided for in Article 2(1) of the Annex to Commission "
            "Recommendation 2003/361/EC (Article 3(1)(a)). Essential status also attaches to "
            "critical entities under Directive (EU) 2022/2557.\n"
        )
        out = self._check("# NIS 2\n\nIntro.\n", "# NIS 2\n\nIntro.\n\n" + prose)
        warned = "\n".join(self._warned(out))
        for observed, number in (
            ("Commission Recommendation 2003/361/EC", "2003/361"),
            ("Directive (EU) 2022/2557", "2022/2557"),
        ):
            with self.subTest(number=number):
                self.assertIn(f"EU/EC instrument number '{observed}'", warned, out)

    # The sibling probe: when a PR changes the alias file or the register, D15 lists every
    # unregistered alignment-table citation already in the corpus that shares a distinctive
    # token with a changed alias key or register Standard ID. In the earlier repository a pull
    # request's first version aliased "US TSA Pipeline Security Directives" while the sibling
    # row "US TSA Rail Cybersecurity Directives" kept warning.
    ALIASES = ".claude/skills/corpus-management/tools/alignment-register-aliases.json"
    TSA_ROWS = ROWS + (("TSA Pipeline Security Directive", "SD Pipeline-2021-02G", "-"),)
    SIBLING_DOC = (
        "| US TSA Pipeline Security Directives | TSA SDs | Pipelines |",
        "| US TSA Rail Cybersecurity Directives | TSA SDs | Rail |",
        "| ACME Security Directives | Guidance | Generic |",
        "| ISACA DTEF | Assurance | Audit |",
    )

    @staticmethod
    def _aliases(*keys, target="TSA Pipeline Security Directive", **sections):
        import json

        return json.dumps({
            "schema_version": 1,
            "aliases": {k: target for k in keys},
            **sections,
        }, indent=2) + "\n"

    def _probe(self, base_extra, head_extra, doc=None, deleted=()):
        """Run D15 on a PR whose corpus document is unchanged (present at the base) and whose
        other changes are ``head_extra`` (and the deletion of ``deleted``); returns stdout."""
        doc = doc or self._doc(*self.SIBLING_DOC)
        base = {self.DOC: doc, **base_extra}
        tmp, base_sha, shutil = self._build_repo(base, head_extra, head_deleted=deleted)
        try:
            result = self._run_gate(self.SCRIPT, tmp, base_sha)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)
        self.assertEqual(
            result.returncode, 0,
            f"D15 is advisory and must exit 0.\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}",
        )
        self.assertNotIn("Traceback", result.stderr, result.stderr)
        return result.stdout

    @staticmethod
    def _siblings(out):
        return [line for line in out.splitlines() if line.startswith("D15 SIBLING ")]

    def test_sibling_probe_lists_other_form_of_aliased_instrument(self) -> None:
        register = self._register(self.TSA_ROWS)
        out = self._probe(
            {self.REGISTER: register, self.ALIASES: self._aliases("TSA Pipeline Security Directives")},
            {self.ALIASES: self._aliases(
                "TSA Pipeline Security Directives", "US TSA Pipeline Security Directives",
            )},
        )
        listed = self._siblings(out)
        self.assertEqual(len(listed), 1, out)
        self.assertIn("security/standard-example.md:8:", listed[0])
        self.assertIn("'US TSA Rail Cybersecurity Directives'", listed[0])
        self.assertIn("'tsa'", listed[0])
        self.assertIn("alias key 'US TSA Pipeline Security Directives'", listed[0])
        # A row sharing only stop-list words ("Security", "Directives") and an unregistered
        # row sharing nothing are not listed; the residual is printed beside the result.
        self.assertNotIn("ACME", out)
        self.assertNotIn("ISACA DTEF", out)
        self.assertIn("D15 SIBLING-PROBE: 1 unregistered", out)
        self.assertIn("sharing no distinctive token", out)
        self.assertEqual(self._warned(out), [], out)

    def test_sibling_probe_lists_the_whole_corpus_from_a_subdirectory(self) -> None:
        # Without --full-tree, ls-tree lists only the invocation directory: in the earlier
        # repository, run from governance/ or .claude/skills/corpus-management/tools/, the probe
        # listed no corpus document outside it.
        import subprocess as sp

        base = {self.DOC: self._doc(*self.SIBLING_DOC), self.REGISTER: self._register(self.TSA_ROWS),
                self.ALIASES: self._aliases("TSA Pipeline Security Directives")}
        head = {self.ALIASES: self._aliases(
            "TSA Pipeline Security Directives", "US TSA Pipeline Security Directives",
        )}
        tmp, base_sha, shutil = self._build_repo(base, head)
        try:
            for sub in ("governance", ".claude/skills/corpus-management/tools"):
                result = sp.run(
                    [sys.executable, str(SKILL_ROOT / "tools" / self.SCRIPT), base_sha, "HEAD"],
                    capture_output=True, text=True, cwd=str(tmp / sub),
                )
                self.assertEqual(result.returncode, 0, sub + ": " + result.stdout + result.stderr)
                listed = self._siblings(result.stdout)
                self.assertEqual(len(listed), 1, sub + ": " + result.stdout)
                self.assertIn("security/standard-example.md:8:", listed[0])
                self.assertIn("D15 SIBLING-PROBE: 1 unregistered", result.stdout)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

