            "import sys\n"
            "sys.path.insert(0, sys.argv[1])\n"
            "import lint_common\n"
            "try:\n"
            "    lint_common.resolve_pr_range('origin/main', 'HEAD')\n"
            "except lint_common.PrRangeError as exc:\n"
            "    print('RAISED:', exc)\n"
