    def test_narrative_boundary_corpus_types_parity(self) -> None:
        """Gate 86's CORPUS_DOCUMENT_TYPES must stay byte-equal to the corpus metadata gate's
        ALLOWED_TYPES (it mirrors it to reject corpus types inside executive/). A drift between the
        two would let a newly-added corpus document type slip past the boundary gate; this parity
        test is the drift guard (in lieu of a lint_common hoist)."""
        import importlib.util
        tools = SKILL_ROOT / "tools"
        def _load(name, fname):
            spec = importlib.util.spec_from_file_location(name, tools / fname)
            mod = importlib.util.module_from_spec(spec)
            sys.path.insert(0, str(tools))
            try:
                spec.loader.exec_module(mod)
            finally:
                sys.path.remove(str(tools))
            return mod
        bnd = _load("bnd_mod", "lint-narrative-boundary.py")
        meta = _load("meta_mod", "lint-metadata.py")
        self.assertEqual(set(bnd.CORPUS_DOCUMENT_TYPES), set(meta.ALLOWED_TYPES),
                         "lint-narrative-boundary CORPUS_DOCUMENT_TYPES has drifted from "
                         "lint-metadata ALLOWED_TYPES; keep them in parity.")

    def test_narrative_boundary_open_fence_at_eof_fails_loud(self) -> None:
        """Gate 86 keeps its fence skip (it protects fenced example metadata), so a file that
        ends inside an open fence would silently leave its remainder unscanned. The gate now
        reports it, naming the opener line; a closed fence still passes."""
        import importlib.util
        tools = SKILL_ROOT / "tools"
        spec = importlib.util.spec_from_file_location("bnd_eof_mod", tools / "lint-narrative-boundary.py")
        bnd = importlib.util.module_from_spec(spec)
        sys.path.insert(0, str(tools))
        try:
            spec.loader.exec_module(bnd)
        finally:
            sys.path.remove(str(tools))
        td = Path(tempfile.mkdtemp(prefix="nb-open-fence-"))
        self.addCleanup(shutil.rmtree, td)
        leak = "**Document Type:** Executive Narrative\\\n"
        opened = td / "open.md"
        # a 4-backtick opener is not closed by a 3-backtick line, so the fence stays open
        opened.write_text("# D\n\n````\nexample\n```\n" + leak, encoding="utf-8")
        findings = bnd.scan_outside_file(opened, "governance/open.md")
        self.assertEqual(len(findings), 1, findings)
        self.assertIn("governance/open.md:L3: the file ends inside the fence opened here", findings[0])
        closed = td / "closed.md"
        closed.write_text("# D\n\n````\n" + leak + "````\n\nProse.\n", encoding="utf-8")
        self.assertEqual(bnd.scan_outside_file(closed, "governance/closed.md"), [])

