    def test_real_git_aliases_main_and_linked(self):
        remote = self.real_remote()
        (self.root / ".web/build.py").write_text("raise SystemExit(19)\n")
        self.commit_fixture()
        main = self.root
        hook = main / ".git/hooks/pre-push"
        installed = hook.read_bytes()
        tracked = (main / ".claude/skills/corpus-management/tools/git-hooks/pre-push").read_bytes()
        other = Path(self.tmp.name) / "alias-tree"
        (other / ".claude/skills/corpus-management/tools/git-hooks").mkdir(parents=True)
        (other / ".claude/skills/corpus-management/tools/git-hooks/pre-push").write_text(
            '#!/bin/sh\necho REDIRECTED_HOOK >&2\nexit 0\n'
            'python3 -I .claude/skills/corpus-management/tools/pre-push-hook.py "$@" < "$refs"\n')
        (other / ".claude/skills/corpus-management/tools/pre-push-hook.py").touch()
        for checkout in self.main_and_linked():
            root = self.root
            for alias in ("symlink", "hardlink"):
                # Directories cannot be hard linked. Use the linked gitfile
                # for both entry points, including --work-tree from main.
                source = root / ".git" if alias == "symlink" else Path(self.tmp.name) / "linked/.git"
                if alias == "symlink":
                    (other / ".git").symlink_to(source)
                else:
                    os.link(source, other / ".git")
                try:
                    for dispatcher, body in (("installed", installed), ("tracked", tracked)):
                        hook.write_bytes(body)
                        for entry in ("option", "environment", "cwd"):
                            with self.subTest(checkout=checkout, alias=alias,
                                              dispatcher=dispatcher, entry=entry):
                                saved = self.env.copy()
                                prefix = ["git"]
                                if entry == "option":
                                    prefix += ["--work-tree", str(other)]
                                elif entry == "environment":
                                    self.env["GIT_WORK_TREE"] = str(other)
                                else:
                                    self.root = other
                                ref = "refs/heads/" + "-".join((checkout, alias, dispatcher, entry))
                                try:
                                    result = self.run_cmd(*prefix, "push", "upstream", "HEAD:" + ref, code=1)
                                    self.assertIn("refusing redirected work tree", result.stderr)
                                    self.assertNotIn("REDIRECTED_HOOK", result.stdout + result.stderr)
                                finally:
                                    self.env = saved
                                    self.root = root
                                self.run_cmd("git", "--git-dir", str(remote), "show-ref",
                                             "--verify", "--quiet", ref, code=1)
                finally:
                    (other / ".git").unlink()
                    hook.write_bytes(installed)

    def test_real_commondir_alias(self):
        # A tree whose .git directory has a commondir file naming this
        # checkout's git directory pushes this checkout's refs, and git
        # runs the hook in that common directory. The tracked hook refuses
        # it; in the earlier repository, an earlier version of it accepted
        # the alias and went on to run the alias's own tree. Only the
        # tracked dispatcher is run here: the installed dispatcher (v7,
        # .claude/skills/corpus-management/tools/install-git-hooks.sh)
        # keeps the earlier check, accepts the alias and runs the alias's
        # own tracked hook (a disclosed residual). An alias that links only
        # objects and refs has its own hooks directory, so no hook of this
        # checkout runs there; a git-new-workdir checkout also links hooks,
        # so this checkout's hook runs from it and refuses, naming that
        # layout (another earlier version refused without naming it). The
        # workdir is emulated (config, refs, objects, info, hooks and
        # packed-refs linked): the contrib script is not installed here.
        remote = self.real_remote()
        main = self.root
        hook = main / ".git/hooks/pre-push"
        installed = hook.read_bytes()
        hook.write_bytes((main / ".claude/skills/corpus-management/tools/git-hooks/pre-push").read_bytes())
        try:
            for layout in ("commondir", "git-new-workdir"):
                other = Path(self.tmp.name) / (layout + "-tree")
                (other / ".claude/skills/corpus-management/tools/git-hooks").mkdir(parents=True)
                (other / ".claude/skills/corpus-management/tools/git-hooks/pre-push").write_text(
                    '#!/bin/sh\necho REDIRECTED_HOOK >&2\nexit 0\n'
                    'python3 -I .claude/skills/corpus-management/tools/pre-push-hook.py "$@" < "$refs"\n')
                (other / ".claude/skills/corpus-management/tools/pre-push-hook.py").touch()
                (other / ".git").mkdir()
                (other / ".git/HEAD").write_bytes((main / ".git/HEAD").read_bytes())
                if layout == "commondir":
                    (other / ".git/commondir").write_text(str(main / ".git") + "\n")
                else:
                    for part in ("config", "refs", "objects", "info", "hooks", "packed-refs"):
                        if (main / ".git" / part).exists():
                            (other / ".git" / part).symlink_to(main / ".git" / part)
                ref = "refs/heads/" + layout
                self.root = other
                try:
                    with self.subTest(layout=layout):
                        result = self.run_cmd("git", "push", "upstream", "HEAD:" + ref, code=1)
                        self.assertIn("refusing redirected work tree", result.stderr)
                        self.assertNotIn("REDIRECTED_HOOK", result.stdout + result.stderr)
                        if layout == "git-new-workdir":
                            self.assertIn("a git-new-workdir checkout", result.stderr)
                finally:
                    self.root = main
                self.run_cmd("git", "--git-dir", str(remote), "show-ref",
                             "--verify", "--quiet", ref, code=1)
        finally:
            hook.write_bytes(installed)

    def test_reftable_linked_tables_refused(self):
        # A reftable clone whose reftable is a directory but whose tables.list
        # and tables are symbolic links into another reftable repository reads
        # that repository's refs; in the earlier repository, the tracked hook
        # passed it. An ordinary reftable clone still passes.
        main = self.root
        table, alias = Path(self.tmp.name) / "table", Path(self.tmp.name) / "table-alias"
        result = subprocess.run(["git", "clone", "-q", "--ref-format=reftable", str(main), str(table)],
                                cwd=main, env=self.env, capture_output=True, text=True, timeout=30)
        if result.returncode:
            self.skipTest("reftable unavailable: " + result.stderr.strip())
        self.run_cmd("git", "clone", "-q", "--ref-format=reftable", str(main), str(alias))
        try:
            self.root = table
            self.push(remote="fork", url="/other/repo.git")
            self.run_cmd("git", "-c", "user.email=t@t", "-c", "user.name=t",
                         "commit", "-q", "--allow-empty", "-m", "y")
            for entry in list((alias / ".git/reftable").iterdir()):
                entry.unlink()
            for entry in (table / ".git/reftable").iterdir():
                (alias / ".git/reftable" / entry.name).symlink_to(entry)
            self.root = alias
            self.assertEqual(self.run_cmd("git", "rev-parse", "HEAD").stdout,
                             subprocess.run(["git", "-C", str(table), "rev-parse", "HEAD"], env=self.env,
                                            capture_output=True, text=True, check=True).stdout)
            result = self.push(code=1, remote="fork", url="/other/repo.git")
            # The walk for symlinks names the first linked entry (a table
            # sorts before tables.list).
            reftable = str((alias / ".git/reftable").resolve())
            self.assertIn("pre-push: refusing " + reftable + "/", result.stderr)
            self.assertIn(": it is a symlink", result.stderr)
            self.assertIn("keep " + reftable + " free of symlinks", result.stderr)
        finally:
            self.root = main

    def test_real_redirect_variables_main_and_linked(self):
        # In the earlier repository, with GIT_OBJECT_DIRECTORY naming a
        # clone's objects, git pushed through the installed and tracked hooks
        # while reading that clone's object store; so did
        # GIT_ALTERNATE_OBJECT_DIRECTORIES, GIT_GRAFT_FILE and
        # GIT_SHALLOW_FILE, which git 2.53 exported to no pre-push hook, and
        # GIT_INDEX_FILE naming the clone's index. Each push now refuses in
        # the tracked hook, naming the variable, and pushes nothing, where
        # the earlier hook pushed all five. GIT_INDEX_FILE naming the
        # checkout's own index still pushes. GIT_COMMON_DIR is not pushed
        # here: git then takes config and hooks from that common dir, so no
        # hook of this checkout runs (LintCommonHelperTests runs the hook
        # with it).
        remote = self.real_remote()
        clone = Path(self.tmp.name) / "objects-clone"
        self.run_cmd("git", "clone", "-q", str(self.root), str(clone))
        head = self.run_cmd("git", "rev-parse", "HEAD").stdout.strip()
        for name in ("grafts", "shallow"):
            (Path(self.tmp.name) / name).write_text(head + "\n")
        values = {"GIT_OBJECT_DIRECTORY": clone / ".git/objects",
                  "GIT_ALTERNATE_OBJECT_DIRECTORIES": clone / ".git/objects",
                  "GIT_GRAFT_FILE": Path(self.tmp.name) / "grafts",
                  "GIT_SHALLOW_FILE": Path(self.tmp.name) / "shallow",
                  "GIT_INDEX_FILE": clone / ".git/index"}
        for checkout in self.main_and_linked():
            for name, value in values.items():
                with self.subTest(checkout=checkout, variable=name):
                    saved = self.env.copy()
                    self.env[name] = str(value)
                    ref = "refs/heads/" + checkout + "-" + name.lower()
                    try:
                        result = self.run_cmd("git", "push", "upstream", "HEAD:" + ref, code=1)
                        self.assertIn("pre-push: refusing " + name, result.stderr)
                        self.assertNotIn("guard 1/3", result.stdout)
                    finally:
                        self.env = saved
                    self.run_cmd("git", "--git-dir", str(remote), "show-ref",
                                 "--verify", "--quiet", ref, code=1)
            git_dir = Path(self.run_cmd("git", "rev-parse", "--absolute-git-dir").stdout.strip())
            saved = self.env.copy()
            self.env["GIT_INDEX_FILE"] = str(git_dir / "index")
            try:
                self.assert_layout_pushes(remote, checkout + "-own-index")
            finally:
                self.env = saved

    def assert_layout_pushes(self, remote, label):
        ref = "refs/heads/" + label
        result = self.run_cmd("git", "push", "upstream", "HEAD:" + ref)
        self.assertIn("Safe to push", result.stdout)
        self.assertEqual(self.run_cmd("git", "--git-dir", str(remote), "rev-parse", ref).stdout,
                         self.run_cmd("git", "rev-parse", "HEAD").stdout)
        (self.root / "fail").touch()
        try:
            result = self.run_cmd("git", "push", "upstream", "HEAD:" + ref + "-blocked", code=1)
            self.assertIn("FAILED at run_all_audits.sh", result.stdout)
            self.run_cmd("git", "--git-dir", str(remote), "show-ref",
                         "--verify", "--quiet", ref + "-blocked", code=1)
        finally:
            (self.root / "fail").unlink()

