        (self.root / ".claude/skills/corpus-management/tools" / "fixture-echo.py").write_text(
            "import os\nimport sys\n"
            "with open('ran.log', 'a') as f:\n"
            "    f.write(' '.join(sys.argv) + '\\n')\n"
            "print('DUE-SOON  fixture band')\n"
            "token = os.environ.get('GRC_RUNNER_ECHO_TOKEN', '')\n"
            "if token:\n"
            "    print(\"runner-echo: .claude/skills/corpus-management/tools/run_all_audits.sh shows this \"\n"
            "          \"gate's advisory lines on a pass \" + token)\n"
            "print('WARN fixture warn line')\n"
            "print('NOTE fixture note line')\n",
            encoding="utf-8")
        (self.root / ".claude/skills/corpus-management/tools" / "fixture-silent.py").write_text(
            "print('WARN unopted warn line')\n", encoding="utf-8")
