    def test_full_guard_runs_gate_36_as_six_isolated_local_shards(self):
        # FLIP TABLE: each local shard runs in its OWN temporary detached
        # checkout of the commit being pushed, so one shard's tests/tmp
        # fixtures are never seen by another; two shards sharing a working
        # tree (or running in this clone's) fail here. A passing run
        # removes every checkout and the shard directory.
        self.change("ai/policy-fixture.md")
        head = self.git("rev-parse", "HEAD").stdout.strip()
        result, _ran = self.run_guard()
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        runs = self.shard_runs()
        self.assertEqual(sorted(run["argv"][2] for run in runs),
                         ["%d/6" % i for i in range(1, 7)])
        trees = [run["cwd"] for run in runs]
        self.assertEqual(len(set(trees)), 6, trees)
        self.assertNotIn(os.path.realpath(self.root), trees)
        for run in runs:
            with self.subTest(shard=run["argv"][2]):
                index = run["argv"][2].split("/")[0]
                self.assertEqual(run["seen"], ["shard-" + index],
                                 "a shard saw another shard's tests/tmp fixture")
                self.assertEqual(run["head"], head)
                self.assertTrue(run["cwd"].startswith(
                    os.path.realpath(self.shard_tmp) + os.sep), run["cwd"])
                self.assertEqual(os.path.basename(run["cwd"]), "repo")
                self.assertTrue(os.path.realpath(run["output"]).startswith(
                    os.path.dirname(run["cwd"]) + os.sep), run["output"])
                # No sibling exists beside this fixture clone, so none is linked.
                self.assertEqual(run["links"], {})
        for i in range(1, 7):
            self.assertRegex(result.stdout,
                             r"gate 36 local shard %d/6: rc=0; Ran 1 test in " % i)
        self.assertIn("OK: every needed job succeeded, the 6 shards discovered one "
                      "unit set", result.stdout)
        self.assertIn("gate 36 passed as 6 local shards", result.stdout)
        self.assertEqual(os.listdir(self.shard_tmp), [])
        worktrees = self.git("worktree", "list", "--porcelain").stdout
        self.assertEqual(worktrees.count("worktree "), 1, worktrees)

    def test_full_guard_shards_reach_this_clones_store_and_siblings(self):
        # FLIP TABLE: each shard checkout's parent links to this clone's own
        # store and siblings, and a relative GRC_STORE is made absolute, so
        # the store is reachable from a shard as it is for the serial run.
        # Each of the four siblings is a symbolic link to this clone's own
        # sibling, by its absolute physical path, and nothing else sits
        # beside a checkout but its log and output files; the passing run's
        # cleanup removes the links as links, so every file in the linked
        # store and siblings survives it.
        parent = Path(self.tmp.name)
        siblings = ("private", "grc_library_private", "grc_library_ref", "grc_library_scratch")
        # With a private store present the guard's install-git-hooks.sh
        # --check requires the installed hook, so this clone installs it.
        for name in ("git-hooks/pre-push", "pre-push-hook.py", "check-dirty-tree-push.py"):
            dest = self.root / ".claude/skills/corpus-management/tools" / name
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(SKILL_ROOT / "tools" / name, dest)
        self.move_base("Hook files")
        subprocess.run(["sh", ".claude/skills/corpus-management/tools/install-git-hooks.sh"], cwd=self.root, env=self.env,
                       check=True, capture_output=True, text=True, timeout=30)
        for name in siblings:
            (parent / name / "nested").mkdir(parents=True)
            (parent / name / "keep.md").write_text(name + "\n", encoding="utf-8")
            (parent / name / "nested" / "keep.md").write_text(name + "\n", encoding="utf-8")
        self.change("ai/policy-fixture.md")
        result, _ran = self.run_guard(GRC_STORE="../private")
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        runs = self.shard_runs()
        self.assertEqual(len(runs), 6)
        for run in runs:
            with self.subTest(shard=run["argv"][2]):
                self.assertEqual(run["siblings"], {
                    name: os.path.realpath(parent / name)
                    for name in ("private", "grc_library_private", "grc_library_ref")})
                self.assertEqual(run["links"], {
                    name: os.path.join(os.path.realpath(parent), name) for name in siblings})
                self.assertEqual(run["beside"], sorted(
                    ["github-output", "repo", "shard.log", "worktree.log", *siblings]))
                self.assertEqual(os.path.realpath(run["store"]),
                                 os.path.realpath(parent / "private"))
                self.assertTrue(os.path.isabs(run["store"]), run["store"])
        self.assertIn("the shard checkouts were removed", result.stdout)
        self.assertEqual(os.listdir(self.shard_tmp), [])
        for name in siblings:
            with self.subTest(survives=name):
                self.assertEqual((parent / name / "keep.md").read_text(encoding="utf-8"), name + "\n")
                self.assertEqual((parent / name / "nested" / "keep.md").read_text(encoding="utf-8"),
                                 name + "\n")

    # test_interrupt_stops_every_shard_group_and_keeps_the_checkouts runs
    # its guard under this launcher. The launcher makes itself the child
    # subreaper (prctl PR_SET_CHILD_SUBREAPER, 36), starts argv[2:] (the
    # guard), passes SIGINT on to it, reaps the guard and every orphan of
    # its run, writes the guard's pid and then "pid signal" for each orphan
    # a signal ended to argv[1], and, once the guard has ended, reaps for
    # up to 60 more seconds until no child is left; it exits with the
    # guard's status (128 + its signal if a signal ended it). In the case
    # that test covers, a SIGINT during the shard step, the guard's INT
    # trap in .claude/skills/corpus-management/tools/pre-push-guard.sh
    # (shard_interrupted INT 130, which ends through shard_fail) makes the
    # guard exit 130, and the test compares the launcher's exit status with
    # the 130 it expects.
    # When prctl is refused, as a seccomp profile may refuse it, the
    # launcher starts nothing, writes "SKIP: prctl(PR_SET_CHILD_SUBREAPER)
    # failed: " and, as the reason, the text of the errno to argv[1] and
    # exits 77, and the test is skipped with that reason before that
    # comparison, so the cause is given rather than a failure that does not
    # name it.
    SUBREAPER = (
        "import ctypes, os, signal, subprocess, sys, time\n"
        "if ctypes.CDLL(None, use_errno=True).prctl(36, 1, 0, 0, 0):\n"
        "    with open(sys.argv[1], 'w', encoding='utf-8') as refused:\n"
        "        refused.write('SKIP: prctl(PR_SET_CHILD_SUBREAPER) failed: %s\\n'\n"
        "                      % os.strerror(ctypes.get_errno()))\n"
        "    sys.exit(77)\n"
        "guard = subprocess.Popen(sys.argv[2:])\n"
        "def forward(_signum, _frame):\n"
        "    try:\n"
        "        os.kill(guard.pid, signal.SIGINT)\n"
        "    except ProcessLookupError:\n"
        "        pass\n"
        "signal.signal(signal.SIGINT, forward)\n"
        "status = deadline = None\n"
        "with open(sys.argv[1], 'w', encoding='ascii') as log:\n"
        "    log.write('%d\\n' % guard.pid)\n"
        "    while True:\n"
        "        try:\n"
        "            pid, how = os.waitpid(-1, 0 if status is None else os.WNOHANG)\n"
        "        except ChildProcessError:\n"
        "            break\n"
        "        if pid == guard.pid:\n"
        "            status, deadline = how, time.monotonic() + 60\n"
        "        elif pid:\n"
        "            if os.WIFSIGNALED(how):\n"
        "                log.write('%d %d\\n' % (pid, os.WTERMSIG(how)))\n"
        "        elif time.monotonic() >= deadline:\n"
        "            break\n"
        "        else:\n"
        "            time.sleep(0.05)\n"
        "sys.exit(os.WEXITSTATUS(status) if os.WIFEXITED(status) else 128 + os.WTERMSIG(status))\n")

    def test_interrupt_stops_every_shard_group_and_keeps_the_checkouts(self):
        # FLIP TABLE: SIGINT to a guard running stub shards stops each shard's
        # own process group (a shard and the child it started), waits for
        # them, keeps and names every checkout and log, and exits 130; no
        # later step runs. The guard starts with INT, TERM and HUP at their
        # defaults, as from a terminal: bash cannot trap a signal that was
        # ignored when it started.
        # Each shard's child holds the release FIFO itself, with its stdin
        # from /dev/null, so its shard's end does not end it. With no group
        # signal at all, the children outlive the run, which the checks of
        # each group below refuse; and a child that ends when its shard does
        # fails the /proc checks below. This test does not refuse the guard's
        # KILL after its grace (9 to 10 seconds of SECONDS), which a host
        # stall after the TERM would bring. It tells a TERM to each shard's
        # group from a TERM to each shard alone by how each child ended, not
        # by time. The guard runs under SUBREAPER, a launcher (isolated
        # Python) that makes itself the child subreaper, so it reaps each
        # child its shard's end orphans, and writes "pid signal" for each
        # process it reaps that a signal ended. A child keeps SIGTERM's
        # default action and the guard knows only its shard's pid, so only a
        # signal to the shard's group reaches it; the first fatal signal sent
        # to it decides how it ends. A child the guard's group TERM ended
        # reports SIGTERM however slow the host is; with a TERM to each shard
        # pid alone, the child lives on and ends only at the guard's group
        # KILL after its grace, and reports SIGKILL. While the shards are
        # held, /proc shows that each child runs isolated (-I) with this
        # fixture's built environment (Python may add LC_CTYPE, PEP 538).
        import signal
        import time
        self.change("ai/policy-fixture.md")
        marks = Path(self.tmp.name) / "hang"
        hang = self.hold_shards(marks)
        release = hang["FIXTURE_SHARD_RELEASE"]
        out_path = Path(self.tmp.name) / "guard.out"

        def default_signals():
            for number in (signal.SIGINT, signal.SIGTERM, signal.SIGHUP):
                signal.signal(number, signal.SIG_DFL)

        reaped_log = Path(self.tmp.name) / "reaped.log"
        with open(out_path, "w", encoding="utf-8") as out:
            guard = subprocess.Popen([sys.executable, "-I", "-c", self.SUBREAPER, str(reaped_log),
                                      "bash", ".claude/skills/corpus-management/tools/pre-push-guard.sh"],
                                     cwd=self.root, env=dict(self.env, **hang),
                                     stdin=subprocess.DEVNULL, stdout=out,
                                     stderr=subprocess.STDOUT, preexec_fn=default_signals)
        try:
            deadline = time.monotonic() + 60
            while (len(self.shard_records(marks)) < 6
                   and guard.poll() is None and time.monotonic() < deadline):
                time.sleep(0.1)
            # A host that refuses the launcher's prctl skips this test,
            # with the reason the launcher wrote (SUBREAPER).
            if guard.poll() == 77 and reaped_log.exists():
                refused = reaped_log.read_text(encoding="utf-8", errors="replace")
                if refused.startswith("SKIP: "):
                    self.skipTest("this test needs its launcher to be the child subreaper, "
                                  "which this host refuses: " + refused[len("SKIP: "):].strip())
            started = sorted(m.name for m in marks.iterdir() if re.fullmatch(r"shard-\d+", m.name))
            self.assertEqual(started, ["shard-%d" % i for i in range(1, 7)],
                             out_path.read_text(encoding="utf-8"))
            for _pid, _pgid, child in self.shard_records(marks):
                with self.subTest(child=child):
                    cmdline = self.proc_bytes(int(child), "cmdline").split(b"\0")
                    self.assertEqual(cmdline[1:3], [b"-I", b"-c"], cmdline)
                    self.assertEqual(cmdline[4:5], [os.fsencode(release)], cmdline)
                    environ = self.proc_bytes(int(child), "environ").split(b"\0")
                    self.assertEqual(
                        sorted(e for e in environ if e and not e.startswith(b"LC_CTYPE=")),
                        sorted(os.fsencode("%s=%s" % item) for item in self.env.items()),
                        "the shard's child does not run with this fixture's environment")
                    fds = Path("/proc/%s/fd" % child)
                    self.assertEqual(os.readlink(fds / "0"), os.devnull)
                    self.assertIn(os.path.realpath(release),
                                  [os.readlink(fd) for fd in fds.iterdir()])
            guard.send_signal(signal.SIGINT)
            rc = guard.wait(timeout=120)
        finally:
            self.stop_guard(guard)
        output = out_path.read_text(encoding="utf-8")
        self.assertEqual(rc, 130, output)
        reaped = reaped_log.read_text(encoding="ascii").splitlines()
        guard_pid = int(reaped[0])
        ended = dict(tuple(int(f) for f in line.split()) for line in reaped[1:])
        self.assertIn("SIGINT received during the gate 36 local shards", output)
        self.assertIn("pre-push guard FAILED at gate 36 local shards (rc=130): interrupted by "
                      "SIGINT", output)
        self.assertNotIn("Safe to push", output)
        records = self.shard_records(marks)
        self.assertEqual(len(records), 6, records)
        self.assertEqual(len({pgid for _pid, pgid, _child in records}), 6, records)
        for pid, pgid, child in records:
            with self.subTest(shard_pid=pid):
                self.assertEqual(pid, pgid, "a shard does not lead its own process group")
                self.assertNotEqual(int(pgid), os.getpgid(0))
                # The child ended by the guard's TERM to its shard's group,
                # not by the KILL after the grace.
                self.assertEqual(ended.get(int(child)), signal.SIGTERM,
                                 "the shard's child was not ended by a TERM to its group "
                                 "(reaped: %r)\n%s" % (ended, output))
                # Every process of the group is gone. SUBREAPER reaps each
                # orphan as it ends and exits once none is left, so the
                # group is normally gone already; the bound (60 seconds)
                # is generous so that only a real leak, not a slow host,
                # fails it.
                deadline = time.monotonic() + 60
                while time.monotonic() < deadline:
                    try:
                        os.killpg(int(pgid), 0)
                    except ProcessLookupError:
                        break
                    time.sleep(0.1)
                with self.assertRaises(ProcessLookupError):
                    os.killpg(int(pgid), 0)
                # The child, which its shard's end does not end, is gone
                # too, and reaped (a zombie still takes signal 0).
                with self.assertRaises(ProcessLookupError):
                    os.kill(int(child), 0)
        ran = (self.root / "ran.log").read_text(encoding="utf-8").split()
        self.assertNotIn(".claude/skills/corpus-management/tools/run-pr-time-checks.sh", ran)
        kept = re.findall(r"^  shard \d: \S+ \(checkout (\S+), log (\S+)\)$", output, re.M)
        self.assertEqual(len(kept), 6, output)
        for checkout, log in kept:
            self.assertTrue(Path(checkout, ".claude/skills/corpus-management/tools", "pre-push-guard.sh").is_file(), checkout)
            self.assertTrue(Path(log).is_file(), log)
        # FLIP TABLE (leftover report): the interrupt message says what was
        # left and that the next push checks it again, with no removal
        # command while this run lasts (a removal command is given only for
        # a finished run); the guard-owner record holds this guard's pid,
        # clone, start time and pid namespace; the next push, once the run
        # has ended, prints the commands that remove it. The scan of every
        # process of the host behind each of these reports may reach its
        # bound on a busy host, which a correctly reported incomplete scan
        # with no removal command says. So may the WARNING that the left
        # report's alarm ended it (assert_left_report, which reads the left
        # report from the line that keeps the checkouts on, not the
        # scan-mode report this run printed first).
        self.assert_left_report(
            output, None,
            " (nothing was removed; the next push reports it until it is removed):",
            "    - this run made it and has not ended yet: the next push checks it again and "
            "prints the commands that remove it only once this run has ended and nothing uses "
            "it\n")
        root = os.path.dirname(os.path.dirname(kept[0][0]))
        record = Path(root, "guard-owner").read_bytes().split(b"\0")
        self.assertEqual(len(record), 7, record)
        self.assertEqual(record[0], b"%d" % guard_pid)
        self.assertEqual(os.path.realpath(os.fsdecode(record[1])), os.path.realpath(self.root))
        self.assertTrue(record[2].isdigit(), record)
        self.assertEqual(os.fsdecode(record[3]), os.readlink("/proc/self/ns/pid"))
        self.assertEqual(record[4:], [self.boot_id().encode("ascii"),
                                      self.machine_id().encode("ascii"), b""])
        later, _ran = self.run_guard()
        self.assertEqual(later.returncode, 0, later.stdout + later.stderr)
        for err in self.complete_reports(later.stderr):
            self.assertIn("pre-push guard: LEFTOVERS of earlier runs", err)
        self.assert_removable(later.stderr, root, [checkout for checkout, _log in kept],
                              re.escape("no process %d exists" % guard_pid), inventory=())
        for checkout, _log in kept:
            self.git("worktree", "remove", "--force", checkout)

    LEFTOVERS_HEAD = ("pre-push guard: LEFTOVERS of earlier runs of this guard in this clone "
                      "(report only: the report ran no git and started and signalled no "
                      "process; no process of a leftover was stopped or signalled, nothing was "
                      "removed and no git state was changed; the push continues):")
    # What a REMOVABLE leftover whose directory exists says was read (no
    # more than the report reads).
    ALL_READ_TEXT = ("every process this /proc shows was read (kernel threads aside: the "
                     "working directory, root directory and open files of each of its threads, "
                     "and its mapped files), and none uses it there")
    # The reason a leftover whose directory exists stays INSPECT while any
    # process (kernel threads aside) cannot be read.
    UNREAD = (r"\d+ process\(es\) could not be read \((\d+) of yours, (\d+) of other users; \d+ "
              r"of them may be privileged\), so whether one uses it is unknown: its mode does "
              r"not exclude one, since a privileged or setuid process, or one handed a "
              r"descriptor, can use it anyway$")
    # The report alone (the guard's own LEFTOVER_PY, read from the fixture's
    # guard), as on a host where every process /proc shows can be read: a
    # process this user cannot read is taken as one that has exited, except
    # a kernel thread, which stays unreadable, so the report's own exclusion
    # of kernel threads is exercised. Any other error reading a process (a
    # process of this user caught as it exits has lost its working directory
    # and descriptors before it is a zombie, which raised a plain OSError
    # and made a test that expects REMOVABLE fail at random) is taken as
    # an exit only when the process is gone, or when /proc/<pid>/stat,
    # read again, shows its leader gone, a zombie or dead, or exiting
    # (PF_EXITING, 0x4, in its flags) and the stat of every one of its
    # threads (/proc/<pid>/task/<tid>/stat) shows the same (the leader
    # alone is a zombie while other threads of the process still run, as the
    # EXITED_LEADER fixture shows), and /proc/<pid>/task, listed again once
    # every thread is read, lists the same threads (a thread created after
    # the first listing is not in it, so a changed listing keeps the process
    # unread); otherwise the process stays one that cannot be read, so a live
    # process the report cannot read (UNREAD_THREAD), or a live thread of one
    # whose leader has exited, is still counted. The re-check reads through
    # os.open and os.read, as the report does, so a prelude can script it. On
    # a host with unreadable processes a test uses it to check the commands
    # printed once nothing else stands in the way. Arguments: the code, then
    # the report's own arguments.
    ALL_READ = (
        "import contextlib, io, os, sys\n"
        "code = sys.argv.pop(1)\n"
        "mode = sys.argv[1]\n"
        "sys.argv[1] = 'identity'\n"
        "g = {'__name__': '__main__'}\n"
        "with contextlib.redirect_stdout(io.StringIO()):\n"
        "    exec(code, g)\n"
        "g['mode'] = mode\n"
        "g['only'] = os.path.realpath(sys.argv[5]) if mode == 'left' else None\n"
        "real = g['uses']\n"
        "def kernel_thread(pid):\n"
        "    try:\n"
        "        data = open('/proc/%s/stat' % pid, 'rb').read()\n"
        "        return int(data[data.rindex(b')') + 2:].split()[6]) & 0x00200000\n"
        "    except (OSError, ValueError, IndexError):\n"
        "        return False\n"
        "def ended(path):\n"
        "    try:\n"
        "        fd = os.open(path, os.O_RDONLY)\n"
        "    except (FileNotFoundError, ProcessLookupError):\n"
        "        return True\n"
        "    except OSError:\n"
        "        return False\n"
        "    try:\n"
        "        data = os.read(fd, 4096)\n"
        "    except OSError:\n"
        "        return False\n"
        "    finally:\n"
        "        os.close(fd)\n"
        "    try:\n"
        "        rest = data[data.rindex(b')') + 2:].split()\n"
        "        return rest[0] in (b'Z', b'X', b'x') or bool(int(rest[6]) & 0x4)\n"
        "    except (ValueError, IndexError):\n"
        "        return False\n"
        "def threads(pid):\n"
        "    try:\n"
        "        return sorted(os.listdir('/proc/%s/task' % pid))\n"
        "    except (FileNotFoundError, ProcessLookupError):\n"
        "        return []\n"
        "def exiting(pid):\n"
        "    if not ended('/proc/%s/stat' % pid):\n"
        "        return False\n"
        "    try:\n"
        "        tids = threads(pid)\n"
        "        if not all(ended('/proc/%s/task/%s/stat' % (pid, tid)) for tid in tids):\n"
        "            return False\n"
        "        return threads(pid) == tids\n"
        "    except OSError:\n"
        "        return False\n"
        "def uses(pid, roots):\n"
        "    try:\n"
        "        return real(pid, roots)\n"
        "    except PermissionError:\n"
        "        if kernel_thread(pid):\n"
        "            raise\n"
        "        raise ProcessLookupError(pid)\n"
        "    except OSError:\n"
        "        if exiting(pid):\n"
        "            raise ProcessLookupError(pid)\n"
        "        raise\n"
        "g['uses'] = uses\n"
        "g['main']()\n")

    def report_code(self):
        guard = (self.root / ".claude/skills/corpus-management/tools" / "pre-push-guard.sh").read_text(encoding="utf-8")
        return guard.split("LEFTOVER_PY='\n", 1)[1].split("\n'\n", 1)[0]

    # A prelude for the report alone that gives it a deterministic process
    # inventory: /proc lists the report itself (which it skips) and the
    # pids FIXTURE_PIDS names (space-separated: the test's own fixture
    # processes) and no other, so what it finds does not depend on what
    # else runs on the host, nor its scan on how much (for every test that
    # asserts an outcome through ALL_READ). Every other path is listed as
    # is.
    NO_OTHER_PROCESS = (
        "import os\n"
        "_listdir = os.listdir\n"
        "def _inventory(path='.'):\n"
        "    if path == '/proc':\n"
        "        return [str(os.getpid())] + os.environ.get('FIXTURE_PIDS', '').split()\n"
        "    return _listdir(path)\n"
        "os.listdir = _inventory\n")

    def report_all_read(self, mode="scan", *args, inventory, prelude="", cwd=None, **extra):
        """The report alone through ALL_READ. inventory is the pids of the
        test's own fixture processes, which with the report itself are all
        that /proc lists (NO_OTHER_PROCESS), or None for the host's whole
        /proc (only for a test whose subject is that scan). With an
        inventory it also runs on the clock CLOCKED_REPORT sets, its wait
        for the worker lasting until the worker ends
        (FIXTURE_JOIN_UNTIL_DONE=1), so no real scan bound, join margin or
        alarm applies to it: it is the report alone that complete_reports
        and assert_removable check an exact outcome on, and a host stall
        cannot make it INCOMPLETE or end it
        (test_report_all_read_does_not_depend_on_real_time). It runs in cwd,
        the fixture clone by default, as a push from there would."""
        if inventory is not None:
            prelude = self.NO_OTHER_PROCESS + self.CLOCKED_REPORT + prelude
            extra["FIXTURE_PIDS"] = " ".join(str(pid) for pid in inventory)
            extra["FIXTURE_JOIN_UNTIL_DONE"] = "1"
        return subprocess.run([sys.executable, "-I", "-c", self.ALL_READ,
                               prelude + self.report_code(),
                               mode, "repo", "1", self.common_dir(), *args],
                              cwd=self.root if cwd is None else cwd,
                              env=dict(self.env, **extra), capture_output=True, text=True,
                              timeout=60)

    def common_dir(self):
        """This fixture's git common directory, as the guard's shell passes it
        to the report (git runs here, in the test, never in the report)."""
        out = self.git("rev-parse", "--git-common-dir").stdout.strip()
        return os.path.realpath(os.path.join(self.root, out))

    def report_alone(self, prelude="", mode="scan", extra_args=(), **extra):
        """The report alone (the guard's own code after prelude), with this
        fixture's common directory, as the guard runs it."""
        return subprocess.run([sys.executable, "-I", "-c", prelude + self.report_code(), mode,
                               "repo", "1", self.common_dir(), *extra_args], cwd=self.root,
                              env=dict(self.env, **extra), capture_output=True, text=True,
                              timeout=60)

    @staticmethod
    def leftover_block(text, word):
        """The lines of the block of the leftover printed as word."""
        lines = text.splitlines()
        for i, line in enumerate(lines):
            if line.startswith("  %s: " % word):
                block = [line]
                for more in lines[i + 1:]:
                    if not more.startswith("    "):
                        break
                    block.append(more)
                return block
        return None

    def assert_removable(self, err, root, checkouts, state, *, inventory, **extra):
        """root is proven a finished run of this clone (state: a pattern for
        how its end was read) in every respect but processes this user cannot
        read: in err, the real guard's report, REMOVABLE with the commands
        that remove it, or INSPECT whose one reason is that processes could
        not be read, or a correctly reported unknown (unknown_scan: an
        incomplete scan, or the WARNING that the report's alarm ended it,
        after whatever it had printed). As on a host where every process is
        read (report_all_read, with the process inventory inventory), it is
        REMOVABLE with those commands, which are returned."""
        expected = self.removable_commands(root, checkouts)
        if not self.unknown_scan(err):
            block = self.leftover_block(err, root)
            self.assertIsNotNone(block, err)
            if block[0].startswith("  %s: REMOVABLE: " % root):
                self.assertEqual(self.leftover_commands("\n".join(block)), expected, err)
            else:
                self.assertEqual(block[0], "  %s: INSPECT (no removal command), because:" % root,
                                 err)
                reasons = [line[6:] for line in block if line.startswith("    - ")]
                self.assertEqual(len(reasons), 1, err)
                self.assertRegex(reasons[0], self.UNREAD)
                self.assertEqual(self.leftover_commands("\n".join(block)), [], err)
        alone = self.report_all_read(inventory=inventory, **extra)
        self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
        block = self.leftover_block(alone.stdout, root)
        self.assertIsNotNone(block, alone.stdout)
        self.assertRegex(block[0], r"^  %s: REMOVABLE: guard run pid \d+ of this clone made it "
                                   r"and has ended \(%s\); %s$"
                                   % (re.escape(str(root)), state, re.escape(self.ALL_READ_TEXT)))
        commands = self.leftover_commands("\n".join(block))
        self.assertEqual(commands, expected, alone.stdout)
        return commands

    @staticmethod
    def boot_id():
        return Path("/proc/sys/kernel/random/boot_id").read_text(encoding="ascii").strip()

    @staticmethod
    def machine_id():
        """This machine id as the report reads it, or - (fail closed)."""
        try:
            value = Path("/etc/machine-id").read_text(encoding="ascii").strip()
        except (OSError, UnicodeDecodeError):
            return "-"
        return value if re.fullmatch("[0-9a-f]{32}", value) else "-"

    # A boot id no kernel has, and a machine id that is not this one.
    OTHER_BOOT = "00000000-0000-0000-0000-000000000000"
    OTHER_MACHINE = "0" * 32

    # A process that only checks how it was started: it exits 0 if it runs
    # isolated (-I) with exactly the environment argv[1] holds as JSON
    # (Python may add LC_CTYPE, PEP 538), and 9 if not.
    ENDED = ("import json, os, sys\n"
             "env = dict(os.environ)\n"
             "env.pop('LC_CTYPE', None)\n"
             "sys.exit(0 if sys.flags.isolated and env == json.loads(sys.argv[1]) else 9)\n")

    def ended_pid(self):
        """The pid of a process that has ended: isolated Python (-I) running
        ENDED with this fixture's built environment (self.env), started by
        start_poisoned in this fixture's directory and reaped here. It must
        exit 0, which it does only if it ran isolated with exactly self.env,
        so a start without -I or with this process's environment fails the
        test. Its wait is bounded, and it is killed and reaped in a finally
        block, whatever that wait raises."""
        done = self.start_poisoned([sys.executable, "-I", "-c", self.ENDED, json.dumps(self.env)],
                                   cwd=self.tmp.name)
        try:
            done.wait(timeout=30)
        finally:
            if done.poll() is None:
                done.kill()
            done.wait(timeout=30)
        self.assertEqual(done.returncode, 0,
                         "the ended process did not run isolated with this fixture's environment")
        return done.pid

    def run_record(self, pid=None, clone=None, start="1", ns=None, boot=None, machine=None):
        """A run record as the guard writes it (in a guard-owner record and
        beside the git record of each checkout): pid, clone, start time, pid
        namespace, boot id and machine id, NUL-separated. By default the pid
        is that of a process that has ended (ended_pid), the clone is the
        fixture's, and the pid namespace, boot id and machine id are those
        of this test."""
        if pid is None:
            pid = self.ended_pid()
        ns = os.readlink("/proc/self/ns/pid") if ns is None else ns
        boot = self.boot_id() if boot is None else boot
        machine = self.machine_id() if machine is None else machine
        return b"\0".join([b"%d" % pid, os.fsencode(str(self.root if clone is None else clone)),
                           start.encode("ascii"), os.fsencode(ns), boot.encode("ascii"),
                           machine.encode("ascii"), b""])

    def write_owner(self, root, **fields):
        """A guard-owner record in root (see run_record)."""
        Path(root, "guard-owner").write_bytes(self.run_record(**fields))

    def make_leftover(self, shards, tmpdir=None, owner=True, relative=False):
        """A shard directory as a run that has ended leaves it:
        grc-gate36-shards.* under tmpdir (the fixture's TMPDIR by default)
        holding a guard-owner record of an ended run of this clone (none
        when owner is False, as an older guard leaves it) and `shards`
        checkouts of HEAD that are registered with this clone (with a
        relative gitdir when relative is set). Returns its physical path
        and the checkouts."""
        base = self.shard_tmp if tmpdir is None else Path(tmpdir)
        root = Path(os.path.realpath(tempfile.mkdtemp(prefix="grc-gate36-shards.", dir=base)))
        if owner:
            self.write_owner(root)
        checkouts = []
        for i in range(1, shards + 1):
            (root / ("shard-%d" % i)).mkdir()
            (root / ("shard-%d" % i) / "shard.log").write_text("log\n", encoding="utf-8")
            checkout = root / ("shard-%d" % i) / "repo"
            config = ("-c", "worktree.useRelativePaths=true") if relative else ()
            self.git(*config, "worktree", "add", "--detach", str(checkout), "HEAD")
            checkouts.append(checkout)
        return root, checkouts

    @staticmethod
    def leftover_commands(text):
        """The commands a leftover report prints, in order (each indented six
        spaces)."""
        return [line[6:] for line in text.splitlines()
                if line.startswith("      ")
                and line[6:].startswith(("git worktree remove ", "rm -rf ", "kill -TERM "))]

    def assert_inspect(self, err, root, *reasons):
        """root is reported INSPECT, with each reason, and no command at all."""
        block = err.split("  %s: " % root, 1)
        self.assertEqual(len(block), 2, err)
        self.assertTrue(block[1].startswith("INSPECT (no removal command), because:\n"), err)
        for reason in reasons:
            self.assertRegex(block[1], r"(?m)^    - " + reason, err)
        self.assertEqual(self.leftover_commands(err), [], err)

    # The line of a report whose scan reached its bound before it finished
    # (not one whose scan failed, which no test accepts): at a stage, or
    # before its state could be read at all.
    INCOMPLETE_SCAN = (r"(?m)^pre-push guard: the leftover scan is INCOMPLETE: (?:its 3s scan "
                       r"bound \(the whole report is bounded to 5s\) was reached while [a-z ]+; "
                       r"leftovers it had not reached are not listed, and none listed has a "
                       r"removal command\.|its state could not be read within the 5s bound; "
                       r"leftovers are not listed\.)$")
    # The first reason of each leftover a report whose scan did not finish
    # lists.
    NOT_FINISHED = ("    - the scan did not finish, so what it holds and whether a process uses "
                    "it are not fully known")

    def incomplete_scan(self, text):
        """Whether text, the real guard's report (a scan of every process of
        the host, which on a busy host can reach its bound before it ends),
        is a correctly reported incomplete scan, which a test accepts in
        place of the outcome it expects there. True when text says its scan
        reached its bound; it must then print no removal command and no
        REMOVABLE leftover, and list each leftover as INSPECT with the
        unfinished scan as its first reason, or the test fails. False when
        text does not say so (a scan that failed included), so the test
        checks its expected outcome. A test that accepts it keeps its exact
        outcome and rendering assertions on the report alone, against a
        deterministic inventory."""
        if not re.search(self.INCOMPLETE_SCAN, text):
            return False
        self.assertEqual(self.leftover_commands(text), [], text)
        lines = text.splitlines()
        for i, line in enumerate(lines):
            self.assertNotRegex(line, r"^  (?! ).*: REMOVABLE: ", text)
            if re.match(r"  (?! ).*: INSPECT \(no removal command\), because:$", line):
                self.assertEqual(lines[i + 1:i + 2], [self.NOT_FINISHED], text)
        return True

    # The guard's line when the alarm of its scan-mode report ended that
    # report (status 142; leftover_report in pre-push-guard.sh).
    ALARMED_SCAN = ("pre-push guard: WARNING: the leftover report (scan) was ended at its "
                    "5-second bound (any report output it printed may be incomplete), so "
                    "what earlier runs of this guard left is unknown; it stopped and removed "
                    "nothing of a leftover.")

    # The guard's line when the alarm of its left-mode report ended that
    # report, with the shard directory the report was given in place of %s
    # (status 142; leftover_report in pre-push-guard.sh).
    ALARMED_LEFT = ("pre-push guard: WARNING: the leftover report (left) was ended at its "
                    "5-second bound (any report output it printed may be incomplete), so "
                    "what this run left in %s and whether a process uses it are unknown; "
                    "it stopped and removed nothing of a leftover.")

    def alarmed(self, text, warning, report=None):
        """Whether text holds warning, the guard's WARNING that the 5-second
        alarm of one of its reports ended that report (ALARMED_SCAN, or
        ALARMED_LEFT with its directory), as a busy host that uses up the
        margin after the scan bound makes it. The alarm can end the report
        at any point of its output, so before it ended the report may have
        printed nothing, a part of its report cut anywhere, even within a
        line, or all of it. That output is in text before the WARNING, which
        the guard writes right after it (so the WARNING ends a line but need
        not start one), or in report when the report writes to another stream
        than the WARNING. It is a correctly reported unknown whatever part of
        the report it holds: a test that accepts it checks its exact outcome
        on the report alone, against a deterministic inventory. A scan that
        failed is never accepted, and nothing of a report may follow the
        WARNING in text (the report had ended), or the test fails."""
        found = re.search(r"(?m)%s$" % re.escape(warning), text)
        if found is None:
            return False
        printed = text[:found.start()] if report is None else report
        self.assertNotRegex(printed, r"(?m)^pre-push guard: the leftover scan failed ", text)
        after = text[found.end():]
        self.assertEqual(self.leftover_commands(after), [], text)
        self.assertNotIn(self.LEFTOVERS_HEAD, after)
        self.assertNotIn("Left behind by this run", after)
        self.assertNotRegex(after, r"(?m)^pre-push guard: the leftover scan ")
        self.assertNotRegex(after, r"(?m)^  (?! ).*: (REMOVABLE|INSPECT)")
        return True

    def unknown_scan(self, text):
        """Whether text, the real guard's scan-mode report (on its stderr),
        is a correctly reported unknown, which a test accepts in place of
        the outcome it expects there: a correctly reported incomplete scan
        (incomplete_scan), or the guard's WARNING that the report's 5-second
        alarm ended it (ALARMED_SCAN), after whatever part of the report it
        had printed (alarmed). False for any other text (a report that
        failed, or the WARNING of the left report, included), so the test
        checks its expected outcome. Only the checks of the real guard's
        scan-mode report use it (complete_reports and assert_removable); the
        checks of what a run left use unknown_left, since a WARNING about the
        scan-mode report says nothing about that."""
        if self.incomplete_scan(text):
            return True
        return self.alarmed(text, self.ALARMED_SCAN)

    def unknown_left(self, out, err, root):
        """Whether out, the real guard's left-mode report about root (this
        run's shard directory), is a correctly reported unknown, which a
        check of what a run left accepts in place of the "Left behind by
        this run" block it expects: a correctly reported incomplete scan
        (incomplete_scan), or the guard's WARNING that the report's
        5-second alarm ended it (ALARMED_LEFT, naming root; alarmed), in
        err, the guard's stderr, or in out when err is None (one text
        holds both). False for any other text (the WARNING of the
        scan-mode report, of a left report that failed or about another
        directory, included), so the test checks its expected outcome."""
        if self.incomplete_scan(out):
            return True
        if err is None:
            return self.alarmed(out, self.ALARMED_LEFT % root)
        return self.alarmed(err, self.ALARMED_LEFT % root, report=out)

    def assert_left_report(self, out, err, *expected):
        """What the real guard printed about what this run left, once a
        shard failed or the run was interrupted: out is the guard's stdout
        and err its stderr, or err is None when out holds both, as one file
        does. The left report is what out holds from the line that keeps the
        shard checkouts on (which names the directory the report is given): a
        "Left behind by this run" block that holds each expected text, or
        a correctly reported unknown (unknown_left). It prints no removal
        command either way, since this run has not ended. Returns the
        directory."""
        kept = re.search(r"(?m)^The shard checkouts and logs are kept for inspection under "
                         r"(\S+):$", out)
        self.assertIsNotNone(kept, out)
        section = out[kept.end():]
        left = section.split("Left behind by this run", 1)
        if not self.unknown_left(section, err, kept.group(1)):
            self.assertEqual(len(left), 2, section)
            for text in expected:
                self.assertIn(text, left[1])
        self.assertEqual(self.leftover_commands(section), [], section)
        return kept.group(1)

    def complete_reports(self, real, *alone):
        """The reports a test checks its exact outcome on: real, the real
        guard's, unless it is a correctly reported unknown (unknown_scan),
        and each report alone."""
        return ([] if self.unknown_scan(real) else [real]) + list(alone)

    def removable_commands(self, root, checkouts):
        return (["git worktree remove --force -- %s" % c for c in sorted(map(str, checkouts))]
                + ["rm -rf -- %s" % root])

    def test_leftovers_are_reported_with_the_commands_that_remove_them(self):
        # FLIP TABLE (leftover report): what a finished run of this clone
        # left (here two registered checkouts in their shard directory) is
        # REMOVABLE, with the commands that remove it, once every process is
        # read (on a host with unreadable processes those alone keep it
        # INSPECT); running them gives a clean start. The header says the
        # report ran no git and started and signalled no process. The real
        # guard's report may be a correctly reported incomplete scan of the
        # host's processes; the report alone, against a deterministic
        # inventory, always shows the header and checkouts.
        self.change(".web/templates-draft/landing.html")
        root, checkouts = self.make_leftover(2)
        result, _ran = self.run_guard()
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        self.assertIn("pre-push guard FAST PATH", result.stdout)
        err = result.stderr
        alone = self.report_all_read(inventory=())
        self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
        for text in self.complete_reports(err, alone.stdout):
            self.assertIn(self.LEFTOVERS_HEAD + "\n", text)
            for checkout in checkouts:
                self.assertIn("    checkout %s: registered with this clone; its directory "
                              "exists; its .git points into this clone\n" % checkout, text)
        commands = self.assert_removable(err, root, checkouts, r"no process \d+ exists",
                                         inventory=())
        for command in commands[:-1]:
            subprocess.run(["bash", "-c", command], cwd=self.root, env=self.env, check=True,
                           capture_output=True, timeout=30)
        # The last command, rm -rf -- <directory>, done here in Python.
        shutil.rmtree(root)
        again, _ran = self.run_guard()
        self.assertEqual(again.returncode, 0, again.stdout + again.stderr)
        self.assertNotIn("LEFTOVERS", again.stderr)

    def test_leftover_report_changes_no_git_state(self):
        # FLIP TABLE: the report runs no git worktree prune, so a guard
        # checkout and an unrelated checkout whose directories are gone
        # both keep their records; the guard's is INSPECT (its shard
        # directory is gone, and no run record beside its git record shows
        # which run made it), named with what git says, and has no command.
        self.change(".web/templates-draft/landing.html")
        gone, gone_checkouts = self.make_leftover(1)
        admin = self.git("-C", str(gone_checkouts[0]), "rev-parse",
                         "--absolute-git-dir").stdout.strip()
        head = self.git("-C", str(gone_checkouts[0]), "rev-parse", "HEAD").stdout.strip()
        shutil.rmtree(gone)
        side = Path(self.tmp.name) / "side-worktree"
        self.git("worktree", "add", "--detach", str(side), "HEAD")
        shutil.rmtree(side)
        before = self.git("worktree", "list", "--porcelain").stdout
        result, _ran = self.run_guard()
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        self.assertNotIn("git worktree prune", result.stderr)
        self.assertNotIn("REMOVABLE", result.stderr)
        self.assertEqual(self.leftover_commands(result.stderr), [], result.stderr)
        # The real guard's report may be a correctly reported incomplete scan
        # of the host's processes; the report alone, against a deterministic
        # inventory, always gives the outcome.
        alone = self.report_all_read(inventory=())
        self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
        for err in self.complete_reports(result.stderr, alone.stdout):
            self.assertNotIn("git worktree prune", err)
            self.assert_inspect(err, gone, re.escape(
                "its directory does not exist, and no run record beside the git record of "
                "checkout %s shows which run registered it (an older guard writes none, or its "
                "run stopped before writing it), so whether that run has ended is not proved"
                % gone_checkouts[0]) + "$")
            self.assertIn("    checkout %s: registered with this clone; git would list it as "
                          "prunable (gitdir file points to non-existent location); its directory "
                          "does not exist\n" % gone_checkouts[0], err)
            # FLIP TABLE: such a git record, which an older guard left with no
            # run record, gets the facts known and a manual inspection
            # procedure ending in the narrow command, marked NOT PROVED, never
            # REMOVABLE, and given as no removal command.
            block = "\n".join(self.leftover_block(err, gone)) + "\n"
            self.assertIn(
                "      its git record holds HEAD %s (detached); a commit made there that no "
                "branch or tag holds is lost with the record\n"
                "      NOT PROVED, so no removal command: no run record shows which run "
                "registered it. To check it by hand (its git record is %s):\n"
                "        1. that no run of this guard that could have registered it is still "
                "running, on this host or on another host, VM or container that shares this "
                "clone;\n"
                "        2. that HEAD %s is held by a branch or tag, or is not needed (git "
                "branch --all --contains %s; git tag --contains %s);\n"
                "        3. that the checkout directory still does not exist (ls -ld -- %s).\n"
                "        Only then, by your own judgement: git worktree remove -- %s removes "
                "that git record alone.\n" % (head, admin, head, head, head, gone_checkouts[0],
                                              gone_checkouts[0]), block)
            self.assertNotIn("REMOVABLE", err)
            self.assertEqual(self.leftover_commands(err), [], err)
        self.assertEqual(self.git("worktree", "list", "--porcelain").stdout, before)
        self.assertIn("worktree %s\n" % side, before)
        self.assertIn("worktree %s\n" % gone_checkouts[0], before)

    def test_prunable_checkout_whose_directory_remains_is_not_called_gone(self):
        # FLIP TABLE: a registered checkout whose .git file is gone while
        # its directory remains is one git lists as prunable; the report
        # says its directory exists, gives git's own reason, and makes it
        # INSPECT with no command.
        self.change(".web/templates-draft/landing.html")
        root, checkouts = self.make_leftover(1)
        (checkouts[0] / ".git").unlink()
        result, _ran = self.run_guard()
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        self.assertEqual(self.leftover_commands(result.stderr), [], result.stderr)
        # As in each test of the real guard's report, a correctly
        # reported incomplete scan is accepted there, and the report
        # alone always gives the outcome.
        alone = self.report_all_read(inventory=())
        self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
        for err in self.complete_reports(result.stderr, alone.stdout):
            self.assert_inspect(err, root, re.escape("git would list checkout %s as prunable "
                                                     "although its directory exists"
                                                     % checkouts[0]))
            self.assertIn("    checkout %s: registered with this clone; git would list it as "
                          "prunable (gitdir file points to non-existent location); its "
                          "directory exists; it has no .git file\n" % checkouts[0], err)
            self.assertNotIn("is gone", err)
        self.assertTrue(checkouts[0].is_dir())
        self.assertIn("worktree %s\n" % checkouts[0],
                      self.git("worktree", "list", "--porcelain").stdout)

    def test_unreadable_checkout_metadata_is_reported_never_dropped(self):
        # FLIP TABLE: a checkout whose .git cannot be read is reported,
        # with or without a guard-owner record, and never given a
        # removal command.
        if os.geteuid() == 0:
            self.skipTest("root reads a mode-000 file")
        self.change(".web/templates-draft/landing.html")
        for owner in (False, True):
            with self.subTest(owner=owner):
                root = Path(os.path.realpath(tempfile.mkdtemp(prefix="grc-gate36-shards.",
                                                              dir=self.shard_tmp)))
                if owner:
                    self.write_owner(root)
                checkout = root / "shard-1" / "repo"
                checkout.mkdir(parents=True)
                (checkout / ".git").write_text("gitdir: /nowhere\n", encoding="utf-8")
                (checkout / ".git").chmod(0)
                try:
                    result, _ran = self.run_guard()
                    alone = self.report_all_read(inventory=())
                finally:
                    (checkout / ".git").chmod(0o600)
                self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
                self.assertEqual(self.leftover_commands(result.stderr), [], result.stderr)
                self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
                # The real guard's report or a correctly reported
                # incomplete scan; the report alone.
                for err in self.complete_reports(result.stderr, alone.stdout):
                    self.assert_inspect(err, root, re.escape("checkout %s is not proven to be "
                                                             "a checkout of this clone"
                                                             % checkout))
                    self.assertIn("    checkout %s: not registered with this clone; its "
                                  "directory exists; its .git cannot be read (Permission "
                                  "denied)\n" % checkout, err)
                shutil.rmtree(root)

    def test_mixed_ownership_gets_no_removal_command(self):
        # FLIP TABLE: a shard directory of this clone that also holds
        # another repository's checkout, or a file the guard does not make,
        # is INSPECT: one checkout of this clone does not license rm -rf of
        # the rest.
        self.change(".web/templates-draft/landing.html")
        other = Path(self.tmp.name) / "other" / "repo"
        other.mkdir(parents=True)
        for args in (("init", "-q"),
                     ("-c", "user.email=o@example.com", "-c", "user.name=o", "commit", "-q",
                      "--allow-empty", "-m", "Other")):
            subprocess.run(["git", *args], cwd=other, env=self.env, check=True,
                           capture_output=True, timeout=30)
        root, checkouts = self.make_leftover(1)
        (root / "shard-2").mkdir()
        foreign = root / "shard-2" / "repo"
        subprocess.run(["git", "worktree", "add", "--detach", str(foreign), "HEAD"], cwd=other,
                       env=self.env, check=True, capture_output=True, timeout=30)
        # Each outcome is checked on the real guard's report, unless it is
        # a correctly reported incomplete scan of the host's processes, and
        # on the report alone.
        def reports():
            result, _ran = self.run_guard()
            self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
            self.assertEqual(self.leftover_commands(result.stderr), [], result.stderr)
            alone = self.report_all_read(inventory=())
            self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
            return self.complete_reports(result.stderr, alone.stdout)
        for err in reports():
            self.assert_inspect(err, root, re.escape("checkout %s is not proven to be a "
                                                     "checkout of this clone" % foreign))
            self.assertRegex(err, r"(?m)^    checkout %s: not registered with this clone; its "
                                  r"directory exists; it is not a checkout of this clone \(its "
                                  r"\.git names .+\)$" % re.escape(str(foreign)))
        subprocess.run(["git", "worktree", "remove", "--force", str(foreign)], cwd=other,
                       env=self.env, check=True, capture_output=True, timeout=30)
        (root / "notes.txt").write_text("mine\n", encoding="utf-8")
        for err in reports():
            self.assert_inspect(err, root, re.escape("it holds %s, which this guard does "
                                                     "not make" % (root / "notes.txt")))
        # A checkout that is a symbolic link (here to this clone's own
        # checkout) is not read through: it is something the guard does
        # not make.
        (root / "notes.txt").unlink()
        (root / "shard-3").mkdir()
        (root / "shard-3" / "repo").symlink_to(checkouts[0])
        for err in reports():
            self.assert_inspect(err, root, re.escape("it holds %s, which this guard does "
                                                     "not make" % (root / "shard-3" / "repo")))

    # A process for a test whose run record names a live pid: it writes
    # "ready" on its stdout once it runs (the startup handshake) and then
    # reads its stdin, a pipe the test holds, until that pipe closes, so it
    # lives until the test's cleanup closes it, with no time limit of its
    # own; it also ends if the test process dies, since the pipe then
    # closes too.
    LIVE_HELPER = ("import sys\n"
                   "sys.stdout.write('ready\\n')\n"
                   "sys.stdout.flush()\n"
                   "sys.stdin.buffer.read()\n")

    def poison_directory(self, name="parent-poison"):
        """A directory (name, in this fixture's directory) that no Python can
        start from: it holds no standard library, so a Python that reads it
        as PYTHONHOME stops at its encodings import ("Failed to import
        encodings module"), before site runs; its sitecustomize.py exits at
        once (status 9), which stops a Python that reads it only as
        PYTHONPATH. Returns its path."""
        poison = Path(self.tmp.name) / name
        poison.mkdir(exist_ok=True)
        (poison / "sitecustomize.py").write_text("raise SystemExit(9)\n", encoding="utf-8")
        return poison

    def start_poisoned(self, argv, poison=None, env=None, **popen):
        """subprocess.Popen(argv, env=env, **popen) (env is self.env by
        default), started while this process's own environment names poison
        (poison_directory's by default) as PYTHONHOME and PYTHONPATH, so a
        process that took this process's environment and was not isolated
        would not start."""
        from unittest.mock import patch

        poison = self.poison_directory() if poison is None else poison
        with patch.dict(os.environ, {"PYTHONHOME": str(poison), "PYTHONPATH": str(poison)}):
            return subprocess.Popen(argv, env=self.env if env is None else env, **popen)

    def live_process(self, code=None, *args, cwd=None, command=None, poison=None,
                     start_new_session=False, extra_env=None):
        """A live process for this test (the one place this class starts a
        helper that it holds alive by a stdin pipe and awaits by a startup
        handshake; elsewhere this class starts other processes, among them
        its guard runs, ended_pid's process, SUBREAPER's launcher and the
        isolated Python report processes of report_all_read and
        report_alone): isolated Python (-I) running code with args, or
        command (bash running a script whose own Python processes it starts
        with -I), started with this fixture's built environment (self.env),
        not this process's, in cwd (this fixture's directory, outside any
        leftover, by default). start_poisoned starts it, so while it starts,
        this process's own environment names poison (poison_directory's by
        default) as PYTHONHOME and PYTHONPATH: a Python that read it as
        PYTHONHOME would stop at its encodings import, since it holds no
        standard library, and one that read it only as PYTHONPATH would stop
        at its sitecustomize.py, which exits at once, so a process that took
        this process's environment and was not isolated would not start. Its
        stdin is a pipe this test holds, so it lives until it ends by itself
        or this test's cleanup closes that pipe and reaps it
        (end_live_helper), with no time limit of its own. Its first line on
        stdout is its startup handshake, awaited for up to 60 seconds; then
        /proc shows that its environment is exactly self.env (Python may add
        LC_CTYPE, PEP 538) and, for code, that its command line has -I.
        start_new_session starts it in a session (and process group) of its
        own. extra_env adds variables to self.env for it, and its environment
        is then exactly both. Returns (its Popen, that line)."""
        import select

        env = dict(self.env, **(extra_env or {}))
        argv = [sys.executable, "-I", "-c", code, *args] if command is None else command
        helper = self.start_poisoned(argv, poison, env=env,
                                     cwd=self.tmp.name if cwd is None else cwd,
                                     stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                     start_new_session=start_new_session)
        self.addCleanup(self.end_live_helper, helper)
        ready, _writable, _failed = select.select([helper.stdout], [], [], 60)
        line = helper.stdout.readline() if ready else b""
        self.assertTrue(line.endswith(b"\n"), "the live process did not start: %r" % line)
        environ = self.proc_bytes(helper.pid, "environ").split(b"\0")
        self.assertEqual(sorted(e for e in environ if e and not e.startswith(b"LC_CTYPE=")),
                         sorted(os.fsencode("%s=%s" % item) for item in env.items()),
                         "the live process does not run with this fixture's environment")
        if command is None:
            cmdline = self.proc_bytes(helper.pid, "cmdline").split(b"\0")
            self.assertEqual(cmdline[1:3], [b"-I", b"-c"], cmdline)
        return helper, line.decode("ascii")

    @staticmethod
    def proc_bytes(pid, name):
        """/proc/<pid>/<name> (environ or cmdline) as the first thread of pid
        that shows it reads it: once the thread-group leader has exited (as
        in EXITED_LEADER), its own is empty or refused (EACCES), and a live
        thread's is read; empty if no thread shows it."""
        tasks = sorted(os.listdir("/proc/%d/task" % pid))
        for where in ["/proc/%d" % pid] + ["/proc/%d/task/%s" % (pid, tid) for tid in tasks]:
            try:
                data = Path(where, name).read_bytes()
            except PermissionError:
                continue
            if data:
                return data
        return b""

    def live_helper(self, cwd=None, poison=None):
        """A live process (LIVE_HELPER) for this test, started by live_process
        (in cwd, this fixture's directory by default, and with poison as
        live_process takes it); its handshake is its "ready" line. Returns
        its Popen."""
        helper, line = self.live_process(self.LIVE_HELPER, cwd=cwd, poison=poison)
        self.assertEqual(line, "ready\n", "the live helper did not start")
        return helper

    @staticmethod
    def end_live_helper(helper):
        """End a live_process process: close its pipe, which ends a process
        that reads it (one blocked elsewhere, such as the FIFO writer of
        test_fifo_in_a_git_record_is_never_opened, is ended first by its
        test's own cleanup, which was registered later and so runs earlier),
        and reap it, killing it first if it has not ended within 30
        seconds. The reaping is in a finally block, so it runs whatever
        closing raises."""
        try:
            helper.stdin.close()
            helper.wait(timeout=30)
        finally:
            if helper.poll() is None:
                helper.kill()
            helper.wait(timeout=30)
            helper.stdout.close()

    def test_live_helper_is_isolated_and_lives_until_its_pipe_closes(self):
        # FLIP TABLE: the live process of
        # test_live_or_unknown_run_gets_no_removal_command starts whatever
        # Python variables this process holds: here PYTHONHOME and PYTHONPATH
        # name this test's own directory (poison_directory), which
        # live_process sets, and does not replace with a directory of its
        # own, while it starts it. A Python that read it as PYTHONHOME would
        # stop at its encodings import, and one that read it only as
        # PYTHONPATH at its sitecustomize.py, so neither would start. Its
        # command line has -I, and its environment is exactly self.env
        # (Python may add LC_CTYPE, PEP 538). It is still running once its
        # handshake is done and ends, with status 0, once its pipe is closed.
        # Started without -I and with this process's environment, it fails
        # its handshake and this test fails; with either one alone, the
        # command line or the environment check fails.
        poison = self.poison_directory("poison")
        helper = self.live_helper(poison=poison)
        self.assertIsNone(helper.poll(), "the live helper ended by itself")
        cmdline = Path("/proc/%d/cmdline" % helper.pid).read_bytes().split(b"\0")
        self.assertEqual(cmdline[1:3], [b"-I", b"-c"], cmdline)
        environ = Path("/proc/%d/environ" % helper.pid).read_bytes().split(b"\0")
        self.assertEqual(sorted(e for e in environ if e and not e.startswith(b"LC_CTYPE=")),
                         sorted(os.fsencode("%s=%s" % item) for item in self.env.items()))
        helper.stdin.close()
        self.assertEqual(helper.wait(timeout=30), 0)

    def test_live_or_unknown_run_gets_no_removal_command(self):
        # FLIP TABLE: a run whose state is unknown (another pid namespace,
        # or a live pid with no start time recorded) is INSPECT with no
        # command, however idle its directory looks. So is a run of another
        # kernel whose machine id is not this one (for the guard-owner
        # record too: its pid means nothing here), even as on a host where
        # every process is read.
        self.change(".web/templates-draft/landing.html")
        root, checkouts = self.make_leftover(1)
        # The live process is live_helper's, isolated from this process's
        # environment and alive until this test's cleanup, however long its
        # three guard and report pairs take. live_process builds the
        # environment this process starts it from, so a live_process that
        # took this process's environment, or ran Python without -I, fails
        # this test too.
        helper = self.live_helper()
        for fields, reason in (
                ({"ns": "pid:[1]"}, r"guard run pid \d+ ran in another pid namespace "
                                    r"\(pid:\[1\]\), so whether it has ended cannot be read "
                                    r"from here$"),
                ({"pid": helper.pid, "start": "-"},
                 r"a process %d exists, and the record holds no start time to tell it from the "
                 r"run that made it$" % helper.pid),
                ({"boot": self.OTHER_BOOT, "machine": self.OTHER_MACHINE},
                 r"guard run pid \d+ ran under another kernel \(boot id %s\), and its machine "
                 r"id %s is not this one, so it may still be running on another machine that "
                 r"shares this clone$" % (self.OTHER_BOOT, self.OTHER_MACHINE))):
            with self.subTest(fields=fields):
                self.write_owner(root, **fields)
                result, _ran = self.run_guard()
                self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
                self.assertEqual(self.leftover_commands(result.stderr), [], result.stderr)
                alone = self.report_all_read(inventory=(helper.pid,))
                self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
                # The real guard's report or a correctly reported
                # incomplete scan; the report alone.
                for err in self.complete_reports(result.stderr, alone.stdout):
                    self.assert_inspect(err, root, reason)
        self.assertIsNone(helper.poll(), "the report stopped a process")

    def test_run_identity_is_its_start_time_not_its_command_line(self):
        # FLIP TABLE: whether the run that made a directory still runs is
        # read from its pid and start time, not its command line: a live
        # process with the recorded start time is that run (INSPECT),
        # whatever it runs, and the same pid with another start time is a
        # reused pid, so the run has ended (REMOVABLE).
        self.change(".web/templates-draft/landing.html")
        root, checkouts = self.make_leftover(1)
        helper = self.live_helper()
        stat = Path("/proc/%d/stat" % helper.pid).read_bytes()
        start = stat[stat.rindex(b")") + 2:].split()[19].decode("ascii")
        self.write_owner(root, pid=helper.pid, start=start)
        result, _ran = self.run_guard()
        self.assertEqual(self.leftover_commands(result.stderr), [], result.stderr)
        alone = self.report_all_read(inventory=(helper.pid,))
        self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
        # The real guard's report or a correctly reported incomplete
        # scan; the report alone.
        for err in self.complete_reports(result.stderr, alone.stdout):
            self.assert_inspect(err, root, "guard run pid %d is still running$" % helper.pid)
        self.write_owner(root, pid=helper.pid, start=str(int(start) + 1))
        result, _ran = self.run_guard()
        self.assert_removable(result.stderr, root, checkouts, re.escape(
            "pid %d is now another process (its start time differs from the record)" % helper.pid),
            inventory=(helper.pid,))
        # Under another boot id of this machine (an earlier boot), the live
        # process with the recorded pid and start time is not that run.
        if self.machine_id() != "-":
            self.write_owner(root, pid=helper.pid, start=start, boot=self.OTHER_BOOT)
            result, _ran = self.run_guard()
            self.assert_removable(result.stderr, root, checkouts, re.escape(
                "guard run pid %d ran during an earlier boot of this machine (its boot id "
                "differs, its machine id is this one)" % helper.pid), inventory=(helper.pid,))
        self.assertIsNone(helper.poll(), "the report stopped a process")

    def test_clean_start_prints_no_leftover_report(self):
        # FLIP TABLE (leftover report): nothing left means no leftover line,
        # even beside another clone's shard directory (its checkout also
        # named repo, its guard-owner record naming that clone) under TMPDIR
        # and a checkout of this clone that the guard did not make.
        self.change(".web/templates-draft/landing.html")
        other = Path(self.tmp.name) / "other" / "repo"
        other.mkdir(parents=True)
        for args in (("init", "-q"),
                     ("-c", "user.email=o@example.com", "-c", "user.name=o", "commit", "-q",
                      "--allow-empty", "-m", "Other")):
            subprocess.run(["git", *args], cwd=other, env=self.env, check=True,
                           capture_output=True, timeout=30)
        foreign = Path(tempfile.mkdtemp(prefix="grc-gate36-shards.", dir=self.shard_tmp))
        self.write_owner(foreign, clone=other)
        (foreign / "shard-1").mkdir()
        subprocess.run(["git", "worktree", "add", "--detach", str(foreign / "shard-1" / "repo"),
                        "HEAD"], cwd=other, env=self.env, check=True, capture_output=True,
                       timeout=30)
        self.git("worktree", "add", "--detach", str(Path(self.tmp.name) / "side"), "HEAD")
        result, _ran = self.run_guard()
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        output = result.stdout + result.stderr
        for text in ("LEFTOVERS", "leftover", "Left behind", "git worktree prune",
                     "INCOMPLETE", "UNREADABLE"):
            self.assertNotIn(text, output)

    def test_leftover_report_signals_and_deletes_nothing(self):
        # FLIP TABLE (leftover report): a leftover a process still uses is
        # INSPECT, with that process and how it uses it, and no command to
        # stop it or remove it; the report stops nothing and removes
        # nothing: the process still runs, and every directory and
        # registration is still there.
        self.change(".web/templates-draft/landing.html")
        root, checkouts = self.make_leftover(2)
        helper = self.live_helper(cwd=checkouts[0])
        result, _ran = self.run_guard()
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        self.assertNotIn("kill", result.stderr)
        self.assertEqual(self.leftover_commands(result.stderr), [], result.stderr)
        alone = self.report_all_read(inventory=(helper.pid,))
        self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
        # The real guard's report or a correctly reported incomplete
        # scan; the report alone.
        for err in self.complete_reports(result.stderr, alone.stdout):
            self.assert_inspect_in_use(err, root, helper.pid)
        self.assertIsNone(helper.poll(), "the report stopped a process")
        self.assertTrue(root.is_dir(), root)
        for checkout in checkouts:
            self.assertTrue((checkout / ".claude/skills/corpus-management/tools" / "pre-push-guard.sh").is_file(), checkout)
        worktrees = self.git("worktree", "list", "--porcelain").stdout
        for checkout in checkouts:
            self.assertIn("worktree %s\n" % checkout, worktrees)

    def assert_inspect_in_use(self, err, root, pid):
        """root, in report err, is INSPECT for one process, pid (a
        live_helper process in it), with the NOT PROVED stop procedure and no
        command (test_leftover_report_signals_and_deletes_nothing)."""
        self.assert_inspect(err, root, re.escape("1 process(es) use it, listed below"))
        self.assertIn("    used by pid %d: " % pid, err)
        self.assertIn("(working directory)\n", err)
        self.assertNotIn("kill", err)
        # FLIP TABLE: a leftover with a detected user gets a clearly
        # conditional, NOT PROVED manual stop procedure: recheck the
        # pid's start time and command line (both printed) just before
        # any signal, never for this guard, the processes that started
        # this push, a pre-push guard or a live run, then push again and
        # remove only what that report marks REMOVABLE. It is never a
        # signal command (no line of it is one). It claims labels only
        # for the guards the report identified, since a run with no run
        # record it read (a fast-path run writes none) is not labelled
        # (in the earlier repository it said each such process was
        # "labelled above").
        start = self.start_time(pid)
        block = "\n".join(self.leftover_block(err, root)) + "\n"
        self.assertNotIn("each labelled above", block)
        self.assertIn(
            "    NOT PROVED, so no stop command: the report does not prove that a process using "
            "it is abandoned. To stop one by hand (never this guard, a process that started "
            "this push, a pre-push guard or a process one started; only the guards the report "
            "identified are labelled above, and a guard run whose run record it did not read, "
            "such as a fast-path run, which writes none, is not), check:\n"
            "      1. that no run of this guard that could have made it is still running, on "
            "this host or on another host, VM or container that shares this clone (a live run "
            "uses its own shard directory: let it end);\n"
            "      2. that the process is not part of another push (no pre-push guard among its "
            "parents) and that stopping it loses nothing you need;\n"
            "      3. just before any signal, that the pid is still the process listed here, "
            "since a pid can be reused: its start time (field 22 of /proc/<pid>/stat) and its "
            "command line (/proc/<pid>/cmdline) must still be:\n", block)
        self.assertRegex(block, r"(?m)^           pid %d: start time %s, command line "
                                r"\S*python\S* -I -c import sys\\x0asys\.stdout\.write\(.*\n"
                                r"      Only then, by your own judgement, stop it \(TERM before "
                                r"anything stronger\); then push again, and remove the leftover "
                                r"only if the report of that push marks it REMOVABLE\.$"
                         % (pid, start))
        for line in block.splitlines():
            self.assertFalse(line.strip().startswith(("kill", "pkill", "killall")), line)
        self.assertEqual(self.leftover_commands(block), [], block)

    # A process that opens the file argv[1], writes "ready" (its
    # handshake) and then reads its stdin, a pipe the test holds, until
    # that pipe closes.
    OPEN_HOLDER = ("import sys\n"
                   "held = open(sys.argv[1])\n"
                   "sys.stdout.write('ready\\n')\n"
                   "sys.stdout.flush()\n"
                   "sys.stdin.buffer.read()\n")

    def test_open_file_inside_a_leftover_is_in_use(self):
        # FLIP TABLE: a process whose working directory is elsewhere but
        # which holds a file inside a leftover open is using it, so the
        # leftover is INSPECT.
        self.change(".web/templates-draft/landing.html")
        root, checkouts = self.make_leftover(1)
        held = checkouts[0] / "README.md"
        # It opens the file before its handshake, so the file is open once
        # live_process returns.
        helper, _line = self.live_process(self.OPEN_HOLDER, str(held))
        self.assertIn(str(held), [os.readlink("/proc/%d/fd/%s" % (helper.pid, fd))
                                  for fd in os.listdir("/proc/%d/fd" % helper.pid)])
        result, _ran = self.run_guard()
        self.assertEqual(self.leftover_commands(result.stderr), [], result.stderr)
        alone = self.report_all_read(inventory=(helper.pid,))
        self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
        # The real guard's report or a correctly reported incomplete
        # scan; the report alone.
        for err in self.complete_reports(result.stderr, alone.stdout):
            self.assert_inspect(err, root, re.escape("1 process(es) use it, listed below"))
            self.assertRegex(err, r"(?m)^    used by pid %d: .* \(open file\)$" % helper.pid)

    # A process whose thread-group leader calls pthread_exit while a second
    # thread keeps running in the working directory argv[1]; that thread
    # prints the pid once the leader is a zombie (its handshake), then reads
    # its stdin, a pipe the test holds, until that pipe closes, which ends
    # the process.
    EXITED_LEADER = (
        "import ctypes, os, sys, threading, time\n"
        "os.chdir(sys.argv[1])\n"
        "pid = os.getpid()\n"
        "def keep():\n"
        "    deadline = time.monotonic() + 10\n"
        "    while time.monotonic() < deadline:\n"
        "        with open('/proc/%d/stat' % pid, 'rb') as f:\n"
        "            data = f.read()\n"
        "        if data[data.rindex(b')') + 2:].split()[0] == b'Z':\n"
        "            break\n"
        "        time.sleep(0.01)\n"
        "    sys.stdout.write('%d\\n' % pid)\n"
        "    sys.stdout.flush()\n"
        "    sys.stdin.buffer.read()\n"
        "threading.Thread(target=keep).start()\n"
        "ctypes.CDLL(None).pthread_exit(None)\n")

    def test_thread_of_an_exited_leader_is_read(self):
        # FLIP TABLE (confirmed by a probe in the earlier repository): when
        # the thread-group leader of a process has exited (pthread_exit)
        # while another thread runs, the leader's /proc entries (working
        # directory, root, descriptors, mappings, command line) are gone,
        # but the process is not: the report reads every thread, so a
        # thread whose working directory is inside a leftover makes it
        # INSPECT, listed with its command line, even as on a host where
        # every process is read (in the earlier repository the process was
        # skipped as gone).
        # The fixture is a live_process, started outside the leftover.
        self.change(".web/templates-draft/landing.html")
        root, checkouts = self.make_leftover(1)
        helper, pid, _tid = self.start_exited_leader(checkouts[0])
        with self.assertRaises(FileNotFoundError):
            os.readlink("/proc/%d/cwd" % pid)
        used = (r"(?m)^    used by pid %d: \S*python\S* -I -c .* \(working directory\)$" % pid)
        result, _ran = self.run_guard()
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        self.assertEqual(self.leftover_commands(result.stderr), [], result.stderr)
        alone = self.report_all_read(inventory=(pid,))
        self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
        # The real guard's report or a correctly reported incomplete
        # scan; the report alone.
        for err in self.complete_reports(result.stderr, alone.stdout):
            self.assert_inspect(err, root, re.escape("1 process(es) use it, listed below"))
            self.assertRegex(err, used)
        self.assertIsNone(helper.poll(), "the report stopped a process")

    def start_exited_leader(self, where):
        """The EXITED_LEADER fixture, a live_process, started outside any
        leftover, its surviving thread in where: (helper, pid, tid), where
        tid is that of the surviving thread, once its leader is a zombie
        and the process has two threads."""
        helper, line = self.live_process(self.EXITED_LEADER, str(where))
        pid = int(line)
        self.assertEqual(pid, helper.pid)
        status = Path("/proc/%d/status" % pid).read_text(encoding="ascii")
        self.assertRegex(status, r"(?m)^State:\s+Z")
        self.assertRegex(status, r"(?m)^Threads:\s+2$")
        tids = [int(t) for t in os.listdir("/proc/%d/task" % pid) if int(t) != pid]
        self.assertEqual(len(tids), 1, tids)
        return helper, pid, tids[0]

    def test_all_read_harness_keeps_a_live_thread_of_an_exited_leader_unread(self):
        # FLIP TABLE: the ALL_READ harness takes a process whose read raised
        # an OSError that is not a permission error as exited only when
        # every one of its threads has ended, not when its leader alone has.
        # Here the leader of the EXITED_LEADER fixture has exited (a zombie,
        # two threads) while its surviving thread runs in a leftover, and
        # reading the working directory of that thread fails with EIO
        # (UNREAD_THREAD): the process stays one that cannot be read
        # (INSPECT, counted as yours), where in the earlier repository the
        # zombie leader made the harness drop it as exited and the leftover
        # was REMOVABLE.
        # Control: without the error the thread is read and listed.
        root, checkouts = self.make_leftover(1)
        helper, pid, tid = self.start_exited_leader(checkouts[0])
        inventory = (pid,)
        read = self.report_all_read(inventory=inventory)
        self.assertEqual(read.returncode, 0, read.stdout + read.stderr)
        self.assert_inspect(read.stdout, root, re.escape("1 process(es) use it, listed below"))
        self.assertRegex(read.stdout, r"(?m)^    used by pid %d: \S*python\S* -I -c .* "
                                      r"\(working directory\)$" % pid)
        unread = self.report_all_read(prelude=self.UNREAD_THREAD, inventory=inventory,
                                      UNREAD_THREAD="/proc/%d/task/%d/cwd" % (pid, tid))
        self.assertEqual(unread.returncode, 0, unread.stdout + unread.stderr)
        self.assert_counted_unread(unread.stdout, root)
        self.assertNotIn("REMOVABLE", unread.stdout)
        self.assertNotIn("used by pid %d" % pid, unread.stdout)
        self.assertIsNone(helper.poll(), "the report stopped a process")

    # A process whose leader keeps its working directory (where it started,
    # outside the leftover) while a second thread unshares its file-system
    # state (unshare with CLONE_FS, through ctypes, in this fixture only)
    # and moves its own working directory into argv[1]; that thread prints
    # "<pid> <tid>" once moved (its handshake) and then waits; the leader
    # reads its stdin, a pipe the test holds, until that pipe closes, which
    # ends the process.
    OWN_CWD_THREAD = (
        "import ctypes, os, sys, threading\n"
        "libc = ctypes.CDLL(None, use_errno=True)\n"
        "def move():\n"
        "    if libc.unshare(0x00000200) != 0:\n"
        "        raise OSError(ctypes.get_errno(), 'unshare(CLONE_FS) failed')\n"
        "    os.chdir(sys.argv[1])\n"
        "    sys.stdout.write('%d %d\\n' % (os.getpid(), threading.get_native_id()))\n"
        "    sys.stdout.flush()\n"
        "    threading.Event().wait()\n"
        "threading.Thread(target=move, daemon=True).start()\n"
        "sys.stdin.buffer.read()\n")
    # A prelude for the report that makes reading the working directory of
    # the thread whose /proc path is UNREAD_THREAD fail with EIO (not a
    # permission error, which the ALL_READ harness takes as an exited
    # process).
    UNREAD_THREAD = (
        "import os\n"
        "_readlink = os.readlink\n"
        "def _unread_readlink(path, *args, **kwargs):\n"
        "    if path == os.environ.get('UNREAD_THREAD'):\n"
        "        raise OSError(5, 'Input/output error')\n"
        "    return _readlink(path, *args, **kwargs)\n"
        "os.readlink = _unread_readlink\n")

    def test_thread_with_its_own_working_directory_is_read_under_a_live_leader(self):
        # FLIP TABLE: every thread of a process is read for its own working
        # directory, root and descriptors, not only when the leader has
        # exited: a thread that has unshared its file-system state and moved
        # into a leftover, while its leader runs elsewhere, makes it
        # INSPECT, listed, even as on a host where every process is read
        # (in the earlier repository the leader was read alone and the
        # leftover was REMOVABLE). A thread whose state cannot be read makes
        # its process unreadable, so the leftover is INSPECT for that, not
        # REMOVABLE.
        # The fixture is a live_process, started outside the leftover.
        self.change(".web/templates-draft/landing.html")
        root, checkouts = self.make_leftover(1)
        helper, pid, tid = self.start_own_cwd_thread(checkouts[0])
        self.assertEqual(os.readlink("/proc/%d/cwd" % pid), os.path.realpath(self.tmp.name))
        self.assertEqual(os.readlink("/proc/%d/task/%d/cwd" % (pid, tid)), str(checkouts[0]))
        used = r"(?m)^    used by pid %d: \S*python\S* -I -c .* \(working directory\)$" % pid
        result, _ran = self.run_guard()
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        self.assertEqual(self.leftover_commands(result.stderr), [], result.stderr)
        alone = self.report_all_read(inventory=(pid,))
        self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
        # The real guard's report or a correctly reported incomplete
        # scan; the report alone.
        for err in self.complete_reports(result.stderr, alone.stdout):
            self.assert_inspect(err, root, re.escape("1 process(es) use it, listed below"))
            self.assertRegex(err, used)
        unread = self.report_all_read(prelude=self.UNREAD_THREAD, inventory=(pid,),
                                      UNREAD_THREAD="/proc/%d/task/%d/cwd" % (pid, tid))
        self.assertEqual(unread.returncode, 0, unread.stdout + unread.stderr)
        self.assert_inspect(unread.stdout, root, self.UNREAD)
        counted = re.search(self.UNREAD[:-1], unread.stdout, re.M)
        self.assertGreater(int(counted.group(1)), 0, unread.stdout)
        self.assertNotIn("used by pid %d" % pid, unread.stdout)
        self.assertIsNone(helper.poll(), "the report stopped a process")

    # A prelude for the report that scripts what /proc shows of one live
    # process as it exits: reading the link FAKE_LINK fails with errno
    # FAKE_LINK_ERRNO (2 is a missing entry, 5 is EIO, not a permission
    # error), and each file FAKE_STAT names (space-separated), opened
    # through os.open (as the report and the ALL_READ harness read a
    # stat), holds the real one changed as FAKE_STAT_HOW says: "gone" (no
    # such file), "zombie" (state Z), "exiting" (PF_EXITING, 0x4, set in
    # its flags) or "live" (as read). The file FAKE_MAPS, opened through
    # os.open (as the report reads mappings), holds FAKE_MAPS_TEXT, by
    # default nothing.
    SCRIPTED_EXIT = (
        "import os\n"
        "_readlink, _open = os.readlink, os.open\n"
        "def _scripted_readlink(path, *args, **kwargs):\n"
        "    if path == os.environ.get('FAKE_LINK'):\n"
        "        code = int(os.environ['FAKE_LINK_ERRNO'])\n"
        "        raise OSError(code, os.strerror(code))\n"
        "    return _readlink(path, *args, **kwargs)\n"
        "def _scripted_open(path, *args, **kwargs):\n"
        "    if path == os.environ.get('FAKE_MAPS'):\n"
        "        reader, writer = os.pipe()\n"
        "        os.write(writer, os.environ.get('FAKE_MAPS_TEXT', '').encode())\n"
        "        os.close(writer)\n"
        "        return reader\n"
        "    if path not in os.environ.get('FAKE_STAT', '').split():\n"
        "        return _open(path, *args, **kwargs)\n"
        "    how = os.environ['FAKE_STAT_HOW']\n"
        "    if how == 'gone':\n"
        "        raise FileNotFoundError(2, os.strerror(2))\n"
        "    fd = _open(path, *args, **kwargs)\n"
        "    try:\n"
        "        data = os.read(fd, 4096)\n"
        "    finally:\n"
        "        os.close(fd)\n"
        "    cut = data.rindex(b')') + 2\n"
        "    rest = data[cut:].split(b' ')\n"
        "    if how == 'zombie':\n"
        "        rest[0] = b'Z'\n"
        "    elif how == 'exiting':\n"
        "        rest[6] = b'%d' % (int(rest[6]) | 0x4)\n"
        "    elif how != 'live':\n"
        "        raise ValueError(how)\n"
        "    reader, writer = os.pipe()\n"
        "    os.write(writer, data[:cut] + b' '.join(rest))\n"
        "    os.close(writer)\n"
        "    return reader\n"
        "os.readlink, os.open = _scripted_readlink, _scripted_open\n")

    def start_own_cwd_thread(self, where):
        """The OWN_CWD_THREAD fixture, a live_process, started outside any
        leftover, its second thread moved to where: (helper, pid, tid)."""
        helper, line = self.live_process(self.OWN_CWD_THREAD, str(where))
        pid, tid = (int(n) for n in line.split())
        self.assertEqual(pid, helper.pid)
        self.assertNotEqual(pid, tid)
        return helper, pid, tid

    def assert_all_read_removable(self, alone, root, checkouts):
        """The report run through ALL_READ found root REMOVABLE, with the
        commands that remove it."""
        self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
        block = self.leftover_block(alone.stdout, root)
        self.assertIsNotNone(block, alone.stdout)
        self.assertTrue(block[0].startswith("  %s: REMOVABLE: " % root), alone.stdout)
        self.assertEqual(self.leftover_commands("\n".join(block)),
                         self.removable_commands(root, checkouts), alone.stdout)

    def assert_counted_unread(self, out, root):
        """root is INSPECT because processes could not be read, one of them
        at least of this user."""
        self.assert_inspect(out, root, self.UNREAD)
        counted = re.search(self.UNREAD[:-1], out, re.M)
        self.assertGreater(int(counted.group(1)), 0, out)

    def test_all_read_harness_takes_a_process_as_exited_only_when_it_is_exiting(self):
        # FLIP TABLE: the ALL_READ harness takes a process whose read raised
        # an OSError that is not a permission error (here EIO reading its
        # working directory, scripted) as one that has exited only when its
        # /proc/<pid>/stat, read again, shows it gone, a zombie or exiting
        # (PF_EXITING), each scripted: the leftover is then REMOVABLE, where
        # in the earlier repository the process was counted unread and the
        # leftover was INSPECT (as a process of this user caught as it exits
        # made it, at random). The stat of every thread is scripted too,
        # since the harness takes a process as exited only when each of its
        # threads has ended. Controls: the same error on a live process
        # keeps it one that cannot be read (INSPECT, counted as yours), and
        # so does the same error on a process whose leader alone is scripted
        # a zombie while its other thread is live (in the earlier repository
        # the harness took that process as exited); so the harness ignores
        # no error of a process any thread of which is live (scripted here;
        # the EXITED_LEADER fixture checks it on a real exited leader).
        root, checkouts = self.make_leftover(1)
        helper, pid, tid = self.start_own_cwd_thread(self.tmp.name)
        leader = "/proc/%d/stat /proc/%d/task/%d/stat" % (pid, pid, pid)
        every = "%s /proc/%d/task/%d/stat" % (leader, pid, tid)
        scripted = dict(FAKE_LINK="/proc/%d/cwd" % pid, FAKE_LINK_ERRNO="5",
                        inventory=(pid,))
        for how in ("exiting", "zombie", "gone"):
            with self.subTest(how):
                alone = self.report_all_read(prelude=self.SCRIPTED_EXIT, FAKE_STAT_HOW=how,
                                             FAKE_STAT=every, **scripted)
                self.assert_all_read_removable(alone, root, checkouts)
        live = self.report_all_read(prelude=self.SCRIPTED_EXIT, FAKE_STAT_HOW="live",
                                    FAKE_STAT=every, **scripted)
        self.assertEqual(live.returncode, 0, live.stdout + live.stderr)
        self.assert_counted_unread(live.stdout, root)
        for how in ("zombie", "exiting"):
            with self.subTest("leader alone " + how):
                alone = self.report_all_read(prelude=self.SCRIPTED_EXIT, FAKE_STAT_HOW=how,
                                             FAKE_STAT=leader, **scripted)
                self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
                self.assert_counted_unread(alone.stdout, root)
        self.assertIsNone(helper.poll(), "the report stopped a process")

    # A prelude for the report that scripts how /proc lists the threads of
    # one process: the first listing of the directory FAKE_TASK shows its
    # threads as they are, and each later one also shows the threads
    # FAKE_TASK_NEW names (space-separated), as when a thread is created
    # after the first listing. Each listing is noted, its names sorted, as
    # one line of the file FAKE_TASK_LOG.
    SCRIPTED_TASKS = (
        "import os\n"
        "_task_listdir = os.listdir\n"
        "_task_listed = []\n"
        "def _scripted_listdir(path='.'):\n"
        "    names = _task_listdir(path)\n"
        "    if path != os.environ.get('FAKE_TASK'):\n"
        "        return names\n"
        "    if _task_listed:\n"
        "        names = names + os.environ.get('FAKE_TASK_NEW', '').split()\n"
        "    _task_listed.append(path)\n"
        "    with open(os.environ['FAKE_TASK_LOG'], 'a', encoding='ascii') as f:\n"
        "        f.write(' '.join(sorted(names)) + '\\n')\n"
        "    return names\n"
        "os.listdir = _scripted_listdir\n")

    def test_all_read_harness_keeps_a_process_whose_threads_change_unread(self):
        # FLIP TABLE: the ALL_READ harness lists the threads of a process
        # again once it has read the stat of each, and takes the process as
        # exited only when both listings are the same and every thread has
        # ended, since a thread created after the first listing is not read.
        # Here a live process (OWN_CWD_THREAD, a live_process, started
        # outside the leftover) has reading its working directory fail with
        # EIO, and the stat of its leader and of each of its threads
        # scripted exiting. When the second listing of its threads also
        # shows a thread the first did not (scripted), the process stays one
        # that cannot be read (INSPECT, counted as yours), where with one
        # listing the harness took it as exited and the leftover was
        # REMOVABLE. Control: with the same threads in both listings it is
        # taken as exited (REMOVABLE). The log shows that each run listed
        # the threads twice, and what each listing showed.
        root, checkouts = self.make_leftover(1)
        helper, pid, tid = self.start_own_cwd_thread(self.tmp.name)
        every = "/proc/%d/stat /proc/%d/task/%d/stat /proc/%d/task/%d/stat" % (
            pid, pid, pid, pid, tid)
        threads = [str(pid), str(tid)]
        # Above the largest pid_max (2**22), so no thread has this id.
        new = str(2 ** 22 + 1)
        for case, added in (("same threads", []), ("a thread created", [new])):
            with self.subTest(case):
                log = Path(self.tmp.name) / ("tasks-%d.log" % len(added))
                alone = self.report_all_read(
                    prelude=self.SCRIPTED_EXIT + self.SCRIPTED_TASKS,
                    inventory=(pid,), FAKE_LINK="/proc/%d/cwd" % pid,
                    FAKE_LINK_ERRNO="5", FAKE_STAT=every, FAKE_STAT_HOW="exiting",
                    FAKE_TASK="/proc/%d/task" % pid, FAKE_TASK_NEW=" ".join(added),
                    FAKE_TASK_LOG=str(log))
                if added:
                    self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
                    self.assert_counted_unread(alone.stdout, root)
                    self.assertNotIn("REMOVABLE", alone.stdout)
                else:
                    self.assert_all_read_removable(alone, root, checkouts)
                self.assertEqual(log.read_text(encoding="ascii").splitlines(),
                                 [" ".join(sorted(threads)),
                                  " ".join(sorted(threads + added))], alone.stdout)
        self.assertIsNone(helper.poll(), "the report stopped a process")

    def test_thread_whose_entries_go_while_it_exits_holds_nothing(self):
        # FLIP TABLE: the report itself counts a thread whose entries are
        # found missing as read when its stat then shows it exiting
        # (PF_EXITING), though not yet a zombie: here the second thread of a
        # live process, whose working directory is scripted missing and its
        # stat exiting. The leftover is REMOVABLE, where in the earlier
        # repository the process could not be read (INSPECT); the ALL_READ
        # harness cannot do this, since the leader it reads again is live.
        # Controls: the same missing entry on a thread that is not exiting
        # keeps the process one that cannot be read; and an exiting thread
        # whose entries are all present is still read, so one whose working
        # directory is in the leftover makes it INSPECT, listed.
        root, checkouts = self.make_leftover(1)
        helper, pid, tid = self.start_own_cwd_thread(self.tmp.name)
        scripted = dict(FAKE_LINK="/proc/%d/task/%d/cwd" % (pid, tid), FAKE_LINK_ERRNO="2",
                        FAKE_STAT="/proc/%d/task/%d/stat" % (pid, tid),
                        inventory=(pid,))
        alone = self.report_all_read(prelude=self.SCRIPTED_EXIT, FAKE_STAT_HOW="exiting",
                                     **scripted)
        self.assert_all_read_removable(alone, root, checkouts)
        live = self.report_all_read(prelude=self.SCRIPTED_EXIT, FAKE_STAT_HOW="live", **scripted)
        self.assertEqual(live.returncode, 0, live.stdout + live.stderr)
        self.assert_counted_unread(live.stdout, root)
        self.assertNotIn("used by pid %d" % pid, live.stdout)
        inside, in_pid, in_tid = self.start_own_cwd_thread(checkouts[0])
        self.assertEqual(os.readlink("/proc/%d/task/%d/cwd" % (in_pid, in_tid)),
                         str(checkouts[0]))
        used = self.report_all_read(prelude=self.SCRIPTED_EXIT, FAKE_STAT_HOW="exiting",
                                    FAKE_STAT="/proc/%d/task/%d/stat" % (in_pid, in_tid),
                                    inventory=(pid, in_pid))
        self.assertEqual(used.returncode, 0, used.stdout + used.stderr)
        self.assert_inspect(used.stdout, root, re.escape("1 process(es) use it, listed below"))
        self.assertRegex(used.stdout, r"(?m)^    used by pid %d: \S*python\S* -I -c .* "
                                      r"\(working directory\)$" % in_pid)
        self.assertIsNone(helper.poll(), "the report stopped a process")
        self.assertIsNone(inside.poll(), "the report stopped a process")

    # A process that maps the file argv[1] through libc mmap (so that once
    # its own descriptor is closed it holds no descriptor of that file) and
    # starts a second thread, which waits; it prints its pid once both run
    # (its handshake), then reads its stdin, a pipe the test holds, until
    # that pipe closes, which ends the process. Its working directory is
    # where it started.
    MAPPED_ONLY = (
        "import ctypes, os, sys, threading\n"
        "libc = ctypes.CDLL(None, use_errno=True)\n"
        "libc.mmap.restype = ctypes.c_void_p\n"
        "libc.mmap.argtypes = (ctypes.c_void_p, ctypes.c_size_t, ctypes.c_int, ctypes.c_int,\n"
        "                      ctypes.c_int, ctypes.c_long)\n"
        "fd = os.open(sys.argv[1], os.O_RDONLY)\n"
        "addr = libc.mmap(None, 4096, 1, 1, fd, 0)\n"
        "if addr is None or addr == ctypes.c_void_p(-1).value:\n"
        "    raise OSError(ctypes.get_errno(), 'mmap failed')\n"
        "os.close(fd)\n"
        "threading.Thread(target=threading.Event().wait, daemon=True).start()\n"
        "sys.stdout.write('%d\\n' % os.getpid())\n"
        "sys.stdout.flush()\n"
        "sys.stdin.buffer.read()\n")

    def test_leader_with_no_mapping_has_the_mappings_of_every_thread_read(self):
        # FLIP TABLE: the report reads the mappings of every thread of a
        # process when its leader, read whole, showed no mapping or is
        # exiting (PF_EXITING) while other threads run, as a leader caught
        # exiting can be read. Here a live process (MAPPED_ONLY, a
        # live_process, started outside the leftover) uses a leftover only
        # through a mapping of a file in it, and has a second thread. With
        # its leader's mappings scripted empty, or its leader's stat
        # scripted exiting and its mappings scripted to one mapping
        # elsewhere, the mapping is still found through the other thread:
        # INSPECT, listed as a mapped file (in the earlier repository the
        # mappings of the leader alone were read and the leftover was
        # REMOVABLE).
        # Control: read as it is, the leader's own mappings show it.
        root, checkouts = self.make_leftover(1)
        held = checkouts[0] / "README.md"
        helper, line = self.live_process(self.MAPPED_ONLY, str(held))
        pid = int(line)
        self.assertEqual(pid, helper.pid)
        self.assertEqual(len(os.listdir("/proc/%d/task" % pid)), 2)
        self.assertIn(" %s\n" % held, Path("/proc/%d/maps" % pid).read_text(encoding="utf-8"))
        self.assertNotIn(str(held), [os.readlink("/proc/%d/fd/%s" % (pid, fd))
                                     for fd in os.listdir("/proc/%d/fd" % pid)])
        used = r"(?m)^    used by pid %d: \S*python\S* -I -c .* \(mapped file\)$" % pid
        maps = "/proc/%d/maps" % pid
        elsewhere = "00400000-00401000 r--p 00000000 00:00 0 /nowhere\n"
        for case, scripted in (
                ("as read", {}),
                ("leader shows no mapping", dict(FAKE_MAPS=maps)),
                ("leader exiting", dict(FAKE_MAPS=maps, FAKE_MAPS_TEXT=elsewhere,
                                        FAKE_STAT="/proc/%d/stat" % pid,
                                        FAKE_STAT_HOW="exiting"))):
            with self.subTest(case):
                alone = self.report_all_read(prelude=self.SCRIPTED_EXIT,
                                             inventory=(pid,), **scripted)
                self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
                self.assert_inspect(alone.stdout, root,
                                    re.escape("1 process(es) use it, listed below"))
                self.assertRegex(alone.stdout, used)
        self.assertIsNone(helper.poll(), "the report stopped a process")

    # A process that moves into the directory argv[1], prints its pid (its
    # handshake) and then reads its stdin, a pipe the test holds, until that
    # pipe closes.
    MOVED_SLEEPER = ("import os, sys; os.chdir(sys.argv[1]); print(os.getpid(), flush=True); "
                     "sys.stdin.buffer.read()")

    def test_fixture_inventory_lists_only_the_fixture_processes(self):
        # FLIP TABLE: a test that asserts an outcome through ALL_READ gives
        # the report a deterministic process inventory, its own fixture
        # processes and the report itself (NO_OTHER_PROCESS with
        # FIXTURE_PIDS), so neither another process of the host nor how long
        # a scan of every process takes decides it. Here two processes (each
        # a live_process, started outside the leftover) move into a
        # leftover: with one of them in the inventory, it alone is listed
        # (INSPECT); with neither, the leftover is REMOVABLE with its
        # commands (a scan of every process of the host would list both).
        root, checkouts = self.make_leftover(1)
        started = []
        for _ in range(2):
            helper, line = self.live_process(self.MOVED_SLEEPER, str(checkouts[0]))
            started.append((helper, int(line)))
        (first, first_pid), (second, second_pid) = started
        for pid in (first_pid, second_pid):
            self.assertEqual(os.readlink("/proc/%d/cwd" % pid), str(checkouts[0]))
        one = self.report_all_read(inventory=(first_pid,))
        self.assertEqual(one.returncode, 0, one.stdout + one.stderr)
        self.assert_inspect(one.stdout, root, re.escape("1 process(es) use it, listed below"))
        self.assertRegex(one.stdout, self.user_line(first_pid))
        self.assertNotIn("used by pid %d" % second_pid, one.stdout)
        self.assert_all_read_removable(self.report_all_read(inventory=()), root, checkouts)
        for helper, _pid in started:
            self.assertIsNone(helper.poll(), "the report stopped a process")

    @staticmethod
    def kthreadd():
        """(2,) when /proc shows pid 2 as a kernel thread (kthreadd, which
        never exits, in the initial pid namespace), otherwise ()."""
        try:
            data = Path("/proc/2/stat").read_bytes()
            flags = int(data[data.rindex(b")") + 2:].split()[6])
        except (OSError, ValueError, IndexError):
            return ()
        return (2,) if flags & 0x00200000 else ()

    @staticmethod
    def unreadable_processes():
        """(of yours, of other users, kernel threads): the processes whose
        working directory this test cannot read."""
        mine, others, kernel = 0, 0, 0
        me = str(os.geteuid())
        for pid in (n for n in os.listdir("/proc") if n.isdigit()):
            try:
                os.readlink("/proc/%s/cwd" % pid)
                continue
            except PermissionError:
                pass
            except OSError:
                continue
            try:
                data = Path("/proc/%s/stat" % pid).read_bytes()
                if int(data[data.rindex(b")") + 2:].split()[6]) & 0x00200000:
                    kernel += 1
                    continue
                uids = [line.split()[1:3] for line in
                        Path("/proc/%s/status" % pid).read_text(encoding="ascii").splitlines()
                        if line.startswith("Uid:")][0]
            except (OSError, ValueError, IndexError):
                continue
            if me in uids:
                mine += 1
            else:
                others += 1
        return mine, others, kernel

    # A process that writes "ready" (its handshake), waits for a line on its
    # stdin, makes itself non-dumpable (prctl PR_SET_DUMPABLE 0, as ssh-agent
    # and gpg-agent do), writes "non-dumpable" and then reads its stdin, a
    # pipe the test holds, until that pipe closes.
    NON_DUMPABLE = ("import ctypes, sys\n"
                    "sys.stdout.write('ready\\n')\n"
                    "sys.stdout.flush()\n"
                    "sys.stdin.buffer.readline()\n"
                    "ctypes.CDLL(None).prctl(4, 0, 0, 0, 0)\n"
                    "sys.stdout.write('non-dumpable\\n')\n"
                    "sys.stdout.flush()\n"
                    "sys.stdin.buffer.read()\n")

    def test_unreadable_process_blocks_removal_whoever_owns_it(self):
        # FLIP TABLE: a process that cannot be read leaves whether a
        # leftover is in use unknown, so it is INSPECT, whoever owns that
        # process and whatever the directory's mode (0700 here): a process
        # of another user, root included, no longer lets the report print a
        # removal command. Only kernel threads are set aside: as on a host
        # where every other process is read (report_all_read, which leaves
        # kernel threads unreadable), it is REMOVABLE. A process of this
        # user made non-dumpable (as ssh-agent and gpg-agent make
        # themselves, confirmed by a probe in the earlier repository) blocks
        # it too. The report alone reads a deterministic inventory: no
        # fixture process, plus kthreadd (pid 2) where /proc shows it as a
        # kernel thread, which never exits. The report sets a kernel thread
        # aside only when reading it fails, so this case exercises that
        # exclusion only where reading /proc/2/cwd is refused, as for a user
        # who is not root; elsewhere (root reads it, so nothing is set
        # aside) the case is skipped, saying why, and the rest of the test
        # runs. The real guard's report may be a correctly reported
        # incomplete scan of the host's processes; the non-dumpable process
        # is also checked by the report alone, against an inventory of that
        # process only.
        self.change(".web/templates-draft/landing.html")
        root, checkouts = self.make_leftover(1)
        self.assertEqual(root.stat().st_mode & 0o7777, 0o700)
        with self.subTest("kernel thread set aside"):
            kernel = self.kthreadd()
            if not kernel:
                self.skipTest("/proc shows no kernel thread as pid 2 here (as in a container), "
                              "so the exclusion of kernel threads is not exercised")
            try:
                os.readlink("/proc/2/cwd")
            except PermissionError:
                pass
            except OSError as exc:
                self.skipTest("reading /proc/2/cwd fails with %s, not a refusal, so the "
                              "exclusion of kernel threads is not exercised as this case "
                              "intends" % exc.strerror)
            else:
                self.skipTest("reading /proc/2/cwd is not refused here (as for root), so the "
                              "report reads kthreadd and sets no kernel thread aside")
            alone = self.report_all_read(inventory=kernel)
            self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
            self.assertEqual(self.leftover_commands(alone.stdout),
                             self.removable_commands(root, checkouts), alone.stdout)
        _mine, others, _kernel = self.unreadable_processes()
        result, _ran = self.run_guard()
        if self.complete_reports(result.stderr) and others:
            self.assert_inspect(result.stderr, root, self.UNREAD)
            counted = re.search(self.UNREAD[:-1], result.stderr, re.M)
            self.assertGreater(int(counted.group(2)), 0, result.stderr)
            self.assertNotIn("lets only a privileged process in", result.stderr)
        # It makes itself non-dumpable only once live_process has read its
        # environment and command line (on its "go" line), since /proc then
        # lets only a privileged process read them.
        # The report alone runs on the clock CLOCKED_REPORT sets, its wait
        # for the worker lasting until the worker ends
        # (FIXTURE_JOIN_UNTIL_DONE=1), so no real scan bound, join or alarm
        # applies to the outcome it checks.
        # Root, or any process with CAP_SYS_PTRACE, reads a non-dumpable
        # process's /proc entries, so where reading its cwd is not refused
        # this part is skipped, as the kernel thread subtest above is; the
        # rest of the test still runs.
        import select
        helper, _line = self.live_process(self.NON_DUMPABLE)
        helper.stdin.write(b"go\n")
        helper.stdin.flush()
        ready, _writable, _failed = select.select([helper.stdout], [], [], 60)
        self.assertEqual(helper.stdout.readline() if ready else b"", b"non-dumpable\n")
        with self.subTest("non-dumpable process of this user"):
            try:
                os.readlink("/proc/%d/cwd" % helper.pid)
            except PermissionError:
                pass
            else:
                self.skipTest("reading a non-dumpable process's cwd is not refused here (as "
                              "for root or with CAP_SYS_PTRACE), so the report reads it and "
                              "the unreadable-process case is not exercised")
            result, _ran = self.run_guard()
            self.assertEqual(self.leftover_commands(result.stderr), [], result.stderr)
            alone = self.report_alone(prelude=self.NO_OTHER_PROCESS + self.CLOCKED_REPORT,
                                      FIXTURE_PIDS=str(helper.pid), FIXTURE_JOIN_UNTIL_DONE="1")
            self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
            for err in self.complete_reports(result.stderr, alone.stdout):
                self.assert_inspect(err, root, self.UNREAD)
                counted = re.search(self.UNREAD[:-1], err, re.M)
                self.assertGreater(int(counted.group(1)), 0, err)

    # The word kill with no letter on either side: a printed kill command
    # matches, a path through .claude/skills/ does not.
    KILL_WORD = re.compile(r"(?<![A-Za-z])kill(?![A-Za-z])")

    def assert_no_kill_word(self, text):
        """Fail if ``text`` holds the word kill, after a planted kill command fails the same check."""
        with self.assertRaises(AssertionError):
            self.assertNotRegex(text + "\n    kill -TERM 4242\n", self.KILL_WORD)
        self.assertNotRegex(text, self.KILL_WORD, text)

    def test_push_from_inside_a_kept_checkout_lists_itself_and_no_command(self):
        # FLIP TABLE (confirmed by a probe in the earlier repository): a
        # push run from inside a kept checkout says so, labels its own
        # guard and the shell that started it among the processes using it,
        # and prints no command to stop them or remove it.
        self.change(".web/templates-draft/landing.html")
        root, checkouts = self.make_leftover(1)
        shell = subprocess.Popen(["bash", "-c", "bash .claude/skills/corpus-management/tools/pre-push-guard.sh; exit $?"],
                                 cwd=checkouts[0], env=self.env, stdout=subprocess.PIPE,
                                 stderr=subprocess.PIPE, text=True)
        out, err = shell.communicate(timeout=60)
        self.assertEqual(shell.returncode, 0, out + err)
        self.assert_no_kill_word(err)
        self.assertEqual(self.leftover_commands(err), [], err)
        # The real guard's report may be a correctly reported incomplete
        # scan of the host's processes. The report alone, run from the
        # same checkout against an empty inventory, always says the push
        # runs inside it; only the real guard can label itself and the
        # shell that started it.
        alone = self.report_all_read(inventory=(), cwd=checkouts[0])
        self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
        self.assert_no_kill_word(alone.stdout)
        inside = re.escape("this push runs inside it (this clone, %s, is in it)" % checkouts[0])
        for text in self.complete_reports(err, alone.stdout):
            self.assert_inspect(text, root, inside)
        if self.complete_reports(err):
            self.assertRegex(err, r"(?m)^    used by pid %d \(started this push\): " % shell.pid)
            self.assertRegex(err, r"(?m)^    used by pid \d+ \(this guard\): bash "
                                  r".claude/skills/corpus-management/tools/pre-push-guard\.sh ")
            # No stop procedure for this guard or what started this push.
            self.assertIn("    no stop procedure: each process using it is this guard, started "
                          "this push, is a pre-push guard or was started by one\n", err)
        self.assertNotIn("NOT PROVED, so no stop command", err)

    # Writes the run record of a stand-in guard run: argv[1] is its pid,
    # argv[2] the record path, argv[3] a number added to its start time (0
    # for its own), argv[4] the clone the record names; the pid namespace
    # and boot id are those of this kernel, the machine id is not recorded.
    STAND_IN_RECORD = (
        "import os, sys\n"
        "pid, path, skew, clone = sys.argv[1], sys.argv[2], int(sys.argv[3]), sys.argv[4]\n"
        "data = open('/proc/%s/stat' % pid, 'rb').read()\n"
        "start = int(data[data.rindex(b')') + 2:].split()[19]) + skew\n"
        "boot = open('/proc/sys/kernel/random/boot_id').read().strip()\n"
        "fields = [pid, clone, str(start), os.readlink('/proc/self/ns/pid'), boot, '-', '']\n"
        "open(path, 'wb').write('\\0'.join(fields).encode())\n")
    # A process that prints its pid and its parent pid (its handshake), then
    # reads its stdin until it closes (the pipe live_process holds, which
    # the shell that starts it passes on with <&0); any further arguments
    # are only carried in its command line.
    SLEEPER = ("import os, sys; print(os.getpid(), os.getppid(), flush=True); "
               "sys.stdin.buffer.read()")

    def user_line(self, pid, label=None):
        """The pattern of the line naming pid as a process using a leftover,
        with label, or with no label at all."""
        return r"(?m)^    used by pid %d%s: \S" % (pid, re.escape(" (%s)" % label) if label else "")

    def test_process_started_by_a_pre_push_guard_gets_no_stop_procedure(self):
        # FLIP TABLE: a guard is known by its identity, not its command
        # line. A stand-in guard run (a script run as a live_process,
        # standing in for a live run of the guard using another run's
        # leftover) writes a run record with its own pid and start time in
        # the guard-owner record of a shard directory of another clone
        # (read before that directory is set aside as not this clone's),
        # moves into a leftover and starts a child there: it is labelled a
        # pre-push guard, its child is labelled as started by one, and
        # neither gets a stop procedure, even where the run that made the
        # leftover has ended, as on a host where every process is read.
        # With a start time that is not its own in the record, the same
        # stand-in is no guard: neither is labelled, and both get the NOT
        # PROVED stop procedure. The script is named pre-push-guard.sh in
        # both cases, so its name decides nothing.
        roots, pids, helpers = {}, {}, []
        script = Path(self.tmp.name) / "other-guard" / "pre-push-guard.sh"
        script.parent.mkdir()
        # It writes its run record, moves into the leftover, and starts its
        # child in the background and waits for it, so it stays its parent.
        # Its Python processes run isolated (-I), and its child reads the
        # pipe live_process holds (<&0, since bash otherwise gives a
        # background job /dev/null), so it lives until that pipe closes.
        script.write_text('cd "$1" || exit 1\n'
                          '"$2" -I -c "$3" "$$" "$4" "$5" "$6" || exit 1\n'
                          '"$2" -I -c "$7" <&0 &\n'
                          'wait\n', encoding="utf-8")
        other = Path(self.tmp.name) / "other-clone"
        for case, skew in (("live", "0"), ("wrong start time", "1")):
            root, checkouts = self.make_leftover(1)
            elsewhere = Path(tempfile.mkdtemp(prefix="grc-gate36-shards.", dir=self.shard_tmp))
            helper, line = self.live_process(command=[
                "bash", str(script), str(checkouts[0]), sys.executable, self.STAND_IN_RECORD,
                str(elsewhere / "guard-owner"), skew, str(other), self.SLEEPER])
            helpers.append(helper)
            child, stand_in = (int(n) for n in line.split())
            self.assertEqual(stand_in, helper.pid)
            roots[case], pids[case] = root, (stand_in, child)
            self.assertEqual(Path("/proc/%d/cmdline" % stand_in).read_bytes().split(b"\0")[1],
                             os.fsencode(script))
            self.assertEqual(Path("/proc/%d/cmdline" % child).read_bytes().split(b"\0")[1:3],
                             [b"-I", b"-c"])
        alone = self.report_all_read(inventory=[pid for pair in pids.values() for pid in pair])
        self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
        for case, root in roots.items():
            stand_in, child = pids[case]
            with self.subTest(case):
                block = "\n".join(self.leftover_block(alone.stdout, root)) + "\n"
                self.assert_inspect(block, root, re.escape("2 process(es) use it, listed below"))
                if case == "live":
                    self.assertRegex(block, self.user_line(stand_in, "a pre-push guard"))
                    self.assertRegex(block, self.user_line(child, "started by a pre-push guard"))
                    self.assertIn("    no stop procedure: each process using it is this guard, "
                                  "started this push, is a pre-push guard or was started by "
                                  "one\n", block)
                    self.assertNotIn("NOT PROVED, so no stop command", block)
                else:
                    self.assertRegex(block, self.user_line(stand_in))
                    self.assertRegex(block, self.user_line(child))
                    self.assertNotIn("pre-push guard)", block)
                    self.assertIn("NOT PROVED, so no stop command", block)
                    for pid in (stand_in, child):
                        self.assertRegex(block, r"(?m)^           pid %d: start time \d+, "
                                                r"command line " % pid)
        # The other clone's shard directory is set aside: it is not listed.
        self.assertNotIn(str(other), alone.stdout)
        for helper in helpers:
            self.assertIsNone(helper.poll(), "the report stopped a process")

    # The report's own labelling alone (the guard's code, read from the
    # fixture's guard, run in identity mode so that its main does not run):
    # argv[2] is a JSON list of [pid, start time, live runs], and it prints
    # the label of each as JSON.
    LABELS = (
        "import contextlib, io, json, sys\n"
        "code = sys.argv.pop(1)\n"
        "cases = json.loads(sys.argv.pop(1))\n"
        "sys.argv[1:] = ['identity', 'repo', '1', '']\n"
        "g = {'__name__': '__main__'}\n"
        "with contextlib.redirect_stdout(io.StringIO()):\n"
        "    exec(code, g)\n"
        "print(json.dumps([g['guard_label'](pid, start, {tuple(run) for run in live})\n"
        "                  for pid, start, live in cases]))\n")

    # The label of a process whose ancestry the report could not establish
    # (its own start time or a parent unread, or a walk that is not
    # consistent).
    UNSURE_ANCESTRY = ("whether a pre-push guard started it is unknown: its ancestry could "
                       "not be established consistently")

    @staticmethod
    def start_time(pid):
        data = Path("/proc/%s/stat" % pid).read_bytes()
        return data[data.rindex(b")") + 2:].split()[19].decode("ascii")

    def test_guard_label_matches_pid_and_start_time_of_each_parent(self):
        # FLIP TABLE: the labels match the pid and the start time, of the
        # process and of each parent (read as the chain is walked),
        # against the live runs: a pid that matches with another start
        # time (a reused pid) is not a guard, nor are its children; a
        # process whose own start time cannot be read while its pid is a
        # live run, or whose parents cannot be read (here a process that
        # has gone), is uncertain, not labelled.
        # Each Python it starts runs isolated (-I) with this fixture's built
        # environment: the live helper (live_process), the process that has
        # gone (ended_pid) and the labelling run.
        helper = self.live_helper()
        done = self.ended_pid()
        child, me = str(helper.pid), str(os.getpid())
        cs, ms = self.start_time(child), self.start_time(me)
        other = lambda start: str(int(start) + 1)
        cases = [
            (child, cs, [[child, cs]], "a pre-push guard"),
            (child, cs, [[child, other(cs)]], None),
            (child, cs, [[me, ms]], "started by a pre-push guard"),
            (child, cs, [[me, other(ms)]], None),
            (child, "-", [[child, cs]], "whether it is a pre-push guard is unknown: its start "
                                        "time cannot be read"),
            (str(done), "-", [[me, ms]], self.UNSURE_ANCESTRY),
        ]
        import json
        read = subprocess.run([sys.executable, "-I", "-c", self.LABELS, self.report_code(),
                               json.dumps([case[:3] for case in cases])], cwd=self.root,
                              env=self.env, capture_output=True, text=True, timeout=60)
        self.assertEqual(read.returncode, 0, read.stdout + read.stderr)
        self.assertEqual(json.loads(read.stdout), [case[3] for case in cases])
        self.assertIsNone(helper.poll(), "the report stopped a process")

    # The report's own labelling against a scripted /proc (the guard's code,
    # read from the fixture's guard, run in identity mode so that its main
    # does not run): argv[2] is a JSON list of [pid, start time, live runs,
    # table], where table maps each pid to the (start time, parent pid)
    # pairs proc_stat returns for it, one per read and the last repeated
    # (null for no such process); a pid the table does not hold is a
    # KeyError, which fails the run. It prints the label of each as JSON.
    SCRIPTED_LABELS = (
        "import contextlib, io, json, sys\n"
        "code = sys.argv.pop(1)\n"
        "cases = json.loads(sys.argv.pop(1))\n"
        "sys.argv[1:] = ['identity', 'repo', '1', '']\n"
        "g = {'__name__': '__main__'}\n"
        "with contextlib.redirect_stdout(io.StringIO()):\n"
        "    exec(code, g)\n"
        "def scripted(table):\n"
        "    table = {pid: list(answers) for pid, answers in table.items()}\n"
        "    def proc_stat(pid):\n"
        "        answers = table[pid]\n"
        "        answer = answers.pop(0) if len(answers) > 1 else answers[0]\n"
        "        return None if answer is None else tuple(answer)\n"
        "    return proc_stat\n"
        "labels = []\n"
        "for pid, start, live, table in cases:\n"
        "    g['proc_stat'] = scripted(table)\n"
        "    labels.append(g['guard_label'](pid, start, {tuple(run) for run in live}))\n"
        "print(json.dumps(labels))\n")

    def test_guard_label_walk_is_consistent_when_pids_are_reused(self):
        # FLIP TABLE: the walk up the parents is kept consistent, so a pid
        # reused while it runs cannot join an unrelated chain to a live
        # guard. A guard (pid 200, start time 50) is live in each case;
        # process 300 was read by the scan with start time 100. With a
        # scripted proc_stat: a consistent chain to the guard is
        # "started by a pre-push guard" and one that ends at pid 1 is no
        # guard (controls); and each of these is uncertain (UNSURE_PARENTS,
        # which keeps the NOT PROVED procedure), where in the earlier
        # repository each was "started by a pre-push guard": process 300
        # read again with another start time (its pid reused by a child of
        # the guard); a parent younger than its child; its direct parent
        # replaced between reads (300 is read again with parent pid 1, as a
        # child is once its parent exits); and an intermediate parent
        # replaced between reads (250 read again with parent pid 1).
        # The label says what is true in each of these cases, every
        # parent read or not (in the earlier repository it said
        # "its parents cannot all be read" when each had been read).
        guard = [["200", "50"]]
        unsure = self.UNSURE_ANCESTRY
        cases = [
            ("consistent chain", ["300", "100", guard,
                                  {"300": [["100", "250"]], "250": [["80", "200"]],
                                   "200": [["50", "1"]]}], "started by a pre-push guard"),
            ("no guard among its parents", ["300", "100", guard,
                                            {"300": [["100", "250"]], "250": [["80", "1"]]}],
             None),
            ("reread with another start time", ["300", "100", guard,
                                                {"300": [["120", "200"]],
                                                 "200": [["50", "1"]]}], unsure),
            ("parent younger than its child", ["300", "100", guard,
                                               {"300": [["100", "250"]],
                                                "250": [["150", "200"]],
                                                "200": [["50", "1"]]}], unsure),
            ("direct parent replaced between reads", ["300", "100", guard,
                                                      {"300": [["100", "250"], ["100", "1"]],
                                                       "250": [["100", "200"]],
                                                       "200": [["50", "1"]]}], unsure),
            ("intermediate parent replaced between reads", ["300", "100", guard,
                                                            {"300": [["100", "250"]],
                                                             "250": [["90", "260"], ["90", "1"]],
                                                             "260": [["90", "200"]],
                                                             "200": [["50", "1"]]}], unsure),
            ("gone when read again", ["300", "100", guard, {"300": [None]}], unsure),
        ]
        read = subprocess.run([sys.executable, "-I", "-c", self.SCRIPTED_LABELS,
                               self.report_code(), json.dumps([case[1] for case in cases])],
                              cwd=self.root, env=self.env, capture_output=True, text=True,
                              timeout=60)
        self.assertEqual(read.returncode, 0, read.stdout + read.stderr)
        for (name, _case, expected), label in zip(cases, json.loads(read.stdout)):
            with self.subTest(name):
                self.assertEqual(label, expected)

    # The report's own reads of a file swapped for a FIFO between its type
    # check and its open (the guard's code, run in identity mode so that its
    # main does not run): argv[2] is a directory holding a regular file
    # "file" and a git common directory "common" whose packed-refs is a
    # regular file; check_regular is wrapped so that, once the real check
    # passes, the entry it checked is replaced by a FIFO. It prints, as
    # JSON, what read_file and then resolve_ref return or raise.
    SWAPPED = (
        "import contextlib, io, json, os, sys\n"
        "code = sys.argv.pop(1)\n"
        "where = sys.argv.pop(1)\n"
        "sys.argv[1:] = ['identity', 'repo', '1', '']\n"
        "g = {'__name__': '__main__'}\n"
        "with contextlib.redirect_stdout(io.StringIO()):\n"
        "    exec(code, g)\n"
        "real = g['check_regular']\n"
        "def swapping(name, dir_fd=None):\n"
        "    real(name, dir_fd)\n"
        "    os.unlink(name, dir_fd=dir_fd)\n"
        "    os.mkfifo(name, dir_fd=dir_fd)\n"
        "g['check_regular'] = swapping\n"
        "out = []\n"
        "try:\n"
        "    out.append(repr(g['read_file'](os.path.join(where, 'file'))))\n"
        "except OSError as exc:\n"
        "    out.append('%s: %s' % (type(exc).__name__, exc.strerror))\n"
        "scan = g['Scan']()\n"
        "scan.common = os.path.join(where, 'common')\n"
        "out.append(list(g['resolve_ref'](scan, b'refs/heads/main')))\n"
        "print(json.dumps(out))\n")

    def test_fifo_swapped_in_after_the_type_check_is_never_read(self):
        # FLIP TABLE: the type check and the open are two lookups by
        # name, so a FIFO swapped in between them is opened (without
        # blocking); the type of the open descriptor is then checked,
        # so it is never read: read_file raises NotRegular, and
        # resolve_ref says packed-refs cannot be read (in the earlier
        # repository packed refs were read from the FIFO as empty:
        # "no ref file or packed ref names it"). The header and
        # .claude/skills/corpus-management/tools/README.md state this
        # window rather than "never opened".
        where = Path(self.tmp.name) / "swap"
        (where / "common").mkdir(parents=True)
        (where / "file").write_text("x\n", encoding="utf-8")
        (where / "common" / "packed-refs").write_text(
            "%s refs/heads/main\n" % ("a" * 40), encoding="utf-8")
        read = subprocess.run([sys.executable, "-I", "-c", self.SWAPPED, self.report_code(),
                               str(where)], cwd=self.root, env=self.env, capture_output=True,
                              text=True, timeout=60)
        self.assertEqual(read.returncode, 0, read.stdout + read.stderr)
        self.assertEqual(json.loads(read.stdout), [
            "NotRegular: it is not a regular file",
            [None, "packed-refs cannot be read (it is not a regular file)"]])
        self.assertTrue((where / "file").is_fifo())
        self.assertTrue((where / "common" / "packed-refs").is_fifo())
        guard = (SKILL_ROOT / "tools" / "pre-push-guard.sh").read_text(encoding="utf-8")
        readme = " ".join((SKILL_ROOT / "tools" / "README.md").read_text(encoding="utf-8")
                          .replace("`", "").split())
        self.assertIn("the open descriptor is then checked", " ".join(
            line.lstrip("# ") for line in guard.splitlines() if line.startswith("#")))
        self.assertIn("so a FIFO or another entry that is not a regular file is not opened "
                      "unless it is swapped in between that check and the open", readme)
        self.assertIn("a descriptor that is not a regular file is closed unread", readme)

    def test_command_line_naming_the_guard_makes_no_guard(self):
        # FLIP TABLE (reproduced in the earlier repository): a process whose
        # own command line, or whose parent command line, merely names
        # .claude/skills/corpus-management/tools/pre-push-guard.sh is not a
        # pre-push guard. Here a shell (bash -c, a live_process) whose argv
        # names it moves into a leftover and starts a child there whose argv
        # names it too: neither is labelled, and both get the NOT PROVED
        # stop procedure (in the earlier repository the shell was labelled a
        # pre-push guard and the child as one too, and no procedure was
        # given), as on a host where every process is read and as the guard
        # prints it.
        root, checkouts = self.make_leftover(1)
        # The child runs isolated (-I) and reads the pipe live_process holds
        # (<&0), so it lives until that pipe closes.
        shell = ('cd "$1" || exit 1\n'
                 '"$2" -I -c "$3" .claude/skills/corpus-management/tools/pre-push-guard.sh <&0 &\n'
                 'wait\n')
        helper, line = self.live_process(command=[
            "bash", "-c", shell, ".claude/skills/corpus-management/tools/pre-push-guard.sh",
            str(checkouts[0]), sys.executable, self.SLEEPER])
        child, parent = (int(n) for n in line.split())
        self.assertEqual(parent, helper.pid)
        self.assertEqual(Path("/proc/%d/cmdline" % child).read_bytes().split(b"\0")[1:3],
                         [b"-I", b"-c"])
        for pid in (child, parent):
            self.assertIn(b".claude/skills/corpus-management/tools/pre-push-guard.sh", Path("/proc/%d/cmdline" % pid).read_bytes())
        self.change(".web/templates-draft/landing.html")
        result, _ran = self.run_guard()
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
        self.assertEqual(self.leftover_commands(result.stderr), [], result.stderr)
        alone = self.report_all_read(inventory=(parent, child))
        self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
        # The real guard's report or a correctly reported incomplete
        # scan; the report alone.
        for text in self.complete_reports(result.stderr, alone.stdout):
            block = "\n".join(self.leftover_block(text, root)) + "\n"
            for pid in (child, parent):
                self.assertRegex(block, self.user_line(pid))
                self.assertRegex(block, r"(?m)^           pid %d: start time \d+, command "
                                        r"line " % pid)
            self.assertNotIn("pre-push guard)", block)
            self.assertNotIn("no stop procedure", block)
            self.assertIn("    NOT PROVED, so no stop command: the report does not prove that a "
                          "process using it is abandoned.", block)
        self.assertIsNone(helper.poll(), "the report stopped a process")

    def test_symlinked_git_record_is_unreadable_not_skipped(self):
        # FLIP TABLE: an entry of <git common dir>/worktrees that is a
        # symbolic link (git follows it, the report does not) is reported as
        # UNREADABLE, so no leftover has a removal command while it remains,
        # as on a host where every process is read (in the earlier
        # repository opening it with O_DIRECTORY and O_NOFOLLOW failed with
        # ENOTDIR, which was taken as an entry git skips, so it was dropped
        # silently and the leftover REMOVABLE). An entry that is a regular
        # file, which git skips, is skipped.
        import json
        root, _checkouts = self.make_leftover(1)
        records = Path(self.common_dir()) / "worktrees"
        target = Path(self.tmp.name) / "record-elsewhere"
        target.mkdir()
        link = records / "linked-record"
        link.symlink_to(target)
        self.addCleanup(link.unlink)
        stray = records / "stray-file"
        stray.write_text("not a git record\n", encoding="utf-8")
        self.addCleanup(stray.unlink)
        alone = self.report_all_read(inventory=())
        self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
        self.assert_inspect(alone.stdout, root, re.escape(
            "1 git record(s) of this clone cannot be read (listed below), so the checkouts "
            "registered with this clone are not fully known") + "$")
        self.assertIn("  UNREADABLE: %s (it is a symbolic link, which the report does not "
                      "follow), so whether that git record registers a checkout of a leftover is "
                      "unknown; no leftover has a removal command while it cannot be read\n"
                      % link, alone.stdout)
        self.assertNotIn(str(stray), alone.stdout)
        read = subprocess.run([sys.executable, "-I", "-c", self.REGISTRATIONS, self.report_code(),
                               self.common_dir()], cwd=self.root, env=self.env,
                              capture_output=True, text=True, timeout=60)
        self.assertEqual(read.returncode, 0, read.stdout + read.stderr)
        self.assertEqual(json.loads(read.stdout)["unread"],
                         [[str(link), "it is a symbolic link, which the report does not follow"]])

    def test_reftable_placeholder_head_is_named_as_not_read(self):
        # FLIP TABLE (confirmed in the earlier repository by a probe on
        # git 2.53.0): in a clone that keeps its refs in reftable, the HEAD
        # of every git record is the placeholder ref: refs/heads/.invalid.
        # The report says "reftable HEAD not read" (in the earlier
        # repository it said that no ref file or packed ref names
        # refs/heads/.invalid), and the leftover stays INSPECT. Checked
        # on a git record of this files-backend fixture given that HEAD,
        # and, where git can make one, on a real reftable clone through the
        # registration reader.
        import json
        root, checkouts = self.make_leftover(1)
        admin = Path(self.git("-C", str(checkouts[0]), "rev-parse",
                              "--absolute-git-dir").stdout.strip())
        original = (admin / "HEAD").read_bytes()
        (admin / "HEAD").write_bytes(b"ref: refs/heads/.invalid\n")
        self.addCleanup((admin / "HEAD").write_bytes, original)
        why = ("reftable HEAD not read: its HEAD names refs/heads/.invalid, the placeholder a "
               "clone that keeps its refs in reftable writes there, and the report reads no "
               "reftable")
        alone = self.report_all_read(inventory=())
        self.assertEqual(alone.returncode, 0, alone.stdout + alone.stderr)
        self.assert_inspect(alone.stdout, root, re.escape(
            "the git record of checkout %s: %s" % (checkouts[0], why)) + "$")
        self.assertNotIn("no ref file or packed ref names it", alone.stdout)
        clone = Path(self.tmp.name) / "reftable-clone"
        made = subprocess.run(["git", "init", "-q", "--ref-format=reftable", str(clone)],
                              env=self.env, capture_output=True, text=True, timeout=30)
        if made.returncode != 0:
            self.skipTest("this git cannot make a reftable clone: %s" % made.stderr.strip())
        for args in (("-c", "user.email=r@example.com", "-c", "user.name=r", "commit", "-q",
                      "--allow-empty", "-m", "Reftable"),
                     ("worktree", "add", "--detach", str(Path(self.tmp.name) / "reftable-wt"),
                      "HEAD")):
            subprocess.run(["git", *args], cwd=clone, env=self.env, check=True,
                           capture_output=True, timeout=30)
        read = subprocess.run([sys.executable, "-I", "-c", self.REGISTRATIONS, self.report_code(),
                               str(clone / ".git")], cwd=self.root, env=self.env,
                              capture_output=True, text=True, timeout=60)
        self.assertEqual(read.returncode, 0, read.stdout + read.stderr)
        got = json.loads(read.stdout)
        self.assertEqual([r["head_problem"] for r in got["records"]], [why], got)

