    @unittest.skipIf(os.geteuid() == 0, "root ignores directory permission bits")
    def test_failed_checkout_removal_reports_its_directory_left_and_registration_gone(self):
        # FLIP TABLE: shard 2's checkout holds a read-only directory with a
        # file in it, and nothing else breaks it. git worktree remove
        # --force then fails to delete that directory but still deletes the
        # checkout's git record, so its directory is left and its
        # registration is no longer listed. The guard says exactly that,
        # names the shard directory (bash-quoted) to remove once nothing
        # uses it, and prints no git worktree remove command for that
        # checkout (there is no registration to remove).
        import shlex
        self.change("ai/policy-fixture.md")
        result, _ran = self.run_guard(FIXTURE_SHARD_KEEP_CHECKOUT="2")
        output = result.stdout + result.stderr
        broken = [run["cwd"] for run in self.shard_runs() if run["argv"][2] == "2/6"]
        self.assertEqual(len(broken), 1, output)
        kept = os.path.join(broken[0], "kept")
        # Restored before the fixture's own cleanup (cleanups run last first).
        self.addCleanup(lambda: os.path.isdir(kept) and os.chmod(kept, 0o700))
        self.assertEqual(result.returncode, 0, output)
        self.assertIn("git worktree remove --force failed (rc=", result.stderr)
        self.assertIn("for the shard checkout %s: " % broken[0], result.stderr)
        shard_root = os.path.dirname(os.path.dirname(broken[0]))
        self.assertIn("could not remove the shard directory %s.\n" % self.bash_quoted(shard_root),
                      result.stderr)
        self.assertTrue(os.path.isdir(broken[0]), output)
        shown = subprocess.run(["bash", "-c", 'printf %q "$1"', "bash", shard_root],
                               env=self.env, capture_output=True, text=True, timeout=30,
                               check=True).stdout
        self.assertIn("pre-push guard: WARNING: the shard checkout %s was not removed by git "
                      "worktree remove; its directory is left and its registration is no "
                      "longer listed by git worktree list. Remove the shard directory %s once "
                      "nothing uses it.\n" % (broken[0], shown), result.stderr)
        named = re.findall(r"(?m)^pre-push guard: WARNING: the shard checkout .+? its "
                           r"directory is left and its registration is no longer listed by "
                           r"git worktree list\. Remove the shard directory (.+) once nothing "
                           r"uses it\.$", result.stderr)
        self.assertEqual([shlex.split(directory) for directory in named], [[shard_root]],
                         result.stderr)
        self.assertNotIn("still registered", result.stderr)
        self.assertNotIn("could not be read", result.stderr)
        self.assertNotIn("git worktree remove --force --", output)
        for directory in ("gone", "left"):
            self.assertEqual(self.printed_removal_commands(result.stderr, directory), [],
                             result.stderr)
        self.assertNotIn("git worktree prune", output)
        self.assertIn("1 of 6 shard checkouts could not be removed by git worktree remove.\n",
                      result.stdout)
        self.assertNotIn("checkouts were removed", output)
        worktrees = self.git("worktree", "list", "--porcelain").stdout
        self.assertNotIn("worktree %s\n" % broken[0], worktrees)
        self.assertEqual(worktrees.count("worktree "), 1, worktrees)
        # The named shard directory, removed once nothing uses it, takes the
        # checkout's directory with it.
        os.chmod(kept, 0o700)
        shutil.rmtree(shard_root)
        self.assertFalse(os.path.lexists(broken[0]))

    @unittest.skipIf(os.geteuid() == 0, "root ignores directory permission bits")
    def test_failed_shard_directory_removal_reports_one_line(self):
        # FLIP TABLE: shard 2's checkout holds a read-only directory with a
        # file in it, so removing the shard directory fails. The guard
        # reports that as one plain line (the removal's exit status, then the
        # exception type and message, naming the shard directory bash-quoted
        # with printf %q, as bash_quoted gives it) before its WARNING, never
        # as a Python traceback.
        self.change("ai/policy-fixture.md")
        result, _ran = self.run_guard(FIXTURE_SHARD_KEEP_CHECKOUT="2")
        output = result.stdout + result.stderr
        broken = [run["cwd"] for run in self.shard_runs() if run["argv"][2] == "2/6"]
        self.assertEqual(len(broken), 1, output)
        kept = os.path.join(broken[0], "kept")
        # Restored before the fixture's own cleanup (cleanups run last first).
        self.addCleanup(lambda: os.path.isdir(kept) and os.chmod(kept, 0o700))
        self.assertEqual(result.returncode, 0, output)
        self.assertNotIn("Traceback", output)
        shard_root = os.path.dirname(os.path.dirname(broken[0]))
        shown = self.bash_quoted(shard_root)
        lines = re.findall(r"(?m)^pre-push guard: removing the shard directory (.+?) "
                           r"failed \(rc=(\d+)\): (\w+): (.+)\n", result.stderr)
        self.assertEqual(len(lines), 1, result.stderr)
        self.assertEqual(lines[0][0], shown, result.stderr)
        self.assertEqual(lines[0][1:3], ("1", "PermissionError"), result.stderr)
        self.assertIn("pre-push guard: removing the shard directory %s failed (rc=1): "
                      "PermissionError: " % shown, result.stderr)
        warning = "pre-push guard: WARNING: could not remove the shard directory %s.\n" % shown
        self.assertIn(warning, result.stderr)
        self.assertLess(result.stderr.index("removing the shard directory "),
                        result.stderr.index(warning), result.stderr)
        self.assertTrue(os.path.isdir(shard_root), output)

    def test_shard_directory_removal_ending_without_a_message_reports_its_status(self):
        # FLIP TABLE: a python3 first on PATH, under the fixture, kills itself
        # (SIGKILL) when it is the shard-directory removal (its program holds
        # shutil.rmtree) and runs the real python3 otherwise, so the removal
        # ends without a message. The guard reports its exit status (rc=137)
        # and a fallback text, not an empty message. The shard directory sits
        # under a TMPDIR holding a space, a tab, a CR and a newline: that line
        # and the WARNING each stay one line and name it as one printf %q word
        # that bash reads back as the exact path (shlex.split cannot).
        import shlex
        real = shutil.which("python3", path=self.env.get("PATH"))
        self.assertIsNotNone(real)
        shim = Path(self.tmp.name) / "shim"
        shim.mkdir()
        (shim / "python3").write_text(
            '#!/bin/sh\ncase "$*" in\n    *shutil.rmtree*) kill -KILL "$$" ;;\nesac\n'
            'exec %s "$@"\n' % shlex.quote(real), encoding="utf-8")
        (shim / "python3").chmod(0o755)
        odd = Path(self.tmp.name) / "shard tmp\tdir\r\nnext"
        odd.mkdir()
        self.change("ai/policy-fixture.md")
        result, _ran = self.run_guard(TMPDIR=str(odd),
                                      PATH=str(shim) + os.pathsep + self.env.get("PATH", ""))
        output = result.stdout + result.stderr
        self.assertEqual(result.returncode, 0, output)
        self.assertNotIn("Traceback", output)
        self.assertEqual(len(self.shard_runs()), 6, output)
        roots = [name for name in os.listdir(odd) if name.startswith("grc-gate36-shards.")]
        self.assertEqual(len(roots), 1, output)
        shard_root = os.path.join(str(odd), roots[0])
        self.assertTrue(os.path.isdir(shard_root), output)
        shown = self.bash_quoted(shard_root)
        self.assertIn("$'", shown)
        self.assertEqual(self.bash_reads(shown), shard_root)
        stderr_lines = result.stderr.splitlines(keepends=True)
        failed = ("pre-push guard: removing the shard directory %s failed (rc=137): "
                  "the removal process printed no message\n" % shown)
        warning = "pre-push guard: WARNING: could not remove the shard directory %s.\n" % shown
        self.assertIn(failed, stderr_lines, result.stderr)
        self.assertIn(warning, stderr_lines, result.stderr)
        self.assertEqual(result.stderr.count("removing the shard directory "), 1, result.stderr)
        self.assertLess(stderr_lines.index(failed), stderr_lines.index(warning), result.stderr)

    def test_shard_directory_removal_printing_two_lines_reports_one_line(self):
        # FLIP TABLE: a python3 first on PATH, under the fixture, writes two
        # lines to stderr and exits 3 when it is the shard-directory removal
        # (its program holds shutil.rmtree) and runs the real python3
        # otherwise. The guard joins the removal's message onto one line, so
        # its failure line holds both messages and neither is printed as a
        # line of its own. Without the guard's newline collapse the second
        # message starts a line and this fails; a guard that also prints the
        # first message on a line of its own fails the first-message count.
        import shlex
        real = shutil.which("python3", path=self.env.get("PATH"))
        self.assertIsNotNone(real)
        shim = Path(self.tmp.name) / "shim"
        shim.mkdir()
        (shim / "python3").write_text(
            '#!/bin/sh\ncase "$*" in\n    *shutil.rmtree*)\n'
            "        printf '%%s\\n' 'first removal message' 'second removal message' >&2\n"
            '        exit 3 ;;\nesac\nexec %s "$@"\n' % shlex.quote(real), encoding="utf-8")
        (shim / "python3").chmod(0o755)
        self.change("ai/policy-fixture.md")
        result, _ran = self.run_guard(PATH=str(shim) + os.pathsep + self.env.get("PATH", ""))
        output = result.stdout + result.stderr
        self.assertEqual(result.returncode, 0, output)
        self.assertNotIn("Traceback", output)
        self.assertEqual(len(self.shard_runs()), 6, output)
        roots = [name for name in os.listdir(self.shard_tmp)
                 if name.startswith("grc-gate36-shards.")]
        self.assertEqual(len(roots), 1, output)
        shard_root = os.path.join(str(self.shard_tmp), roots[0])
        self.assertTrue(os.path.isdir(shard_root), output)
        shown = self.bash_quoted(shard_root)
        stderr_lines = result.stderr.splitlines(keepends=True)
        failed = ("pre-push guard: removing the shard directory %s failed (rc=3): "
                  "first removal message second removal message\n" % shown)
        warning = "pre-push guard: WARNING: could not remove the shard directory %s.\n" % shown
        self.assertIn(failed, stderr_lines, result.stderr)
        self.assertEqual(result.stderr.count("removing the shard directory "), 1, result.stderr)
        self.assertEqual(result.stderr.count("first removal message"), 1, result.stderr)
        self.assertEqual(result.stderr.count("second removal message"), 1, result.stderr)
        self.assertIn(warning, stderr_lines, result.stderr)
        self.assertLess(stderr_lines.index(failed), stderr_lines.index(warning), result.stderr)

    def test_failed_checkout_removal_with_unreadable_registrations_keeps_its_command(self):
        # FLIP TABLE: git worktree remove fails for shard 2's checkout (its
        # .git file is gone), and FIXTURE_GIT_WORKTREE_LIST_FAIL, a fixture
        # switch, makes a git shim fail git worktree list (rc=3). The guard
        # keeps that exit status: it says the registration state could not
        # be read, never that the registration is no longer listed, and
        # still prints the command for that checkout alone, which, run as
        # printed, removes the registration that is in fact still there.
        path = self.git_shim('if [ -n "${FIXTURE_GIT_WORKTREE_LIST_FAIL}" ] '
                             '&& [ "$1" = worktree ] && [ "$2" = list ]; then exit 3; fi')
        self.change("ai/policy-fixture.md")
        result, _ran = self.run_guard(FIXTURE_SHARD_BREAK_CHECKOUT="2",
                                      FIXTURE_GIT_WORKTREE_LIST_FAIL="1", **path)
        output = result.stdout + result.stderr
        self.assertEqual(result.returncode, 0, output)
        broken = [run["cwd"] for run in self.shard_runs() if run["argv"][2] == "2/6"]
        self.assertEqual(len(broken), 1, output)
        self.assertIn("for the shard checkout %s: " % broken[0], result.stderr)
        self.assertIn("its directory is gone and its registration state could not be read "
                      "(git worktree list failed, rc=3), so it may still be registered.",
                      result.stderr)
        self.assertNotIn("no longer listed", result.stderr)
        self.assertNotIn("and it is still registered", result.stderr)
        self.assertNotIn("git worktree prune", output)
        commands = self.failed_removal_commands(result.stderr,
                                                registration=self.REGISTRATION_UNREAD)
        self.assertEqual(commands, [["git", "worktree", "remove", "--force", "--", broken[0]]],
                         result.stderr)
        self.assertIn("1 of 6 shard checkouts could not be removed by git worktree remove.\n",
                      result.stdout)
        self.assertNotIn("checkouts were removed", output)
        self.assertEqual(os.listdir(self.shard_tmp), [])
        # The real git, without the shim, still lists it; the command removes it.
        worktrees = self.git("worktree", "list", "--porcelain").stdout
        self.assertIn("worktree %s\n" % broken[0], worktrees)
        self.assertEqual(worktrees.count("worktree "), 2, worktrees)
        self.git(*commands[0][1:])
        worktrees = self.git("worktree", "list", "--porcelain").stdout
        self.assertEqual(worktrees.count("worktree "), 1, worktrees)

    def test_failed_removal_command_is_shell_quoted_and_runs_as_printed(self):
        # FLIP TABLE: the shard checkouts sit under a TMPDIR whose name
        # holds a space and a tab, so bash printf %q quotes the printed path
        # in $'...' form. Run as printed through bash, the command gives git
        # that path as one argument and removes exactly that checkout's
        # registration: another worktree of this repository stays
        # registered.
        odd = Path(self.tmp.name) / "shard tmp\tdir"
        odd.mkdir()
        other = Path(self.tmp.name) / "other checkout"
        self.git("worktree", "add", "--detach", str(other), "HEAD")
        other = os.path.realpath(other)
        self.change("ai/policy-fixture.md")
        result, _ran = self.run_guard(FIXTURE_SHARD_BREAK_CHECKOUT="2", TMPDIR=str(odd))
        output = result.stdout + result.stderr
        self.assertEqual(result.returncode, 0, output)
        broken = [run["cwd"] for run in self.shard_runs() if run["argv"][2] == "2/6"]
        self.assertEqual(len(broken), 1, output)
        self.assertIn(" ", broken[0])
        self.assertIn("\t", broken[0])
        self.assertEqual(os.listdir(odd), [])
        commands = self.printed_removal_commands(result.stderr)
        self.assertEqual(len(commands), 1, result.stderr)
        before = self.git("worktree", "list", "--porcelain").stdout
        self.assertIn("worktree %s\n" % broken[0], before)
        self.assertIn("worktree %s\n" % other, before)
        self.assertEqual(before.count("worktree "), 3, before)
        ran = subprocess.run(["bash", "-c", commands[0]], cwd=self.root, env=self.env,
                             capture_output=True, text=True, timeout=30)
        self.assertEqual(ran.returncode, 0, commands[0] + "\n" + ran.stdout + ran.stderr)
        after = self.git("worktree", "list", "--porcelain").stdout
        self.assertNotIn("worktree %s\n" % broken[0], after)
        self.assertIn("worktree %s\n" % other, after)
        self.assertEqual(after.count("worktree "), 2, after)
        # The words bash reads from it, and the $'...' form that carries the tab.
        words = subprocess.run(["bash", "-c", "printf '%s\\0' " + commands[0]], env=self.env,
                               capture_output=True, text=True, timeout=30, check=True).stdout
        self.assertEqual(words.split("\0")[:-1],
                         ["git", "worktree", "remove", "--force", "--", broken[0]])
        self.assertIn("$'", commands[0])

    def test_failing_local_shard_blocks_the_push_with_its_status(self):
        # FLIP TABLE: a failing shard fails the push with that shard's own
        # exit status (7 here), read directly; the later steps do not run,
        # and every checkout and log is kept, its path printed.
        self.change("ai/policy-fixture.md")
        result, ran = self.run_guard(FIXTURE_SHARD_FAIL="3")
        self.assertEqual(result.returncode, 7, result.stdout + result.stderr)
        self.assertIn("gate 36 local shard 3/6: rc=7", result.stdout)
        self.assertIn("stub shard failure in shard 3", result.stdout)
        self.assertIn("pre-push guard FAILED at gate 36 local shards (rc=7): shard(s) 3 "
                      "of 6 failed", result.stdout)
        self.assertNotIn(".claude/skills/corpus-management/tools/run-pr-time-checks.sh", ran)
        self.assertNotIn("Safe to push", result.stdout)
        kept = re.findall(r"^  shard \d: \S+ \(checkout (\S+), log (\S+)\)$",
                          result.stdout, re.M)
        self.assertEqual(len(kept), 6, result.stdout)
        for checkout, log in kept:
            self.assertTrue(Path(checkout, ".claude/skills/corpus-management/tools", "pre-push-guard.sh").is_file(), checkout)
            self.assertTrue(Path(log).is_file(), log)
        # FLIP TABLE: a failed run, not only an interrupted one, reports
        # what it left, with no removal command while it lasts; the next
        # push makes it REMOVABLE. The scan of every process of the host
        # behind each of these reports may reach its bound on a busy host,
        # which a correctly reported incomplete scan with no removal
        # command says. So may the WARNING that the left report's alarm
        # ended it (assert_left_report).
        self.assert_left_report(result.stdout, result.stderr,
                                "    - this run made it and has not ended yet: ")
        root = os.path.dirname(os.path.dirname(kept[0][0]))
        later, _ran = self.run_guard(FIXTURE_SHARD_FAIL="3")
        self.assert_removable(later.stderr, root, [checkout for checkout, _log in kept],
                              r"no process \d+ exists", inventory=())
        for checkout in re.findall(r"^  shard \d: \S+ \(checkout (\S+), log \S+\)$",
                                   later.stdout, re.M) + [c for c, _log in kept]:
            self.git("worktree", "remove", "--force", checkout)

    def test_missing_shard_output_or_reconcile_failure_blocks_the_push(self):
        # FLIP TABLE: every shard exits 0 but one wrote no outputs; the
        # guard's own check names that shard and fails the push with 2
        # before the reconcile runs, keeping the checkouts. A reconcile
        # refusal (malformed outputs) and a reconcile failure (another unit
        # set) each fail the push with the reconcile's status.
        self.change("ai/policy-fixture.md")
        for env, rc, expected in (
                ({"FIXTURE_SHARD_NO_OUTPUT": "5"}, 2,
                 ["pre-push guard FAILED at gate 36 local shards (rc=2): shard(s) 5 of 6 "
                  "exited 0 but wrote no step outputs (GITHUB_OUTPUT file missing or empty), "
                  "so the reconcile was not run"]),
                ({"FIXTURE_SHARD_BAD_OUTPUT": "4"}, 2,
                 ["REFUSED: regression-shard-4 published no well-formed 'units_sha256' output",
                  "pre-push guard FAILED at gate 36 local shards (rc=2): the shard reconcile "
                  "failed (rc=2)"]),
                ({"FIXTURE_SHARD_OTHER_UNITS": "3"}, 1,
                 ["pre-push guard FAILED at gate 36 local shards (rc=1): the shard reconcile "
                  "failed (rc=1)"])):
            with self.subTest(env=env):
                result, ran = self.run_guard(**env)
                self.assertEqual(result.returncode, rc, result.stdout + result.stderr)
                for text in expected:
                    self.assertIn(text, result.stdout)
                if "FIXTURE_SHARD_NO_OUTPUT" in env:
                    self.assertNotIn("gate 36 local shard reconcile", result.stdout)
                else:
                    self.assertIn("gate 36 local shard reconcile", result.stdout)
                self.assertNotIn(".claude/skills/corpus-management/tools/run-pr-time-checks.sh", ran)
                self.assertNotEqual(os.listdir(self.shard_tmp), [])
                kept = re.findall(r"\(checkout (\S+), log", result.stdout)
                self.assertEqual(len(kept), 6, result.stdout)
                for checkout in kept:
                    self.git("worktree", "remove", "--force", checkout)
                for entry in self.shard_tmp.iterdir():
                    shutil.rmtree(entry)
                (self.root / "ran.log").unlink(missing_ok=True)

    def test_header_exit_codes_match_the_shard_step(self):
        # FLIP TABLE: the header states the shard step's real exit codes:
        # the first failing shard's own status in shard order (here shard 4
        # exits 5 and every other failing shard 7, so failing shards 4 and
        # 6 exit 5, and 2 and 4 exit 7), else 2 for set-up or a shard
        # without outputs, else the reconcile's own status (1 failure, 2
        # refusal), and 130/143/129 on INT/TERM/HUP. The behaviour behind
        # each code is pinned by the tests above and this one; the retired
        # wording (a shard failure exits 1, a missing shard) is gone.
        guard = (SKILL_ROOT / "tools" / "pre-push-guard.sh").read_text(encoding="utf-8")
        header = " ".join(line.lstrip("#").strip() for line in guard.split("\nset -u\n", 1)[0]
                          .splitlines())
        for text in ("At the local gate 36 shards (step 1b): the first failing shard's own exit "
                     "status, in shard order, when any shard fails; otherwise 2 when the shard "
                     "run cannot be set up or a shard exited 0 without writing its step outputs; "
                     "otherwise the reconcile's own status when it fails (1 for a failure, 2 for "
                     "a refusal); 130, 143 or 129 when SIGINT, SIGTERM or SIGHUP interrupts the "
                     "step.",):
            self.assertIn(text, header)
        for retired in ("1 when a local gate 36 shard fails", "a shard is missing",
                        "a missing shard"):
            self.assertNotIn(retired, header)
        self.assertNotIn("so a shard is missing", guard)
        stub = self.root / self.REGRESSION_SCRIPT
        stub.write_text(stub.read_text(encoding="utf-8").replace(
            "    sys.exit(7)\n", "    sys.exit(5 if index == '4' else 7)\n"), encoding="utf-8")
        self.change("ai/policy-fixture.md")
        for failing, rc in (("4,6", 5), ("2,4", 7)):
            with self.subTest(failing=failing):
                result, _ran = self.run_guard(FIXTURE_SHARD_FAIL=failing)
                self.assertEqual(result.returncode, rc, result.stdout + result.stderr)
                for checkout in re.findall(r"\(checkout (\S+), log", result.stdout):
                    self.git("worktree", "remove", "--force", checkout)

    def test_local_shard_count_is_six_and_the_workflow_has_no_shard_job(self):
        # The guard's REGRESSION_SHARD_COUNT is 6, and the quality workflow
        # runs no regression-shard job, so gate 36 is split only locally.
        guard = (SKILL_ROOT / "tools" / "pre-push-guard.sh").read_text(encoding="utf-8")
        quality = (REPO_ROOT / ".github" / "workflows" / "quality.yml").read_text(
            encoding="utf-8")
