class AuditGateParityTests(LinterTestCase):
    """.claude/skills/corpus-management/tools/lint-audit-gate-parity.py

    Covers the positive baseline (the real repository state passes) and
    synthetic-``--root`` negatives for each drift class the gate detects:
    a mismatched gate NAME; an invocation (argv) drift between the execution
    surfaces (a missing flag, a wrong flag value, a pre-commit-only
    divergence now that argv-parity is 3-way, and a quoted-whitespace value,
    which the gate-line allowlist refuses); section-5 grouped-list drift (a
    missing, duplicated, unknown, or malformed number, or a comment or fence
    left open, with comment, fence,
    and prose numbers ignored; these copy the real surfaces, so they assert
    exit 0 where clean); plus unit coverage of the extractor's
    branch routing and the documented out-of-contract metacharacter residue. Each
    minimal synthetic root deliberately
    trips the unrelated exclusion/delta guards, so the negatives key on the
    distinctive finding substring, not on the exit code alone.
    """

    def test_extract_argv_quote_and_operator_aware(self) -> None:
        # Unit proof that the argv extractor routes correctly AND each branch is
        # right, so the integration fixtures' flagged results rest on a correct
        # parse. shlex word-split alone cannot tell an unquoted && operator (or a
        # $-expansion / glob) from a quoted literal, so a char outside the safe
        # allowlist routes to the raw-sentinel comparand instead of shlex.
        import importlib.util
        tool = Path(__file__).resolve().parent.parent / "tools" / "lint-audit-gate-parity.py"
        spec = importlib.util.spec_from_file_location("_agp_unit", str(tool))
        agp = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(agp)
        e = agp._extract_argv
        S = ".claude/skills/corpus-management/tools/x.py"

        def is_raw(r):
            return len(r) == 1 and r[0].startswith("\x00raw:")

        # SHLEX branch (all chars in the allowlist): simple flag, empty, and a
        # quoted-whitespace value tokenized correctly (NOT the raw branch).
        self.assertEqual(e(f"python3 {S} --check", S), ("--check",))
        self.assertFalse(is_raw(e(f"python3 {S} --check", S)))
        self.assertEqual(e(f"python3 {S}", S), ())
        self.assertEqual(e(f"python3 {S} --s 'a b'", S), ("--s", "a b"))
        self.assertFalse(is_raw(e(f"python3 {S} --s 'a b'", S)))
        # shlex preserves intra-quote whitespace (a naive split would collapse
        # these equal -- the distinction the shlex branch exists to make):
        self.assertNotEqual(
            e(f"python3 {S} --s 'a  b'", S), e(f"python3 {S} --s 'a b'", S)
        )
        # RAW branch: an allowlist-violating char (operator, $-expansion, glob)
        # routes to the raw-sentinel comparand.
        self.assertTrue(is_raw(e(f"python3 {S} --x && y", S)))
        self.assertTrue(is_raw(e(f"python3 {S} --arg $FOO", S)))
        self.assertTrue(is_raw(e(f"python3 {S} --g *.py", S)))
        # and the raw comparand distinguishes what shlex would collapse: an
        # unquoted operator vs a quoted literal, and $-expansion vs a quoted string.
        self.assertNotEqual(
            e(f"python3 {S} --x && y", S), e(f"python3 {S} --x '&&' y", S)
        )
        self.assertNotEqual(
            e(f"python3 {S} --arg $FOO", S), e(f'python3 {S} --arg "$FOO"', S)
        )
        # malformed (unbalanced quote) never crashes and routes to raw.
        self.assertTrue(is_raw(e(f'python3 {S} --sep "a', S)))

    def test_extract_argv_metachar_residue_documented(self) -> None:
        # Locks the accepted out-of-contract residue: a metacharacter-bearing
        # invocation gets a best-effort RAW comparison, NOT shell-semantic modelling.
        # No live gate uses a metacharacter, so this is inert; the tests below
        # document the boundary so it cannot regress silently.
        import importlib.util
        tool = Path(__file__).resolve().parent.parent / "tools" / "lint-audit-gate-parity.py"
        spec = importlib.util.spec_from_file_location("_agp_res", str(tool))
        agp = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(agp)
        e = agp._extract_argv
        S = ".claude/skills/corpus-management/tools/x.py"
        # Residue A (SAFE, fail-toward-flagging): equivalent quote spellings of a
        # metachar arg compare UNEQUAL -> surfaced for review, never a silent pass.
        self.assertNotEqual(
            e(f"python3 {S} --x 'a&b'", S), e(f'python3 {S} --x "a&b"', S)
        )
        # Residue B: identical metachar TEXT across surfaces yields identical
        # comparands (no drift flagged). Such an operator would break the gate
        # loudly under argparse in the direct-exec pre-commit surface anyway.
        self.assertEqual(
            e(f"python3 {S} --x && y", S), e(f"python3 {S} --x && y", S)
        )

    def test_script_re_accepts_an_optional_isolated_flag_only(self) -> None:
        # The runners may switch a gate to `python3 -I .claude/skills/corpus-management/tools/X.py` (isolated mode);
        # -I is the only interpreter option the parser accepts before the script,
        # and the flags after the script compare the same with or without it.
        import importlib.util
        tool = Path(__file__).resolve().parent.parent / "tools" / "lint-audit-gate-parity.py"
        spec = importlib.util.spec_from_file_location("_agp_isolated", str(tool))
        agp = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(agp)
        S = ".claude/skills/corpus-management/tools/x.py"
        for command in (f"python3 {S} --check", f"python3 -I {S} --check",
                        f"python3  -I\t{S} --check", f"run: python3 -I {S}"):
            with self.subTest(command=command):
                m = agp.SCRIPT_RE.search(command)
                self.assertIsNotNone(m)
                self.assertEqual(m.group(1), S)
        self.assertEqual(agp._extract_argv(f"python3 -I {S} --check", S),
                         agp._extract_argv(f"python3 {S} --check", S))
        for command in (f"python3 -B {S}", f"python3 -IB {S}", f"python3 -I -B {S}",
                        f"python3 -B -I {S}", f"python3 -Itools/x.py", f"python3 -i {S}",
                        f"python3 -E {S}", f"python3 -X dev {S}", f"python3 -I -I {S}"):
            with self.subTest(command=command):
                self.assertIsNone(agp.SCRIPT_RE.search(command))

    _ISOLATED_SURFACES = (
        ".claude/skills/corpus-management/specs/specification-audit-programme.md",
        ".github/workflows/quality.yml",
        ".claude/skills/corpus-management/tools/run_all_audits.sh",
        ".pre-commit-config.yaml",
        ".claude/skills/corpus-management/tools/run-pr-time-checks.sh",
    )

    def _live_gate_count(self) -> int:
        """The number of live gates in the spec's section-6 inventory (tombstone rows
        left out), the least number of gate lines each runtime surface holds."""
        agp = self._gate_parity_module("_agp_live_count")
        return len(agp.parse_spec_inventory(_resolve_path(agp.SPEC_PATH)))

    def _surface_gate_floor(self, name: str) -> int:
        """The least number of gate lines the real runtime surface ``name`` holds: every
        live gate on the runner and pre-commit, the CI subset on the workflow."""
        if name == ".github/workflows/quality.yml":
            agp = self._gate_parity_module("_agp_subset_floor")
            return len(agp.parse_ci_subset(_resolve_path(agp.SPEC_PATH))[1])
        return self._live_gate_count()

    def _run_isolated_fixture(self, flag: str, *surfaces: str) -> subprocess.CompletedProcess:
        """Copy the real surfaces and put ``flag`` after ``python3`` on every gate
        invocation of the named runtime surfaces (runner, workflow, pre-commit);
        with no surface named, the copy is unchanged."""
        prefixes = {".claude/skills/corpus-management/tools/run_all_audits.sh": "run_gate ",
                    ".github/workflows/quality.yml": "run: python3 .claude/skills/corpus-management/tools/",
                    ".pre-commit-config.yaml": "entry: python3 .claude/skills/corpus-management/tools/"}
        synthetic_root = Path(tempfile.mkdtemp(prefix="synthetic-parity-isolated-", dir=FIXTURE_DIR))
        try:
            for name in self._ISOLATED_SURFACES:
                lines = (_resolve_path(name)).read_text(encoding="utf-8").splitlines(keepends=True)
                if name in surfaces:
                    changed = 0
                    for i, line in enumerate(lines):
                        if line.lstrip().startswith(prefixes[name]) and " python3 .claude/skills/corpus-management/tools/" in line:
                            lines[i] = line.replace(" python3 .claude/skills/corpus-management/tools/", f" python3 {flag} .claude/skills/corpus-management/tools/", 1)
                            changed += 1
                    self.assertGreaterEqual(changed, self._surface_gate_floor(name),
                                            f"fixture anchor in {name}")
                target = synthetic_root / name
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_text("".join(lines), encoding="utf-8")
            return subprocess.run(
                [sys.executable, str(REPO_ROOT / ".claude/skills/corpus-management/tools/lint-audit-gate-parity.py"),
                 "--root", str(synthetic_root)],
                cwd=str(REPO_ROOT), capture_output=True, text=True, timeout=300)
        finally:
            shutil.rmtree(synthetic_root, ignore_errors=True)

    def test_isolated_invocations_keep_parity(self) -> None:
        # Every gate on every runtime surface switched to `python3 -I`, and the
        # runner alone switched: each still parses, and the gate reports exactly
        # what it reports for the unswitched copy (the -I flag is not compared).
        unswitched = self._run_isolated_fixture("-I")
        self.assertNotEqual(unswitched.returncode, 2, unswitched.stderr)
        surfaces = (".claude/skills/corpus-management/tools/run_all_audits.sh", ".github/workflows/quality.yml",
                    ".pre-commit-config.yaml")
        for switched in (surfaces, surfaces[:1]):
            with self.subTest(switched=switched):
                result = self._run_isolated_fixture("-I", *switched)
                self.assertEqual((result.returncode, result.stdout, result.stderr),
                                 (unswitched.returncode, unswitched.stdout, unswitched.stderr))

    def test_other_interpreter_flags_are_parse_errors(self) -> None:
        # Only -I is accepted: any other interpreter option before the script leaves
        # the invocation unparsed, which the gate refuses with exit 2.
        for flag, surface in (("-B", ".claude/skills/corpus-management/tools/run_all_audits.sh"),
                              ("-I -B", ".github/workflows/quality.yml"),
                              ("-IB", ".pre-commit-config.yaml")):
            with self.subTest(flag=flag, surface=surface):
                result = self._run_isolated_fixture(flag, surface)
                self.assertEqual(result.returncode, 2, result.stdout + result.stderr)
                self.assertIn("python3 [-I] .claude/skills/corpus-management/tools/X.py ...", result.stderr)

    def test_every_interpreter_invocation_on_a_line_is_checked(self) -> None:
        # In the earlier repository, SCRIPT_RE.search read `python3 -B .claude/skills/corpus-management/tools/x.py && python3 .claude/skills/corpus-management/tools/x.py` at its
        # second call. A gate line is now one GATE_COMMAND and nothing else, so a second
        # call is refused on every surface, whatever its options.
        for surface in (".claude/skills/corpus-management/tools/run_all_audits.sh", ".github/workflows/quality.yml",
                        ".pre-commit-config.yaml"):
            with self.subTest(surface=surface):
                result = self._run_isolated_fixture("-B .claude/skills/corpus-management/tools/x.py && python3", surface)
                self.assertEqual(result.returncode, 2, result.stdout + result.stderr)
                self.assertIn("is not an accepted gate line", result.stderr)

    def _run_mutated_surfaces(self, mutate) -> subprocess.CompletedProcess:
        """Copy the real surfaces gate 35 reads, apply ``mutate(name, text) -> text`` to
        each, and run the gate with --root on the copy."""
        synthetic_root = Path(tempfile.mkdtemp(prefix="synthetic-parity-mutated-", dir=FIXTURE_DIR))
        try:
            for name in self._ISOLATED_SURFACES:
                text = _resolve_path(name).read_text(encoding="utf-8")
                target = synthetic_root / name
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_text(mutate(name, text), encoding="utf-8")
            return subprocess.run(
                [sys.executable, str(REPO_ROOT / ".claude/skills/corpus-management/tools/lint-audit-gate-parity.py"),
                 "--root", str(synthetic_root)],
                cwd=str(REPO_ROOT), capture_output=True, text=True, timeout=300)
        finally:
            shutil.rmtree(synthetic_root, ignore_errors=True)

    def test_argv_drift_on_runner_and_precommit_together_is_caught(self) -> None:
        # With --check removed from build-taxonomy.py on both the runner and pre-commit,
        # the surfaces still agree with each other, so only the canonical GATE_ARGV
        # comparison can see it.
        anchor = "tools/build-taxonomy.py --check"
        both = (".claude/skills/corpus-management/tools/run_all_audits.sh", ".pre-commit-config.yaml")

        def drop_check(name, text):
            if name not in both:
                return text
            self.assertEqual(text.count(anchor), 1, f"fixture anchor in {name}")
            return text.replace(anchor, "tools/build-taxonomy.py")

        finding = "Gate 33 invocation (argv) drift from the canonical argv"
        drifted = self._run_mutated_surfaces(drop_check)
        self.assertEqual(drifted.returncode, 1, drifted.stdout + drifted.stderr)
        self.assertIn(finding, drifted.stdout)
        self.assertEqual(drifted.stdout.count("from the canonical argv"), 2, drifted.stdout)
        # Flip: the unchanged copy passes, with no canonical-argv finding.
        clean = self._run_mutated_surfaces(lambda name, text: text)
        self.assertEqual(clean.returncode, 0, clean.stdout + clean.stderr)
        self.assertNotIn("canonical argv", clean.stdout)

    def test_canonical_argv_table_entries_track_the_live_gates(self) -> None:
        # A live gate with no GATE_ARGV entry, and an entry for a number that is not live,
        # are findings; the real table matches the real inventory exactly (the flip).
        agp = self._gate_parity_module("_agp_canonical_table")
        spec = agp.parse_spec_inventory(_resolve_path(agp.SPEC_PATH))
        self.assertEqual(set(agp.GATE_ARGV), {row[1] for row in spec})
        self.assertEqual(agp.verify_canonical_argv(spec, [], agp.GATE_ARGV), [])
        table = dict(agp.GATE_ARGV)
        del table[33]
        table[9999] = ()
        found = agp.verify_canonical_argv(spec, [], table)
        self.assertEqual(len(found), 2, found)
        self.assertTrue(any(f.startswith("Gate 33 canonical argv: no GATE_ARGV entry") for f in found))
        self.assertTrue(any(f.startswith("Gate 9999 canonical argv") for f in found))

    def test_ci_subset_block_inside_an_outer_fence_is_refused(self) -> None:
        # The ```text block nested inside an outer 4-backtick fence renders as an
        # example, so its opener is fence text and the subset is unreadable (exit 2).
        spec_name = ".claude/skills/corpus-management/specs/specification-audit-programme.md"

        def wrap(outer_before):
            def mutate(name, text):
                if name != spec_name:
                    return text
                lines = text.split("\n")
                index = next(i for i, line in enumerate(lines) if line.startswith("ci-pr-subset:"))
                self.assertEqual((lines[index - 1], lines[index + 1]), ("```text", "```"))
                if outer_before:
                    lines[index - 1:index - 1] = ["````markdown", "an example", "````"]
                else:
                    lines[index + 2:index + 2] = ["````"]
                    lines[index - 1:index - 1] = ["````markdown"]
                return "\n".join(lines)
            return mutate

        nested = self._run_mutated_surfaces(wrap(False))
        self.assertEqual(nested.returncode, 2, nested.stdout + nested.stderr)
        self.assertIn("not alone inside a fenced block opened at top level", nested.stderr)
        # Flip: an outer fence that closes before the ```text line leaves it at top level.
        closed = self._run_mutated_surfaces(wrap(True))
        self.assertEqual(closed.returncode, 0, closed.stdout + closed.stderr)

    def _gate_parity_module(self, name: str):
        import importlib.util
        tool = Path(__file__).resolve().parent.parent / "tools" / "lint-audit-gate-parity.py"
        spec = importlib.util.spec_from_file_location(name, str(tool))
        agp = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(agp)
        return agp

    # (command, accepted) on every surface: the allowlisted shapes, and the bypass shapes it
    # refuses. The allowlist test and the every-reader parse test below share the table.
    GATE_LINE_SHAPES = (
        ("python3 .claude/skills/corpus-management/tools/x.py", True),
        ("python3 -I .claude/skills/corpus-management/tools/x.py", True),
        ("python3 .claude/skills/corpus-management/tools/x.py --check", True),
        ("python3 -I .claude/skills/corpus-management/tools/x.py --check --release-delta", True),
        ("python3 .claude/skills/corpus-management/tools/x_y-2.py --root=a/b.c,d+e -v", True),
        ("python3 .claude/skills/corpus-management/tools/x.py -B", True),
        ("python3 -B .claude/skills/corpus-management/tools/x.py && python3 .claude/skills/corpus-management/tools/x.py", False),
        ('python3 "-B" .claude/skills/corpus-management/tools/x.py', False),
        ('"python3" -B .claude/skills/corpus-management/tools/x.py', False),
        ("/usr/bin/python3 .claude/skills/corpus-management/tools/x.py", False),
        ("python3   -I  .claude/skills/corpus-management/tools/x.py", False),
        ("python3 .claude/skills/corpus-management/tools/x.py && /usr/bin/pyt?on3 -B .claude/skills/corpus-management/tools/x.py", False),
        ("python3 .claude/skills/corpus-management/tools/x.py --message 'run python3 -B now'", False),
        ("python3 .claude/skills/corpus-management/tools/x.py --sep 'a b'", False),
        ("python3 .claude/skills/corpus-management/tools/x.py # note", False),
        ("python3 .claude/skills/corpus-management/tools/x.py\r", False),
        ("python3 .claude/skills/corpus-management/tools/sub/x.py", False),
        ("python3 .claude/skills/corpus-management/tools/X.py", False),
        ("python3 tools/../../x.py", False),
    )

    def test_gate_commands_match_a_closed_allowlist(self) -> None:
        agp = self._gate_parity_module("_agp_allowlist")
        for command, accepted in self.GATE_LINE_SHAPES:
            with self.subTest(command=command):
                self.assertEqual(agp._gate_command(command) is not None, accepted)

    # Each YAML surface must have its file's fixed skeleton; a fixture's steps or hooks
    # follow these heads at the real files' columns.
    # The one pull-request job: pull_request only, jobs exactly {lint} named "Lint markdown
    # corpus", its first steps the three pinned setup steps.
    _WORKFLOW_JOB_HEAD = ("name: Quality\non:\n  pull_request:\npermissions:\n"
                          "  contents: read\njobs:\n  lint:\n    name: Lint markdown corpus\n"
                          "    runs-on: ubuntu-latest\n    steps:\n")
    _WF_CHECKOUT_STEP = ("      - name: Checkout\n        uses: actions/checkout@"
                         "0123456789abcdef0123456789abcdef01234567 # v1\n        with:\n"
                         "          fetch-depth: 0\n")
    _WF_SETUP_PYTHON_STEP = ("      - name: Set up Python\n        uses: actions/setup-python@"
                             "0123456789abcdef0123456789abcdef01234567 # v1\n        with:\n"
                             '          python-version: "3.14"\n')
    _WF_INSTALL_STEP = ("      - name: Install pinned dependencies\n"
                        "        run: python3 -m pip install -r requirements.txt\n")
    _WORKFLOW_HEAD = (_WORKFLOW_JOB_HEAD + _WF_CHECKOUT_STEP + _WF_SETUP_PYTHON_STEP
                      + _WF_INSTALL_STEP)
    # A synthetic specification's section 4 CI subset block naming gate 1 alone.
    _SPEC_SUBSET = "## 4. Enforcement surfaces\n\n```text\nci-pr-subset: 1\n```\n\n"
    _PRECOMMIT_HEAD = "repos:\n  - repo: local\n    hooks:\n"

    def _gate_fixtures(self, root: Path, command: str) -> dict[str, Path]:
        """``command`` as the one gate line of a runner, a workflow step and a pre-commit
        hook under ``root``."""
        (root / "tools").mkdir(exist_ok=True)
        paths = {"runner": root / "tools" / "run_all_audits.sh",
                 "workflow": root / "quality.yml", "precommit": root / "pre-commit.yaml"}
        paths["runner"].write_text(f'run_gate() {{\n}}\nrun_gate "Shape" {command}\n',
                                   encoding="utf-8")
        paths["workflow"].write_text(self._WORKFLOW_HEAD + f"      - name: Shape\n"
                                     f"        run: {command}\n", encoding="utf-8")
        paths["precommit"].write_text(
            self._PRECOMMIT_HEAD + f"      - id: shape\n        name: Shape\n"
            f"        entry: {command}\n        language: system\n"
            f"        pass_filenames: false\n        always_run: true\n", encoding="utf-8")
        return paths

    def _assert_refused_on_every_reader(self, *commands: str) -> None:
        """Each command, as the gate line of each surface, is a ParseError in gate 35's
        parser for that surface. A YAML value that begins with a quote is refused before
        the gate line is read."""
        agp = self._gate_parity_module("_agp_refused")
        for command in commands:
            root = Path(tempfile.mkdtemp(prefix="synthetic-parity-refused-", dir=FIXTURE_DIR))
            try:
                paths = self._gate_fixtures(root, command)
                for parse, path, message in (
                        (agp.parse_runner, paths["runner"], "is not an accepted gate line"),
                        (agp.parse_workflow, paths["workflow"],
                         "is not an accepted gate line|value that begins with a quote"),
                        (agp.parse_precommit, paths["precommit"],
                         "is not an accepted gate line|value that begins with a quote")):
                    with self.subTest(command=command, parser=parse.__name__):
                        with self.assertRaisesRegex(agp.ParseError, message):
                            parse(path)
            finally:
                shutil.rmtree(root, ignore_errors=True)

    def test_allowlisted_gate_lines_parse_on_every_reader(self) -> None:
        agp = self._gate_parity_module("_agp_accepted")
        for command, accepted in self.GATE_LINE_SHAPES:
            if not accepted:
                continue
            root = Path(tempfile.mkdtemp(prefix="synthetic-parity-accepted-", dir=FIXTURE_DIR))
            try:
                paths = self._gate_fixtures(root, command + " \t")
                m = agp._gate_command(command)
                expected = [("Shape", m.group("script"), tuple(m.group("args").split()))]
                for parse, path in ((agp.parse_runner, paths["runner"]),
                                    (agp.parse_workflow, paths["workflow"]),
                                    (agp.parse_precommit, paths["precommit"])):
                    with self.subTest(command=command, parser=parse.__name__):
                        self.assertEqual([e[1:] for e in parse(path)], expected)
            finally:
                shutil.rmtree(root, ignore_errors=True)

