    def test_yaml_continuation_is_refused(self) -> None:
        # In the earlier repository, before the allowlist, the parser read one physical line;
        # a plain scalar continued on a deeper line was run whole by YAML but read only up to
        # its first line. A continuation line is now refused as a line shape, or, shaped as a
        # key, as a deeper line no key opens.
        agp = self._gate_parity_module("_agp_continued")
        root = Path(tempfile.mkdtemp(prefix="synthetic-parity-continued-", dir=FIXTURE_DIR))
        try:
            workflow, precommit = root / "quality.yml", root / "pre-commit.yaml"
            for continued, message in (("&& python3 -B .claude/skills/corpus-management/tools/x.py", "nor a plain list item"),
                                       ("-B", "nor a plain list item"),
                                       ("x: python3 -B .claude/skills/corpus-management/tools/x.py",
                                        "no key above it opens a nested value")):
                workflow.write_text(self._WORKFLOW_HEAD + "      - name: Continued\n"
                                    "        run: python3 .claude/skills/corpus-management/tools/x.py\n"
                                    f"          {continued}\n", encoding="utf-8")
                precommit.write_text(self._PRECOMMIT_HEAD + "      - id: continued\n"
                                     "        name: Continued\n"
                                     f"        entry: python3 .claude/skills/corpus-management/tools/x.py\n          {continued}\n"
                                     "        language: system\n", encoding="utf-8")
                for parse, path in ((agp.parse_workflow, workflow),
                                    (agp.parse_precommit, precommit)):
                    with self.subTest(continued=continued, parser=parse.__name__):
                        with self.assertRaisesRegex(agp.ParseError, message):
                            parse(path)
        finally:
            shutil.rmtree(root, ignore_errors=True)

