    def test_precommit_gate_hook_with_args_or_another_language_is_refused(self) -> None:
        agp = self._gate_parity_module("_agp_hook_keys")
        root = Path(tempfile.mkdtemp(prefix="synthetic-parity-hook-keys-", dir=FIXTURE_DIR))
