    def test_synthetic_name_drift_flagged(self) -> None:
        # Build a tiny four-surface fixture where everything aligns
        # except one gate name in the pre-commit hook (mismatch vs spec).
        synthetic_root = Path(tempfile.mkdtemp(prefix="synthetic-parity-drift-", dir=FIXTURE_DIR))  # unique per-run: no cross-run delete-race
        import shutil
        (synthetic_root / ".claude/skills/corpus-management/specs").mkdir(parents=True)
        (synthetic_root / ".github" / "workflows").mkdir(parents=True)
        (synthetic_root / ".claude/skills/corpus-management/tools").mkdir(parents=True)
        try:
            # Spec inventory (canonical): one row.
            (synthetic_root / ".claude/skills/corpus-management/specs"
             / "specification-audit-programme.md").write_text(
                "# Audit Programme\n\n" + self._SPEC_SUBSET +
                "## 6. Gate inventory\n\n"
                "| # | Gate | Script |\n"
                "| --- | --- | --- |\n"
                "| 1 | Metadata audit | [`.claude/skills/corpus-management/tools/lint-metadata.py`](../tools/lint-metadata.py) |\n\n"
                "## 7. Next section\n",
                encoding="utf-8",
            )
            # Workflow: matches spec.
            (synthetic_root / ".github" / "workflows" / "quality.yml").write_text(
                self._WORKFLOW_HEAD +
                "      - name: Metadata audit\n"
                "        run: python3 .claude/skills/corpus-management/tools/lint-metadata.py\n",
                encoding="utf-8",
            )
            # Runner: matches spec.
            (synthetic_root / ".claude/skills/corpus-management/tools" / "run_all_audits.sh").write_text(
                '#!/usr/bin/env bash\n'
                'run_gate "Metadata audit" python3 .claude/skills/corpus-management/tools/lint-metadata.py\n',
                encoding="utf-8",
            )
            # Pre-commit: WRONG NAME (introduces drift).
            (synthetic_root / ".pre-commit-config.yaml").write_text(
                "repos:\n"
                "  - repo: local\n"
                "    hooks:\n"
                "      - id: lint-metadata\n"
                "        name: Wrong Name For Metadata Audit\n"
                "        entry: python3 .claude/skills/corpus-management/tools/lint-metadata.py\n"
                "        language: system\n"
                "        pass_filenames: false\n"
                "        always_run: true\n",
                encoding="utf-8",
            )
            result = run_linter(
                ".claude/skills/corpus-management/tools/lint-audit-gate-parity.py",
                "--root",
                str(synthetic_root),
            )
            self.assertLinterFails(result, "name drift")
        finally:
            shutil.rmtree(synthetic_root, ignore_errors=True)

