def _pinned_rule_collections() -> tuple[str, ...]:
    """Repository paths of the pinned AIQT rule collections, from aiqt_rules.

    The rule pack ships as the vendored, byte-pinned collections under
    ``.claude/aiqt/rules/`` and their rendered copies under ``.claude/rules/``.
    Derived from the validator's own constants so a layout change there moves
    these tests too.
    """
    import aiqt_rules

    vendored = tuple(f"{aiqt_rules.VENDOR_REL}/{aiqt_rules.VENDORED_RULES_DIR}/{sub}"
                     for sub in aiqt_rules.RENDER_SUBDIRS)
    rendered = tuple(f"{aiqt_rules.UPSTREAM_RULES_PREFIX}{sub}"
                     for sub in aiqt_rules.RENDER_SUBDIRS)
    return vendored + rendered


class SkillSpecsGateScopeTests(unittest.TestCase):
    """Scope fixes that follow gate 6's widening to the skill's specs/."""

    SPEC = ".claude/skills/corpus-management/specs/specification-audit-programme.md"
    INGESTION = ".claude/skills/corpus-management/specs/instruction-ai-document-ingestion.md"
    TARGET = "governance/specification-master-project.md"

    def test_provision_default_index_reads_skill_specs_docs_and_registers(self) -> None:
        # Builds the default index over a fixture repository with 1 citing
        # document under each literal skill path, so a scan root dropped from
        # DEFAULT_SCAN_ROOTS (or from the constants it is built from) fails here.
        import tempfile
        from unittest import mock
        import provision_citations as mod
        planted = (
            ".claude/skills/corpus-management/specs/planted-spec.md",
            ".claude/skills/corpus-management/docs/planted-guide.md",
            ".claude/skills/corpus-management/registers/planted-register.md",
        )
        with tempfile.TemporaryDirectory() as td:
            root = Path(td).resolve()
            for rel in planted:
                (root / rel).parent.mkdir(parents=True)
                (root / rel).write_text("# Planted\n\nGDPR Art. 33 applies.\n", encoding="utf-8")
            with mock.patch.object(mod, "REPO_ROOT", root):
                index = mod.group_by_key(mod.scan_files(mod.corpus_files(list(mod.DEFAULT_SCAN_ROOTS))))
        self.assertEqual(sorted(c.path for c in index.get("GDPR Art. 33", [])), sorted(planted))

    def test_exempt_file_entries_may_be_a_single_pass_iterator(self) -> None:
        # The basename check runs before the path check; an iterator of entries
        # must reach the path check unspent.
        from lint_common import is_exempt_file
        path = REPO_ROOT / "a" / "x.md"
        for entries, expected in ((["a/x.md"], True), (iter(["a/x.md"]), True),
                                  (iter(["x.md"]), True), (iter(["b/x.md", "y.md"]), False)):
            with self.subTest(entries=entries):
                self.assertIs(is_exempt_file(path, entries, repo_root=REPO_ROOT), expected)

    def test_d15_scope_follows_gate_6(self) -> None:
        mod = load_linter_module(".claude/skills/corpus-management/tools/check-alignment-register-on-pr.py",
                                 "d15_scope_skill_specs")
        self.assertTrue(mod.in_scope(self.SPEC))
        self.assertTrue(mod.in_scope("ai/framework-ai-assurance-evidence.md"))
        self.assertFalse(mod.in_scope(".claude/skills/corpus-management/docs/guide.md"))
        self.assertFalse(mod.in_scope(".claude/skills/corpus-management/tools/x.md"))
        self.assertFalse(mod.in_scope("README.md"))

    def test_review_cadence_excludes_ingestion_instruction_by_name(self) -> None:
        mod = load_linter_module(".claude/skills/corpus-management/tools/check-review-cadence.py",
                                 "review_cadence_skill_specs")
        rels = {p.relative_to(REPO_ROOT).as_posix() for p in mod.iter_active_docs()}
        self.assertNotIn(self.INGESTION, rels)
        self.assertIn(self.SPEC, rels)
        self.assertEqual(mod.iter_active_docs([REPO_ROOT / self.INGESTION]), [])

    def test_walker_matches_path_qualified_and_basename_exempt_files(self) -> None:
        import tempfile
        from lint_common import iter_markdown_targets
        with tempfile.TemporaryDirectory() as td:
            root = Path(td).resolve()
            for rel in ("a/x.md", "b/x.md"):
                (root / rel).parent.mkdir(parents=True)
                (root / rel).write_text("# x\n", encoding="utf-8")

            def scan(exempt: set[str]) -> list[str]:
                return sorted(p.relative_to(root).as_posix() for p in iter_markdown_targets(
                    [root], exempt_files=exempt, repo_root=root))

            self.assertEqual(scan(set()), ["a/x.md", "b/x.md"])
            self.assertEqual(scan({"a/x.md"}), ["b/x.md"])
            self.assertEqual(scan({"x.md"}), [])

    def _cross_file_exempt_case(self, script: str, unique: str) -> None:
        from unittest import mock
        mod = load_linter_module(script, unique)
        target = str(REPO_ROOT / self.TARGET)
        for exempt, calls in (({self.TARGET}, 0), ({Path(self.TARGET).name}, 0), (set(), 1)):
            with self.subTest(exempt=exempt), \
                 mock.patch.object(mod, "EXEMPT_FILES", frozenset(exempt)), \
                 mock.patch.object(mod, "check_file", return_value=[]) as check:
                self.assertEqual(mod.main([target]), 0)
                self.assertEqual(check.call_count, calls)

    def test_cross_file_refs_matches_path_qualified_exempt_entry(self) -> None:
        self._cross_file_exempt_case(".claude/skills/corpus-management/tools/lint-cross-file-section-refs.py",
                                     "xfile_refs_skill_specs")

    def test_cross_file_names_matches_path_qualified_exempt_entry(self) -> None:
        self._cross_file_exempt_case(".claude/skills/corpus-management/tools/lint-cross-file-section-names.py",
                                     "xfile_names_skill_specs")


