class ReviewCadenceTests(LinterTestCase):
    """.claude/skills/corpus-management/tools/check-review-cadence.py

    Tests the date-driven cadence enforcement by overriding --as-of to a
    date far past today. The corpus contains many documents with annual
    or quarterly review cadences and Dates in 2026; an as-of in 2030
    should put many of them past the action threshold.
    """

    def test_far_future_as_of_flags_documents(self) -> None:
        result = run_linter(
            ".claude/skills/corpus-management/tools/check-review-cadence.py",
            "--as-of",
            "2030-12-31",
        )
        self.assertLinterFails(result)

    def test_biannual_is_six_months_not_two_years(self) -> None:
        # Regression guard: 'biannual' means twice a year (6 months),
        # not every two years. Confused-with-biennial bug would put
        # document review schedules 18 months late.
        #
        # Test the FREQUENCY_MAP entry directly: the check-review-
        # cadence linter walks fixed domain directories and does not
        # accept a fixture-path argument, so we import the module and
        # assert the constant. The hyphenated filename requires
        # importlib.util.spec_from_file_location.
        import importlib.util
        spec = importlib.util.spec_from_file_location(
            "check_review_cadence",
            SKILL_ROOT / "tools" / "check-review-cadence.py",
        )
        self.assertIsNotNone(spec)
        self.assertIsNotNone(spec.loader)
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        # FREQUENCY_MAP is a list of (phrase, months) tuples. Find
        # the biannual entry.
        biannual_months = None
        for phrase, months in mod.FREQUENCY_MAP:
            if phrase == "biannual":
                biannual_months = months
                break
        self.assertEqual(
            biannual_months,
            6,
            "biannual should map to 6 months (twice a year), not 24 "
            "(biennial). Otherwise next-review-due dates for biannual "
            "documents are 18 months too late.",
        )
        # Defence in depth: also confirm biennial is still 24.
        biennial_months = None
        for phrase, months in mod.FREQUENCY_MAP:
            if phrase == "biennial":
                biennial_months = months
                break
        self.assertEqual(biennial_months, 24, "biennial should map to 24 months")

    def test_project_governance_in_domains(self) -> None:
        # The "full corpus audit sweep" in section 6.3 of
        # specification-project-governance-separation.md is read to include
        # review-cadence, so this gate's DOMAINS must hold the
        # .project-governance/ directory so that its non-README cadence-bearing
        # artefacts (the citation-verification registers and worklists, e.g. the
        # verifications register's 12-month re-verification) are scheduled rather
        # than unenforced. Gate 10 skips every README by design (see
        # iter_active_docs), so the directory's README is not cadence-scheduled
        # here; its date currency is covered by gate 31. In the earlier
        # repository a migration of this gate omitted the directory (the gate
        # walks a fixed domain list); the test asserts the constant directly
        # because the walk takes no fixture path.
        import importlib.util

        spec = importlib.util.spec_from_file_location(
            "check_review_cadence",
            SKILL_ROOT / "tools" / "check-review-cadence.py",
        )
        self.assertIsNotNone(spec)
        self.assertIsNotNone(spec.loader)
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        self.assertIn(
            ".claude/skills/corpus-management/registers",
            mod.DOMAINS,
            "gate 10 must scan .claude/skills/corpus-management/registers so the register's 12-month "
            "re-verification cadence is scheduled (gate 10 skips all READMEs "
            "by design, so the directory's README cadence is not scheduled here).",
        )

    def test_scope_never_reaches_the_pinned_rule_collections(self) -> None:
        # In the earlier repository EXEMPT_DIRECTORY_PREFIXES lost its last entry,
        # "guardrails/", because neither the per-domain walk nor the explicit-path
        # filter (DOMAINS or ROOT_DOCS only) can reach the rule pack. The pack no
        # longer ships as a top-level guardrails/ directory; it ships as the pinned
        # rule collections under .claude (vendored under .claude/aiqt/rules/, rendered
        # under .claude/rules/). Pin the same property on the live tree (which holds
        # those collections) and on a synthetic tree, so a non-domain directory
        # joining DOMAINS fails here instead of silently needing an exempt entry. The
        # registers directory is a domain that also sits under .claude, so the fixture
        # shows the boundary is the collection, not the .claude prefix.
        collections = _pinned_rule_collections()
        for rel in collections:
            self.assertTrue(any((REPO_ROOT / rel).glob("*.md")),
                            f"live tree should hold the pinned rule collection {rel}/")
        live = load_linter_module(".claude/skills/corpus-management/tools/check-review-cadence.py", "_check_review_cadence_live")
        scanned = [f.relative_to(REPO_ROOT).as_posix() for f in live.iter_active_docs()]
        self.assertTrue(scanned)
        self.assertEqual([r for r in scanned
                          if any(r.startswith(f"{c}/") for c in collections)], [])
        mod = load_linter_module(".claude/skills/corpus-management/tools/check-review-cadence.py", "_check_review_cadence_scope")
        registers = next(d for d in mod.DOMAINS if d.startswith(".claude/"))
        root = Path(tempfile.mkdtemp(prefix="cadence-scope-")).resolve()
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        pinned = [f"{c}/b.md" for c in collections]
        for rel in ("governance/a.md", *pinned, f"{collections[0]}/governance/c.md",
                    ".claude/skills/corpus-management/docs/d.md",
                    ".claude/skills/corpus-management/tools/e.md",
                    f"{registers}/r.md", "governance/specification-ingestion.md"):
            (root / rel).parent.mkdir(parents=True, exist_ok=True)
            (root / rel).write_text("x\n", encoding="utf-8")
        mod.REPO_ROOT = root
        walked = [f.relative_to(root).as_posix() for f in mod.iter_active_docs()]
        self.assertEqual(walked, [f"{registers}/r.md", "governance/a.md",
                                  "governance/specification-ingestion.md"])
        explicit = mod.iter_active_docs([*(Path(p) for p in pinned),
                                         Path(".claude/skills/corpus-management/docs/d.md"),
                                         Path("governance/a.md")])
        self.assertEqual([f.relative_to(root).as_posix() for f in explicit], ["governance/a.md"])
        unreachable = [p for p in mod.EXEMPT_DIRECTORY_PREFIXES
                       if not any(p.startswith(f"{d}/") for d in mod.DOMAINS)]
        self.assertEqual(unreachable, [], "prefixes the per-domain walk can never match")

    def test_scope_covers_the_moved_specifications_not_the_adopter_guides(self) -> None:
        # In the earlier repository, before the move, this gate scheduled the
        # specifications S1 and S2 in governance/, and they now sit in the skill's
        # specs/ directory. The adopter guides, outside this gate in docs/ before
        # the move, stay outside in the skill's docs/ directory. The expected
        # directories are written out here, not read from lint_common.
        mod = load_linter_module(".claude/skills/corpus-management/tools/check-review-cadence.py", "_check_review_cadence_planted")
        root = Path(tempfile.mkdtemp(prefix="cadence-planted-")).resolve()
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        planted = (
            "governance/a.md",
            ".claude/skills/corpus-management/specs/s.md",
            ".claude/skills/corpus-management/docs/g.md",
        )
        for rel in planted:
            (root / rel).parent.mkdir(parents=True, exist_ok=True)
            (root / rel).write_text("x\n", encoding="utf-8")
        mod.REPO_ROOT = root
        expected = [".claude/skills/corpus-management/specs/s.md", "governance/a.md"]
        walked = [f.relative_to(root).as_posix() for f in mod.iter_active_docs()]
        self.assertEqual(walked, expected)
        explicit = mod.iter_active_docs([Path(p) for p in planted])
        self.assertEqual([f.relative_to(root).as_posix() for f in explicit], expected)


