    def test_ok_line_names_only_lists_read(self) -> None:
        """The OK line names only the lists actually read. With no P-TODO.md (under --root, or on a default run with
        no private sibling or no P-TODO.md in it) it says .working/TODO.md alone and prints gate 81's explicit
        not-present line; with P-TODO.md present it names both. Exit status is 0 throughout."""
        import contextlib
        todo = "# TODO\n\n## Priority 2\n\n### 2.3 A public item\n\nBody.\n"
        both = "live backlog item(s) (.working/TODO.md + P-TODO.md)"
        only = "live backlog item(s) (.working/TODO.md),"
        absent = "OK: P-TODO.md not present ("
        root, result = self._run("perm-todo-only", todo, "# DONE\n")
        try:
            self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
            self.assertIn(only, result.stdout)
            self.assertNotIn(both, result.stdout)
            self.assertIn(absent, result.stdout)
            self.assertIn("Scanning .working/TODO.md only.", result.stdout)
        finally:
            shutil.rmtree(root, ignore_errors=True)
        root, result = self._run("perm-both-lists", todo, "# DONE\n",
                                 ptodo="# P-TODO\n\n### P-1.1 A private item\n\nBody.\n")
        try:
            self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
            self.assertIn(both, result.stdout)
            self.assertNotIn(absent, result.stdout)
        finally:
            shutil.rmtree(root, ignore_errors=True)
        # Default run (no --root): no private sibling, then a private sibling with no P-TODO.md in it.
        root = Path(tempfile.mkdtemp(prefix="perm-default-sibling-", dir=FIXTURE_DIR))
        try:
            (root / ".working").mkdir(parents=True, exist_ok=True)
            (root / ".working/TODO.md").write_text(
                "# TODO\n\n| ID | Item | Tags |\n| --- | --- | --- |\n| 2.3 | A public item | `[public]` |\n",
                encoding="utf-8")
            (root / "private").mkdir()
            for sibling in (None, root / "private"):
                m = self._perm_module()
                m.REPO_ROOT = root
                m.resolve_working = lambda _rel, **_kw: None
                m.resolve_sibling = lambda _name, _s=sibling, **_kw: _s
                buf = io.StringIO()
                with contextlib.redirect_stdout(buf):
                    rc = m.main(["lint-todo-number-permanence.py"])
                out = buf.getvalue()
                self.assertEqual(rc, 0, out)
                self.assertIn(only, out)
                self.assertNotIn(both, out)
                self.assertIn(absent, out)
        finally:
            shutil.rmtree(root, ignore_errors=True)

    def test_skip_and_degraded_name_which_absence(self) -> None:
        """The default run skips P-TODO.md for an absent private sibling AND for a usable sibling
        with no P-TODO.md in it. The skip line and the DEGRADED notice each name the case that
        applies, so the second never reads as "no private sibling". Exit status is 0 in both."""
        import contextlib
        root = Path(tempfile.mkdtemp(prefix="perm-skip-reason-", dir=FIXTURE_DIR))
        try:
            (root / ".working").mkdir(parents=True, exist_ok=True)
            (root / ".working/TODO.md").write_text(
                "# TODO\n\n| ID | Item | Tags |\n| --- | --- | --- |\n| 2.3 | A public item | `[public]` |\n",
                encoding="utf-8")
            sibling = root / "private"
            sibling.mkdir()
            cases = (
                (None,
                 "OK: P-TODO.md not present (no private sibling; public-only clone / adopter checkout). "
                 "Scanning .working/TODO.md only.",
                 "the P-TODO.md live ids and cross-list duplicate check (no private sibling supplies it)",
                 "has no P-TODO.md"),
                (sibling,
                 f"OK: P-TODO.md not present (the private sibling {sibling} has no P-TODO.md). "
                 f"Scanning .working/TODO.md only.",
                 "the P-TODO.md live ids and cross-list duplicate check "
                 "(the private sibling has no P-TODO.md)",
                 "no private sibling"),
            )
            for resolved, skip, degraded, wrong in cases:
                m = self._perm_module()
                m.REPO_ROOT = root
                m.resolve_working = lambda _rel, **_kw: None
                m.resolve_sibling = lambda _name, _s=resolved, **_kw: _s
                buf = io.StringIO()
                with contextlib.redirect_stdout(buf):
                    rc = m.main(["lint-todo-number-permanence.py"])
                out = buf.getvalue()
                self.assertEqual(rc, 0, out)
                self.assertIn(skip, out.splitlines())
                notice = [ln for ln in out.splitlines() if ln.startswith("DEGRADED: gate 78 skipped ")]
                self.assertEqual(len(notice), 1, out)
                self.assertIn(degraded, notice[0])
                self.assertNotIn(wrong, out)
        finally:
            shutil.rmtree(root, ignore_errors=True)

    def _perm_module(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location(
            "perm_pid", SKILL_ROOT / "tools" / "lint-todo-number-permanence.py")
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

