    def test_standalone_compiler_admits_a_repository_pinned_aiqt_root(self):
        # Positive control for the standalone compiler path: a verified,
        # repository-pinned pack binds the dependency; the compiler then
        # proceeds to its own configuration validation (the empty --root
        # has no pack) instead of failing on the AIQT dependency.
        pack = self._repo_pack_copy()
        compiler = SKILL_ROOT / "src" / "tools" / "corpus_mgmt_compiler.py"
        env = {k: v for k, v in os.environ.items()
               if k not in ("AIQT_PACK_ROOT", "GRC_AIQT_PACK")}
        with tempfile.TemporaryDirectory() as tmp:
            res = subprocess.run(
                [sys.executable, "-I", str(compiler), "--check",
                 "--root", tmp, "--aiqt-root", str(pack)],
                capture_output=True, text=True, env=env, timeout=120)
        output = res.stdout + res.stderr
        self.assertEqual(res.returncode, 2, output)
        self.assertNotIn("does not verify", output)
        self.assertNotIn("aiqt_corpus module is unavailable", output)
        self.assertIn("pack root not found", output)
        # The positive control also asserts the INSTALLED module's origin is
        # the explicit root's module, so a fallback that bound another copy
        # could not pass this test.
        probe = (
            "import importlib.util, sys\n"
            "from pathlib import Path\n"
            "spec = importlib.util.spec_from_file_location("
            f"'corpus_mgmt_compiler_originprobe', {str(compiler)!r})\n"
            "mod = importlib.util.module_from_spec(spec)\n"
            "spec.loader.exec_module(mod)\n"
            f"problem = mod._ensure_aiqt(Path({str(pack)!r}))\n"
            "print('PROBLEM:', problem)\n"
            "print('ORIGIN:', sys.modules['aiqt_corpus'].__spec__.origin)\n")
        res = subprocess.run([sys.executable, "-I", "-c", probe],
                             capture_output=True, text=True, env=env,
                             timeout=120)
        self.assertEqual(res.returncode, 0, res.stdout + res.stderr)
        self.assertIn("PROBLEM: None", res.stdout)
        self.assertIn(f"ORIGIN: {pack / 'tools' / 'aiqt_corpus.py'}",
                      res.stdout)

    def test_stale_pack_path_is_scrubbed_before_verification(self):
        # A caller's stale pack tools/ entry is removed from sys.path at
        # the START of bootstrap, BEFORE verification and capture, so a
        # concurrent import of aiqt_corpus inside the verification window
        # fails closed with ModuleNotFoundError instead of executing
        # rewritten disk bytes, and the module the bootstrap then installs
        # is built from the captured verified bytes (in the earlier
        # repository, the bootstrap removed the entry only after capture
        # and then accepted the disk module by origin).
        import importlib
        import threading
        from unittest.mock import patch
        pack = self._repo_pack_copy()
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_stalepath")
        swapped = b"SWAPPED_IN = True\n"
        outcomes = {}
        original = mod._verified

        def concurrent_import():
            try:
                outcomes["module"] = importlib.import_module("aiqt_corpus")
            except ImportError as exc:
                outcomes["error"] = exc

        def capture_then_race(pack_root, what):
            result = original(pack_root, what)
            # The race under test: verification and capture are done; a
            # stale sys.path entry would still reach the pack, the module
            # file is rewritten, and another thread imports aiqt_corpus.
            (Path(pack_root) / "tools" / "aiqt_corpus.py").write_bytes(swapped)
            thread = threading.Thread(target=concurrent_import)
            thread.start()
            thread.join(timeout=60)
            self.assertFalse(thread.is_alive(), "the concurrent importer hung")
            return result

        stale = str(pack / "tools")
        saved_module = sys.modules.pop("aiqt_corpus", None)
        saved_path = list(sys.path)
        try:
            sys.path[:] = [e for e in sys.path
                           if not (Path(e) / "aiqt_corpus.py").is_file()]
            sys.path.insert(0, stale)  # the caller's stale insert
            with patch.object(mod, "_verified", capture_then_race), \
                    patch.dict(os.environ, {"AIQT_PACK_ROOT": str(pack)}):
                os.environ.pop("GRC_AIQT_PACK", None)
                mod.ensure_on_path()
                corpus = importlib.import_module("aiqt_corpus")
            self.assertNotIn(stale, sys.path,
                             "the stale pack tools/ entry survived bootstrap")
            self.assertNotIn(
                "module", outcomes,
                "the concurrent import must fail closed during verification; "
                f"it got {getattr(outcomes.get('module'), '__file__', None)!r}")
            self.assertIsInstance(outcomes.get("error"), ModuleNotFoundError)
            self.assertFalse(getattr(corpus, "SWAPPED_IN", False),
                             "the rewritten on-disk module bytes ran")
            self.assertEqual(corpus.__file__,
                             str(pack / "tools" / "aiqt_corpus.py"))
        finally:
            sys.modules.pop("aiqt_corpus", None)
            if saved_module is not None:
                sys.modules["aiqt_corpus"] = saved_module
            sys.path[:] = saved_path

    def test_bootstrap_holds_no_import_lock_while_the_verified_module_executes(self):
        # The captured bytes execute with NO import lock held. The child
        # pauses another thread inside the real subprocess module's
        # execution (that thread holds subprocess's per-module import
        # lock); it resumes with a nested import -- which needs the global
        # import lock -- once it sees the global lock held continuously, or
        # after a deadline. A bootstrap that held the global lock across
        # execution deadlocks the CHILD (both threads wait on each other's
        # lock), surfacing here as TimeoutExpired, never a wedged suite;
        # the lock-free execution completes.
        shim = SKILL_ROOT / "tools" / "aiqt_bootstrap.py"
        probe = (
            "import _imp, importlib.machinery, importlib.util, sys, threading, time, types\n"
            "from pathlib import Path\n"
            "assert 'subprocess' not in sys.modules\n"
            "in_exec = threading.Event()\n"
            "class PauseLoader:\n"
            "    def __init__(self, real):\n"
            "        self.real = real\n"
            "    def create_module(self, spec):\n"
            "        return None\n"
            "    def exec_module(self, module):\n"
            "        in_exec.set()\n"
            "        deadline = time.monotonic() + 5.0\n"
            "        stable = 0\n"
            "        while time.monotonic() < deadline:\n"
            "            if _imp.lock_held():\n"
            "                stable += 1\n"
            "                if stable >= 30:\n"
            "                    break\n"
            "            else:\n"
            "                stable = 0\n"
            "            time.sleep(0.01)\n"
            "        import colorsys\n"
            "        self.real.loader.exec_module(module)\n"
            "class PauseFinder:\n"
            "    done = False\n"
            "    def find_spec(self, name, path=None, target=None):\n"
            "        if name != 'subprocess' or PauseFinder.done:\n"
            "            return None\n"
            "        PauseFinder.done = True\n"
            "        real = importlib.machinery.PathFinder.find_spec('subprocess')\n"
            "        return importlib.util.spec_from_loader("
            "'subprocess', PauseLoader(real), origin=real.origin)\n"
            "sys.meta_path.insert(0, PauseFinder())\n"
            "b = threading.Thread(target=__import__, args=('subprocess',), daemon=True)\n"
            "b.start()\n"
            "assert in_exec.wait(timeout=30)\n"
            f"shim = Path({str(shim)!r})\n"
            "src = shim.read_text(encoding='utf-8')\n"
            "tail = 'ensure_on_path()\\n'\n"
            "assert src.endswith(tail)\n"
            "mod = types.ModuleType('aiqt_bootstrap_lockprobe')\n"
            "mod.__file__ = str(shim)\n"
            "exec(compile(src[:-len(tail)], str(shim), 'exec'), mod.__dict__)\n"
            "mod._verified_corpus_source = b'import subprocess\\nX = 1\\n'\n"
            f"mod._install_verified_corpus(Path({str(shim.parent)!r}))\n"
            "b.join(timeout=60)\n"
            "assert not b.is_alive()\n"
            "print('LOCK-FREE-EXEC-OK', sys.modules['aiqt_corpus'].X)\n")
        env = {k: v for k, v in os.environ.items()
               if k not in ("AIQT_PACK_ROOT", "GRC_AIQT_PACK")}
        res = subprocess.run([sys.executable, "-I", "-c", probe],
                             capture_output=True, text=True, env=env,
                             timeout=120)
        self.assertEqual(res.returncode, 0, res.stdout + res.stderr)
        self.assertIn("LOCK-FREE-EXEC-OK 1", res.stdout)

    def test_explicit_compiler_root_without_pin_is_a_configuration_error(self):
        # An explicit --aiqt-root carrying tools/aiqt_corpus.py but no
        # PIN.toml (and no .aiqt) is refused as a configuration error (exit
        # 2) naming PIN.toml, with no fallback to the in-repo vendored
        # copy: the compiler must fail on the AIQT root, never proceed to
        # its own configuration validation with a silently substituted
        # pack, and the sentinel must never run.
        base = self._fixture_base("aiqt-nopin-root-")
        root = base / "pack"
        (root / "tools").mkdir(parents=True)
        (root / "tools" / "aiqt_corpus.py").write_text(
            "print('SENTINEL-NOPIN-ROOT')\n", encoding="utf-8")
        compiler = SKILL_ROOT / "src" / "tools" / "corpus_mgmt_compiler.py"
        env = {k: v for k, v in os.environ.items()
               if k not in ("AIQT_PACK_ROOT", "GRC_AIQT_PACK")}
