    def test_embedded_nul_sys_path_entry_never_raises_valueerror(self):
        # In the earlier repository, a change moved os.path.realpath
        # ahead of the empty-entry check's name test while catching only
        # OSError, so a sys.path entry with an embedded NUL raised
        # ValueError out of ensure_on_path(), which promises ImportError.
        # Now _pack_tools_entry reports such an entry unmatched (never an
        # exception), and the masquerade scan -- which such an entry also
        # breaks -- refuses with ImportError naming the uninspectable
        # entry, never a raw ValueError.
        from unittest.mock import patch
        pack = self._repo_pack_copy()
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_nulentry")
        for entry in ("\x00/tools", "x\x00y"):
            with self.subTest(entry=repr(entry)):
                self.assertFalse(mod._pack_tools_entry(entry))

        def provides_corpus(e):
            try:
                return (Path(e) / "aiqt_corpus.py").is_file()
            except (OSError, ValueError):
                return False

        saved_module = sys.modules.pop("aiqt_corpus", None)
        saved_path = list(sys.path)
        saved_meta = list(sys.meta_path)
        try:
            sys.path[:] = [e for e in sys.path if not provides_corpus(e)]
            sys.path.insert(0, "x\x00y")
            with patch.dict(os.environ, {"AIQT_PACK_ROOT": str(pack)}):
                os.environ.pop("GRC_AIQT_PACK", None)
                with self.assertRaisesRegex(
                        ImportError, re.escape("uninspectable sys.path entry in place.")):
                    mod.ensure_on_path()
        finally:
            sys.modules.pop("aiqt_corpus", None)
            if saved_module is not None:
                sys.modules["aiqt_corpus"] = saved_module
            sys.path[:] = saved_path
            sys.meta_path[:] = saved_meta

    def test_concurrent_import_fails_closed_with_every_alias_form_on_path(self):
        # The name guard owns the name whatever sys.path holds: with every
        # known alias form present AT ONCE -- the literal pack tools/
        # entry, a directory symlink alias, a symlink named tools in a
        # markerless parent, a plain directory holding a file-level
        # aiqt_corpus.py symlink, a benign symlink retargeted to the pack
        # tools/ after the scrub, and a relative entry re-resolved after a
        # chdir -- a concurrent import during the verification window fails
        # closed with ModuleNotFoundError and the rewritten disk bytes
        # never run. The resolved-path scrub still removes the three forms
        # it can see.
        if os.name != "posix":
            self.skipTest("needs POSIX symlinks")
        import importlib
        import threading
        from unittest.mock import patch
        pack = self._repo_pack_copy()
        base = self._fixture_base("aiqt-allalias-")
        benign = base / "benign"
        benign.mkdir()
        cwd_start = base / "cwd-benign"
        cwd_start.mkdir()
        dirlink = base / "dirlink"
        dirlink.symlink_to(pack / "tools")
        (base / "markerless").mkdir()
        toolslink = base / "markerless" / "tools"
        toolslink.symlink_to(pack / "tools")
        plain = base / "plaindir"
        plain.mkdir()
        (plain / "aiqt_corpus.py").symlink_to(pack / "tools"
                                              / "aiqt_corpus.py")
        retarget = base / "retarget"
        retarget.symlink_to(benign)
        scrubbed = [str(pack / "tools"), str(dirlink), str(toolslink)]
        survivors = [str(plain), str(retarget), "tools"]
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_allalias")
        outcomes = {}
        original = mod._verified
        saved_cwd = os.getcwd()

        def concurrent_import():
            try:
                outcomes["module"] = importlib.import_module("aiqt_corpus")
            except ImportError as exc:
                outcomes["error"] = exc

        def capture_then_race(pack_root, what):
            result = original(pack_root, what)
            outcomes["scrubbed_gone"] = all(e not in sys.path
                                            for e in scrubbed)
            outcomes["survivors_live"] = all(e in sys.path
                                             for e in survivors)
            retarget.unlink()
            retarget.symlink_to(pack / "tools")
            os.chdir(pack)
            (Path(pack_root) / "tools"
             / "aiqt_corpus.py").write_bytes(b"SWAPPED_IN = True\n")
            importlib.invalidate_caches()
            thread = threading.Thread(target=concurrent_import)
            thread.start()
            thread.join(timeout=60)
            outcomes["importer_done"] = not thread.is_alive()
            return result

        saved_module = sys.modules.pop("aiqt_corpus", None)
        saved_path = list(sys.path)
        saved_meta = list(sys.meta_path)
        try:
            os.chdir(cwd_start)
            sys.path[:] = [e for e in sys.path
                           if not (Path(e) / "aiqt_corpus.py").is_file()]
            sys.path[0:0] = scrubbed + survivors
            with patch.object(mod, "_verified", capture_then_race), \
                    patch.dict(os.environ, {"AIQT_PACK_ROOT": str(pack)}):
                os.environ.pop("GRC_AIQT_PACK", None)
                with self.assertRaises(ImportError):
                    mod.ensure_on_path()
            self.assertTrue(outcomes.get("importer_done"),
                            "the concurrent importer hung")
            self.assertTrue(outcomes.get("scrubbed_gone"),
                            "the resolved-path scrub must still remove the "
                            "literal entry and the directory-level aliases")
            self.assertTrue(outcomes.get("survivors_live"),
                            "the guard-only alias forms should survive the "
                            "scrub: the name guard is under test")
            self.assertNotIn(
                "module", outcomes,
                "the concurrent import must fail closed with every alias "
                "form on sys.path; it got "
                f"{getattr(outcomes.get('module'), '__file__', None)!r}")
            self.assertIsInstance(outcomes.get("error"),
                                  ModuleNotFoundError)
            self.assertIsNone(sys.modules.get("aiqt_corpus"),
                              "a module was published despite the "
                              "fail-closed window")
        finally:
            os.chdir(saved_cwd)
            sys.modules.pop("aiqt_corpus", None)
            if saved_module is not None:
                sys.modules["aiqt_corpus"] = saved_module
            sys.path[:] = saved_path
            sys.meta_path[:] = saved_meta
            sys.path_importer_cache.pop("tools", None)
            importlib.invalidate_caches()

    def test_published_guard_serves_only_the_verified_module(self):
        # Once the verified module is published, the name guard serves ONLY
        # it: with the pack file rewritten ON DISK and both a pack tools/
        # entry and a file-level symlink alias freshly put on sys.path, an
        # import of aiqt_corpus after the name is emptied from sys.modules
        # still yields the published verified module object itself --
        # sys.path is never consulted for the name.
        if os.name != "posix":
            self.skipTest("needs POSIX symlinks")
        import importlib
        from unittest.mock import patch
        pack = self._repo_pack_copy()
        base = self._fixture_base("aiqt-guardserve-")
        plain = base / "plaindir"
        plain.mkdir()
        (plain / "aiqt_corpus.py").symlink_to(pack / "tools"
                                              / "aiqt_corpus.py")
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_guardserve")
        saved_module = sys.modules.pop("aiqt_corpus", None)
        saved_path = list(sys.path)
        saved_meta = list(sys.meta_path)
        try:
            sys.path[:] = [e for e in sys.path
                           if not (Path(e) / "aiqt_corpus.py").is_file()]
            with patch.dict(os.environ, {"AIQT_PACK_ROOT": str(pack)}):
                os.environ.pop("GRC_AIQT_PACK", None)
                mod.ensure_on_path()
                published = importlib.import_module("aiqt_corpus")
                (pack / "tools" / "aiqt_corpus.py").write_bytes(
                    b"SWAPPED_IN = True\n")
                sys.path.insert(0, str(pack / "tools"))
                sys.path.insert(0, str(plain))
                sys.modules.pop("aiqt_corpus", None)
                importlib.invalidate_caches()
                again = importlib.import_module("aiqt_corpus")
            self.assertIs(again, published,
                          "the guard must serve the published verified "
                          "module object itself, never a re-import")
            self.assertFalse(getattr(again, "SWAPPED_IN", False),
                             "the rewritten on-disk module bytes ran")
            self.assertIn(mod._INSTALL_MARKER_ATTR, again.__dict__,
                          "the served module must carry the installation "
                          "marker")
        finally:
            sys.modules.pop("aiqt_corpus", None)
            if saved_module is not None:
                sys.modules["aiqt_corpus"] = saved_module
            sys.path[:] = saved_path
            sys.meta_path[:] = saved_meta
            importlib.invalidate_caches()

