    def test_repo_root_premise_and_dotted_routes_scrubbed(self):
        # In the earlier repository, the bootstrap disclosed the
        # dotted-name residual on a false premise -- that the repository
        # root, an ancestor of the in-repo pack, is a legitimate sys.path
        # entry through which a dotted import runs the on-disk pack
        # bytes. Executed, that is false: .claude is not a Python
        # identifier, so NO dotted spelling reaches the in-repo pack
        # through a repository-root entry. The routes that DO reach the
        # file are a pack-root entry (import tools.aiqt_corpus), a
        # pack-root-parent entry (import aiqt.tools.aiqt_corpus through a
        # .claude entry) and, for an OVERRIDE pack, any chain of
        # identifier-named ancestors. This test pins the executed
        # premise, the corrected docstrings, and the second scrub layer:
        # ensure_on_path now also removes entries resolving to a pack
        # ROOT or to a pack root's PARENT, while a repository-root-shaped
        # entry (no dotted route) and an override pack's deeper
        # identifier-named ancestor (the disclosed REMAINING residual)
        # survive.
        import importlib
        from unittest.mock import patch
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_reporoot")
        self.assertFalse(".claude".isidentifier())
        docs = {
            "module": " ".join(mod.__doc__.split()),
            "scrub": " ".join(
                mod._scrub_pack_tools_entries.__doc__.split()),
            "ensure_on_path": " ".join(mod.ensure_on_path.__doc__.split()),
        }
        for where, text in docs.items():
            self.assertNotIn("keeps names OTHER than", text,
                             f"the {where} docstring must not claim the "
                             "scrub keeps other names unimportable "
                             "(the disclosed residual of a pack file imported under a dotted name)")
            self.assertNotIn("keeps OTHER names", text,
                             f"the {where} docstring must not claim the "
                             "scrub keeps other names unimportable "
                             "(the disclosed residual of a pack file imported under a dotted name)")
            self.assertNotIn(
                "legitimate ``sys.path`` entry that cannot be scrubbed "
                "away", text,
                f"the {where} docstring must not repeat the false "
                "premise that the repository root is a dotted route to "
                "the in-repo pack (corrects the premise of a repository root wrongly treated as a dotted route)")
        self.assertIn("a repository root wrongly treated as a dotted route", docs["module"],
                      "REMAINING must name the corrected premise")
        self.assertIn("``.claude`` is not a Python identifier",
                      docs["module"],
                      "the docstring must state WHY the repository root "
                      "is not a dotted route")
        self.assertIn("the REPOSITORY ROOT does NOT", docs["module"],
                      "the docstring must state the executed fact that "
                      "the repository root reaches the in-repo pack "
                      "under no module name")
        # Executed premise, in a clean child interpreter: the repository
        # root reaches the in-repo pack under NO dotted spelling; a
        # pack-root entry and a pack-root-parent entry both reach it.
        repo_root = REPO_ROOT
        pack_root = repo_root / ".claude" / "aiqt"
        probe = (
            "import importlib, sys\n"
            "sys.dont_write_bytecode = True\n"
            "def attempt(entry, dotted):\n"
            "    sys.path.insert(0, entry)\n"
            "    try:\n"
            "        m = importlib.import_module(dotted)\n"
            "        print('LOADED', dotted, getattr(m, '__file__', None))\n"
            "    except ModuleNotFoundError:\n"
            "        print('REFUSED', dotted)\n"
            "    finally:\n"
            "        sys.path.remove(entry)\n"
            "for dotted in ('claude.aiqt.tools.aiqt_corpus',\n"
            "               'aiqt.tools.aiqt_corpus', 'tools.aiqt_corpus'):\n"
            f"    attempt({str(repo_root)!r}, dotted)\n"
            f"attempt({str(pack_root)!r}, 'tools.aiqt_corpus')\n"
            "sys.modules.pop('tools', None)\n"
            "sys.modules.pop('tools.aiqt_corpus', None)\n"
            "importlib.invalidate_caches()\n"
            f"attempt({str(pack_root.parent)!r}, 'aiqt.tools.aiqt_corpus')\n")
        res = subprocess.run([sys.executable, "-I", "-c", probe],
                             capture_output=True, text=True, timeout=120)
        self.assertEqual(res.returncode, 0, res.stderr)
        lines = res.stdout.strip().splitlines()
        expected_file = str(pack_root / "tools" / "aiqt_corpus.py")
        self.assertEqual(lines[:3],
                         ["REFUSED claude.aiqt.tools.aiqt_corpus",
                          "REFUSED aiqt.tools.aiqt_corpus",
                          "REFUSED tools.aiqt_corpus"],
                         "no dotted spelling may reach the in-repo pack "
                         "through a repository-root entry "
                         "(corrects the premise of a repository root wrongly treated as a dotted route)")
        self.assertEqual(lines[3],
                         f"LOADED tools.aiqt_corpus {expected_file}",
                         "a pack-root entry is a real dotted route")
        self.assertEqual(lines[4],
                         f"LOADED aiqt.tools.aiqt_corpus {expected_file}",
                         "a pack-root-parent entry is a real dotted route")
        # The second scrub layer, and the disclosed REMAINING residual.
        pack = self._repo_pack_copy()           # <base>/.claude/aiqt
        base = pack.parent.parent               # repository-root-shaped
        anc = self._fixture_base("aiqt-ancestor-")
        over = anc / "grand" / "pk"
        (over / "tools").mkdir(parents=True)
        (over / "tools" / "aiqt_corpus.py").write_text(
            "ANCESTOR_ROUTE = True\n")
        (over / "PIN.toml").write_text("[source]\n")
        saved_module = sys.modules.pop("aiqt_corpus", None)
        saved_path = list(sys.path)
        saved_meta = list(sys.meta_path)
        added = [str(pack), str(pack.parent), str(base), str(anc)]
        try:
            sys.path[:] = [e for e in sys.path
                           if not (Path(e) / "aiqt_corpus.py").is_file()]
            for e in added:
                sys.path.insert(0, e)
            with patch.dict(os.environ, {"AIQT_PACK_ROOT": str(pack)}):
                os.environ.pop("GRC_AIQT_PACK", None)
                mod.ensure_on_path()
                self.assertNotIn(str(pack), sys.path,
                                 "a pack-root entry must be scrubbed: it is a "
                                 "recognized dotted route to the pack file")
                self.assertNotIn(str(pack.parent), sys.path,
                                 "a pack-root-parent entry must be "
                                 "scrubbed: it is a recognized dotted route to the pack file")
                self.assertIn(str(base), sys.path,
                              "a repository-root-shaped entry (its "
                              "pack-root grandchild sits below the "
                              "non-identifier .claude, so it carries no "
                              "dotted route) must be kept")
                self.assertIn(str(anc), sys.path,
                              "an identifier-named ancestor two levels "
                              "above an override pack root is the "
                              "disclosed REMAINING residual and is kept")
                importlib.invalidate_caches()
                dotted = importlib.import_module(
                    "grand.pk.tools.aiqt_corpus")
                bare = importlib.import_module("aiqt_corpus")
            self.assertEqual(dotted.__file__,
                             str(over / "tools" / "aiqt_corpus.py"),
                             "the surviving ancestor route really loads "
                             "the on-disk file: the residual the "
                             "docstring discloses")
            self.assertNotIn(mod._INSTALL_MARKER_ATTR, dotted.__dict__,
                             "the dotted-name module is a plain disk "
                             "import, not the published verified module")
            self.assertIn(mod._INSTALL_MARKER_ATTR, bare.__dict__,
                          "the bare name must still serve the published "
                          "verified module")
        finally:
            for name in ("aiqt_corpus", "grand", "grand.pk",
                         "grand.pk.tools", "grand.pk.tools.aiqt_corpus"):
                sys.modules.pop(name, None)
            if saved_module is not None:
                sys.modules["aiqt_corpus"] = saved_module
            sys.path[:] = saved_path
            sys.meta_path[:] = saved_meta
            importlib.invalidate_caches()

    def test_rerun_displaces_a_finder_placed_in_front_of_the_guard(self):
        # In the earlier repository, the bootstrap inserted the guard only
        # when absent, so a finder placed at sys.meta_path[0] after the
        # first bootstrap stayed in front of the guard on every later run
        # and decided the name first. Now every bootstrap run removes the
        # guard if present and re-inserts it at index 0 under the lock, so
        # the next run displaces such a finder behind the guard (a finder
        # inserted in front with NO further run remains the disclosed
        # REMAINING gap).
        from unittest.mock import patch

        class FrontFinder:
            def find_spec(self, fullname, path=None, target=None):
                return None

        pack = self._repo_pack_copy()
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_refront")
        front = FrontFinder()
        saved_module = sys.modules.pop("aiqt_corpus", None)
        saved_path = list(sys.path)
        saved_meta = list(sys.meta_path)
        try:
            with patch.dict(os.environ, {"AIQT_PACK_ROOT": str(pack)}):
                os.environ.pop("GRC_AIQT_PACK", None)
                mod.ensure_on_path()
                self.assertIs(sys.meta_path[0], mod._NAME_GUARD,
                              "the first run must put the guard at the "
                              "front")
                sys.meta_path.insert(0, front)
                self.assertIs(sys.meta_path[0], front)
                mod.ensure_on_path()
            self.assertIs(sys.meta_path[0], mod._NAME_GUARD,
                          "a re-run must put the guard back at the FRONT "
                          "of sys.meta_path, displacing a finder inserted "
                          "ahead of it (guards against a finder left in front of the guard)")
            self.assertIn(front, sys.meta_path,
                          "the foreign finder is displaced, not removed")
            self.assertGreater(sys.meta_path.index(front),
                               sys.meta_path.index(mod._NAME_GUARD),
                               "the displaced finder must sit BEHIND the "
                               "guard")
            self.assertEqual(
                sys.meta_path.count(mod._NAME_GUARD), 1,
                "re-fronting must not duplicate the guard")
        finally:
            sys.modules.pop("aiqt_corpus", None)
            if saved_module is not None:
                sys.modules["aiqt_corpus"] = saved_module
            sys.path[:] = saved_path
            sys.meta_path[:] = saved_meta

    def test_non_str_sys_path_entries_are_skipped_never_typeerror(self):
        # In the earlier repository, a bytes or int sys.path entry made the
        # scrub raise TypeError out of ensure_on_path(), which promises
        # ImportError. The import system's own PathFinder skips such entries
        # (observed: find_spec over a bytes or int entry returns None); the
        # scrub and the masquerade scan now skip them the same way:
        # _pack_tools_entry reports them unmatched, the bootstrap completes
        # with the entries left in place (they are not pack tools/ entries),
        # and no TypeError escapes. aiqt_corpus is emptied from sys.modules
        # first so the masquerade scan really runs over the non-str entries.
        import importlib
        from unittest.mock import patch
        pack = self._repo_pack_copy()
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_nonstrentry")
        bytes_entry = b"/nonstr-bytes-entry"
        int_entry = 42
        for entry in (bytes_entry, int_entry):
            with self.subTest(entry=repr(entry)):
                self.assertFalse(
                    mod._pack_tools_entry(entry),
                    "a non-str entry must be reported unmatched, never "
                    "raise (guards against a TypeError out of the scrub)")
        saved_module = sys.modules.pop("aiqt_corpus", None)
        saved_path = list(sys.path)
        saved_meta = list(sys.meta_path)
        try:
            sys.path[:] = [e for e in sys.path
                           if not (Path(e) / "aiqt_corpus.py").is_file()]
            sys.path.insert(0, bytes_entry)
            sys.path.insert(0, int_entry)
            with patch.dict(os.environ, {"AIQT_PACK_ROOT": str(pack)}):
                os.environ.pop("GRC_AIQT_PACK", None)
                try:
                    tools = mod.ensure_on_path()
                except TypeError as exc:
                    self.fail("ensure_on_path() raised TypeError on a "
                              f"non-str sys.path entry: {exc} "
                              "(guards against a TypeError out of the scrub on a "
                              "non-str entry)")
            self.assertEqual(str(tools), str(pack / "tools"),
                             "the bootstrap must complete normally with "
                             "non-str entries present")
            self.assertIn(bytes_entry, sys.path,
                          "a non-str entry is skipped, not removed: it is "
                          "not a pack tools/ entry")
            self.assertIn(int_entry, sys.path,
                          "a non-str entry is skipped, not removed: it is "
                          "not a pack tools/ entry")
            self.assertIn(mod._INSTALL_MARKER_ATTR,
                          sys.modules["aiqt_corpus"].__dict__,
                          "the published module must carry the "
                          "installation marker")
        finally:
            sys.modules.pop("aiqt_corpus", None)
            if saved_module is not None:
                sys.modules["aiqt_corpus"] = saved_module
            sys.path[:] = saved_path
            sys.meta_path[:] = saved_meta
            importlib.invalidate_caches()

    def test_refront_keeps_guard_present_in_every_meta_path_state(self):
        # In the earlier repository, the bootstrap re-fronted the guard
        # with sys.meta_path.remove() followed by insert(0, ...) -- two
        # list operations. Python 3.14's importer snapshots sys.meta_path
        # with list(meta_path) BEFORE taking any import lock (gh-130094),
        # so a concurrent import whose snapshot landed between the two
        # steps saw NO guard and fell through to sys.path; in that code, a
        # forced interleaving made a concurrent import execute planted,
        # unverified on-disk bytes. The re-front is now ONE atomic slice
        # assignment built from the old list first. This test instruments
        # every mutating operation on sys.meta_path during a re-run and
        # asserts the guard is present in the state the list holds AFTER
        # every mutation step (and before the first one), so the two-step
        # form is observed to fail at its remove() step; it also pins the
        # end state: the guard at index 0 exactly once.
        from unittest.mock import patch
        pack = self._repo_pack_copy()
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_refront_states")
        guard = mod._NAME_GUARD
        states = []

        def has_guard(items):
            return any(f is guard for f in items)

        class RecordingMetaPath(list):
            def _record(self, op):
                states.append((op, has_guard(list.copy(self))))

            def remove(self, x):
                list.remove(self, x)
                self._record("remove")

            def insert(self, index, x):
                list.insert(self, index, x)
                self._record("insert")

            def append(self, x):
                list.append(self, x)
                self._record("append")

            def extend(self, items):
                list.extend(self, items)
                self._record("extend")

            def pop(self, index=-1):
                out = list.pop(self, index)
                self._record("pop")
                return out

            def clear(self):
                list.clear(self)
                self._record("clear")

            def __setitem__(self, key, value):
                list.__setitem__(self, key, value)
                self._record("setitem")

            def __delitem__(self, key):
                list.__delitem__(self, key)
                self._record("delitem")

        saved_module = sys.modules.pop("aiqt_corpus", None)
        saved_path = list(sys.path)
        saved_meta_obj = sys.meta_path
        saved_meta = list(sys.meta_path)
        try:
            with patch.dict(os.environ, {"AIQT_PACK_ROOT": str(pack)}):
                os.environ.pop("GRC_AIQT_PACK", None)
                mod.ensure_on_path()        # first run installs the guard
                sys.modules.pop("aiqt_corpus", None)  # a retry re-run
                recording = RecordingMetaPath(sys.meta_path)
                sys.meta_path = recording
                self.assertTrue(has_guard(recording),
                                "the re-run must start with the guard "
                                "already present")
                mod.ensure_on_path()        # the observed re-run
            self.assertTrue(states,
                            "the re-run must re-front the guard (at "
                            "least one observed sys.meta_path mutation)")
            for op, present in states:
                self.assertTrue(
                    present,
                    f"sys.meta_path passed through a state WITHOUT the "
                    f"guard after a {op} step: a concurrent import's "
                    "unlocked list(sys.meta_path) snapshot can land in "
                    "exactly that gap and fall through to sys.path "
                    "(guards against a guardless gap during the re-front)")
            self.assertIs(sys.meta_path[0], guard,
                          "after the re-run the guard is at index 0")
            self.assertEqual(
                sum(1 for f in sys.meta_path if f is guard), 1,
                "after the re-run the guard appears exactly once")
        finally:
            sys.meta_path = saved_meta_obj
            sys.meta_path[:] = saved_meta
            sys.modules.pop("aiqt_corpus", None)
            if saved_module is not None:
                sys.modules["aiqt_corpus"] = saved_module
            sys.path[:] = saved_path

    def test_refused_prebootstrap_module_is_removed_from_sys_modules(self):
        # In the earlier repository, the bootstrap raised ImportError
        # when an unmarked aiqt_corpus was already in sys.modules, but
        # left the module there, so a later import of the name in the
        # same process returned the unmarked module while the guard
        # stayed unpublished. ensure_on_path now removes the refused
        # module from sys.modules under the import lock (only when it is
        # still the same object) before re-raising, so the name fails
        # closed for the rest of the process.
        import importlib
        import types
        from unittest.mock import patch
        pack = self._repo_pack_copy()
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_prestay")
        impostor = types.ModuleType("aiqt_corpus")
        impostor.__file__ = str(pack / "tools" / "aiqt_corpus.py")
        saved_module = sys.modules.pop("aiqt_corpus", None)
        saved_path = list(sys.path)
        saved_meta = list(sys.meta_path)
        try:
            sys.modules["aiqt_corpus"] = impostor
            with patch.dict(os.environ, {"AIQT_PACK_ROOT": str(pack)}):
                os.environ.pop("GRC_AIQT_PACK", None)
                with self.assertRaisesRegex(
                        ImportError, "installation marker"):
                    mod.ensure_on_path()
                self.assertNotIn(
                    "aiqt_corpus", sys.modules,
                    "the refused pre-bootstrap module must be removed "
                    "from sys.modules, not left importable "
                    "(guards against an unmarked pre-guard module left importable)")
                with self.assertRaises(ModuleNotFoundError):
                    importlib.import_module("aiqt_corpus")
        finally:
            sys.modules.pop("aiqt_corpus", None)
            if saved_module is not None:
                sys.modules["aiqt_corpus"] = saved_module
            sys.path[:] = saved_path
            sys.meta_path[:] = saved_meta

    def test_empty_sys_path_entry_is_scrubbed_like_dot(self):
        # In the earlier repository, _pack_dotted_entry returned False for
        # the empty sys.path entry while removing ".", so with the working
        # directory at a pack root or at a pack root's parent the empty
        # entry survived the scrub and import tools.aiqt_corpus (or
        # aiqt.tools.aiqt_corpus) loaded the on-disk pack bytes without the
        # installation marker. The scrub now resolves the empty entry
        # against the current working directory, exactly like ".", in both
        # _pack_tools_entry and _pack_dotted_entry.
        pack = self._repo_pack_copy()
        tools_dir = str(SKILL_ROOT / "tools")
        env = {k: v for k, v in os.environ.items()
               if k not in ("AIQT_PACK_ROOT", "GRC_AIQT_PACK")}
        env["AIQT_PACK_ROOT"] = str(pack)
        cases = (
            ("pack root", pack, "tools.aiqt_corpus"),
            ("pack root parent", pack.parent, "aiqt.tools.aiqt_corpus"),
            ("pack tools dir", pack / "tools", None),
        )
        for label, cwd, dotted in cases:
            with self.subTest(cwd=label):
                tail = ""
                if dotted:
                    tail = (
                        "import importlib\n"
                        "try:\n"
                        f"    m = importlib.import_module({dotted!r})\n"
                        "    print('LOADED', m.__file__)\n"
                        "except ModuleNotFoundError:\n"
                        f"    print('REFUSED', {dotted!r})\n")
                probe = (
                    "import os, sys\n"
                    "sys.dont_write_bytecode = True\n"
                    f"os.chdir({str(cwd)!r})\n"
                    "sys.path.insert(0, '')\n"
                    "sys.path.insert(0, '.')\n"
                    f"sys.path.append({tools_dir!r})\n"
                    "import aiqt_bootstrap\n"
                    "print('EMPTY',"
                    " 'KEPT' if '' in sys.path else 'SCRUBBED')\n"
                    "print('DOT',"
                    " 'KEPT' if '.' in sys.path else 'SCRUBBED')\n"
                    + tail)
                res = subprocess.run([sys.executable, "-I", "-c", probe],
                                     capture_output=True, text=True,
                                     env=env, timeout=120)
                self.assertEqual(res.returncode, 0, res.stderr)
                lines = res.stdout.strip().splitlines()
                self.assertEqual(lines[0], "EMPTY SCRUBBED",
                                 "the empty entry must be resolved against "
                                 "the working directory and scrubbed "
                                 "exactly like '.' when that directory is "
                                 "a pack place (guards against an unscrubbed empty sys.path entry)")
                self.assertEqual(lines[1], "DOT SCRUBBED",
                                 "'.' must keep being scrubbed at a pack "
                                 "place: '' and '.' are the same route")
                if dotted:
                    self.assertEqual(
                        lines[2], f"REFUSED {dotted}",
                        "no dotted spelling may reach the pack through "
                        "the empty entry after the scrub "
                        "(guards against an unscrubbed empty sys.path entry)")

    def test_every_refusal_path_removes_unmarked_module(self):
        # In the earlier repository, the bootstrap removed a refused
        # unmarked aiqt_corpus from sys.modules only on the
        # before-this-bootstrap-ran path. An unmarked module present when
        # the bootstrap FAILED before that check (a broken strict override),
        # one refused by the mid-install marker check in
        # _install_verified_corpus, and one refused by the
        # after-installation re-check all stayed in sys.modules, and a later
        # import returned them while the docstrings said the name fails
        # closed for the rest of the process. Every such refusal, and a
        # bootstrap failure after a pre-existing module was seen, now goes
        # through one helper that removes the refused module under the
        # import lock (only when the name still binds the same object)
        # before the ImportError propagates.
        import importlib
        import types
        from unittest.mock import patch
        pack = self._repo_pack_copy()
        broken = self._fixture_base("aiqt-broken-override-")
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_refusalpaths")
        saved_module = sys.modules.pop("aiqt_corpus", None)
        saved_path = list(sys.path)
        saved_meta = list(sys.meta_path)
        try:
            sys.path[:] = [e for e in sys.path
                           if not (isinstance(e, str)
                                   and (Path(e) / "aiqt_corpus.py").is_file())]
            with patch.dict(os.environ, {"AIQT_PACK_ROOT": str(pack)}):
                os.environ.pop("GRC_AIQT_PACK", None)
                # Case A: a bootstrap failure after a pre-existing module
                # was seen (the strict override is shapeless, so
                # find_pack_tools raises before the acceptance check runs).
                impostor_a = types.ModuleType("aiqt_corpus")
                sys.modules["aiqt_corpus"] = impostor_a
                with patch.dict(os.environ,
                                {"AIQT_PACK_ROOT": str(broken)}):
                    with self.assertRaises(ImportError):
                        mod.ensure_on_path()
                self.assertNotIn(
                    "aiqt_corpus", sys.modules,
                    "a pre-existing module seen by a FAILING bootstrap "
                    "must be removed from sys.modules "
                    "(guards against a refused module left in sys.modules)")
                with self.assertRaises(ModuleNotFoundError):
                    importlib.import_module("aiqt_corpus")
                # Case B: the mid-install marker check. A successful run
                # first captures the verified bytes; the unmarked module
                # then stands in for one that appeared during execution.
                mod.ensure_on_path()
                impostor_b = types.ModuleType("aiqt_corpus")
                sys.modules["aiqt_corpus"] = impostor_b
                with self.assertRaisesRegex(ImportError,
                                            "installation marker"):
                    mod._install_verified_corpus(pack / "tools")
                self.assertNotIn(
                    "aiqt_corpus", sys.modules,
                    "a module refused by the mid-install marker check "
                    "must be removed from sys.modules "
                    "(guards against a refused module left in sys.modules)")
                # Case C: the after-installation re-check. An installer
                # that leaves an unmarked module behind stands in for a
                # racing publisher.
                impostor_c = types.ModuleType("aiqt_corpus")

                def planting_installer(tools):
                    sys.modules["aiqt_corpus"] = impostor_c

                with patch.object(mod, "_install_verified_corpus",
                                  planting_installer):
                    with self.assertRaisesRegex(ImportError,
                                                "installation marker"):
                        mod.ensure_on_path()
                self.assertNotIn(
                    "aiqt_corpus", sys.modules,
                    "a module refused by the after-installation re-check "
                    "must be removed from sys.modules "
                    "(guards against a refused module left in sys.modules)")
                with self.assertRaises(ModuleNotFoundError):
                    importlib.import_module("aiqt_corpus")
        finally:
            sys.modules.pop("aiqt_corpus", None)
            if saved_module is not None:
                sys.modules["aiqt_corpus"] = saved_module
            sys.path[:] = saved_path
            sys.meta_path[:] = saved_meta
            importlib.invalidate_caches()

    def test_dotted_route_disclosure_names_the_class_not_a_complete_list(self):
        # The defect class behind the repository-root premise, the
        # symlinked dotted route and the empty-entry route is the claim of
        # an exhaustive dotted-route list: in the earlier repository,
        # three times in a row a route turned up that the docstrings said
        # did not exist or was removed. The docstrings now claim
        # protection only for what the guard owns (the bare name
        # aiqt_corpus), state the dotted routes as a CLASS -- any sys.path
        # entry from which the pack's files can be reached under a path of
        # identifiers -- give the known routes as examples, never call the
        # list complete, and describe the scrub as a best-effort second
        # layer that removes the entry shapes it recognises.
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_disclosure")
        docs = {
            "module": " ".join(mod.__doc__.split()),
            "dotted": " ".join(mod._pack_dotted_entry.__doc__.split()),
            "scrub": " ".join(
                mod._scrub_pack_tools_entries.__doc__.split()),
            "ensure_on_path": " ".join(mod.ensure_on_path.__doc__.split()),
        }
        self.assertIn("path of Python identifiers", docs["module"],
                      "the module docstring must state the dotted routes "
                      "as a class over identifier paths")
        for marker in ("a dotted route through a symlinked directory",
                       "an unscrubbed empty sys.path entry",
                       "any other such route",
                       "no list of such routes here is complete"):
            self.assertIn(marker, docs["module"],
                          "the module docstring must give the class, the "
                          "known examples, and the explicit "
                          f"non-completeness: missing {marker!r}")
        self.assertIn("BEST-EFFORT", docs["scrub"],
                      "the scrub must be described as a best-effort "
                      "second layer")
        self.assertIn("RECOGNISES", docs["scrub"],
                      "the scrub must claim only the entry shapes it "
                      "recognises")
        self.assertIn("an unscrubbed empty sys.path entry", docs["dotted"],
                      "_pack_dotted_entry must document the empty entry "
                      "resolved exactly like '.'")
        for where, doc_text in docs.items():
            for claim in ("exactly these entries",
                          "no such route exists",
                          "disclosed exactly",
                          "removes exactly those resolved entries"):
                self.assertNotIn(
                    claim, doc_text,
                    f"the {where} docstring must not claim an exhaustive "
                    f"dotted-route list ({claim!r}): the defect class is "
                    "the exhaustive-route claim itself")

    def test_symlink_entry_dotted_route_is_pinned_disclosed_residual(self):
        # A plain sys.path directory holding a symlink to a pack directory
        # (at any depth) survives the scrub -- the ENTRY resolves to the
        # plain directory, and only the entry is resolved, never the links
        # under it -- and a dotted import through the link runs the on-disk
        # pack bytes without the installation marker. This is a disclosed
        # residual of the best-effort scrub, pinned here so a change in the
        # behaviour (or the loss of the disclosure) is caught; the bare
        # name stays guarded throughout.
        pack = self._repo_pack_copy()
        plain = self._fixture_base("aiqt-symlink-entry-")
        os.symlink(pack / "tools", plain / "xtools")
        os.symlink(pack.parent, plain / "yclaude")
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_symlinkroute")
        docs = {
            "module": " ".join(mod.__doc__.split()),
            "dotted": " ".join(mod._pack_dotted_entry.__doc__.split()),
            "scrub": " ".join(
                mod._scrub_pack_tools_entries.__doc__.split()),
        }
        for where in ("module", "dotted", "scrub"):
            self.assertIn("a dotted route through a symlinked directory", docs[where],
                          f"the {where} docstring must disclose the "
                          "symlink-in-plain-entry dotted route as a "
                          "residual the scrub does not recognise")
        self.assertIn("at any depth", docs["module"],
                      "the disclosure must cover symlinks at any depth, "
                      "not one worked example")
        tools_dir = str(SKILL_ROOT / "tools")
        env = {k: v for k, v in os.environ.items()
               if k not in ("AIQT_PACK_ROOT", "GRC_AIQT_PACK")}
        env["AIQT_PACK_ROOT"] = str(pack)
        probe = (
            "import importlib, os, sys\n"
            "sys.dont_write_bytecode = True\n"
            f"sys.path.insert(0, {str(plain)!r})\n"
            f"sys.path.append({tools_dir!r})\n"
            "import aiqt_bootstrap\n"
            f"print('ENTRY', 'KEPT' if {str(plain)!r} in sys.path"
            " else 'SCRUBBED')\n"
            "for dotted in ('xtools.aiqt_corpus',"
            " 'yclaude.aiqt.tools.aiqt_corpus'):\n"
            "    m = importlib.import_module(dotted)\n"
            "    print('LOADED', dotted,\n"
            "          hasattr(m, '__aiqt_bootstrap_installed_digest__'),\n"
            "          os.path.realpath(m.__file__))\n"
            "bare = importlib.import_module('aiqt_corpus')\n"
            "print('BARE',"
            " hasattr(bare, '__aiqt_bootstrap_installed_digest__'))\n")
        res = subprocess.run([sys.executable, "-I", "-c", probe],
                             capture_output=True, text=True, env=env,
                             timeout=120)
        self.assertEqual(res.returncode, 0, res.stderr)
        lines = res.stdout.strip().splitlines()
        real_file = os.path.realpath(pack / "tools" / "aiqt_corpus.py")
        self.assertEqual(lines[0], "ENTRY KEPT",
                         "the plain directory holding the symlinks is not "
                         "an entry shape the scrub recognises: the kept "
                         "entry is the disclosed residual "
                         "(a dotted route through a symlinked directory)")
        self.assertEqual(lines[1],
                         f"LOADED xtools.aiqt_corpus False {real_file}",
                         "the symlink route really loads the on-disk pack "
                         "bytes without the installation marker: the "
                         "disclosed residual "
                         "(a dotted route through a symlinked directory)")
        self.assertEqual(
            lines[2],
            f"LOADED yclaude.aiqt.tools.aiqt_corpus False {real_file}",
            "a deeper symlink route behaves the same way")
        self.assertEqual(lines[3], "BARE True",
                         "the bare name must still serve only the "
                         "published verified module")

    def test_non_importerror_bootstrap_failure_removes_unmarked_module(self):
        # In the earlier repository, the failure handler was `except
        # ImportError` only, so a bootstrap failure raising RuntimeError
        # (Path.expanduser on an unknown-user override), OSError or
        # SyntaxError (_load_verifier beside the shim) left a planted
        # unmarked aiqt_corpus in sys.modules and a later import returned
        # it, while the docstrings claimed every bootstrap failure after a
        # pre-existing module was seen removed it. The handler now catches
        # BaseException, removes an UNMARKED pre-existing module through
        # the one shared helper, and re-raises the original error
        # unchanged.
        import importlib
        import importlib.util
        import types
        from unittest.mock import patch
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_nonimporterror")
        saved_module = sys.modules.pop("aiqt_corpus", None)
        saved_path = list(sys.path)
        saved_meta = list(sys.meta_path)
        base = self._fixture_base("aiqt-nonimporterror-")
        try:
            # Route 1: RuntimeError out of Path.expanduser for an
            # unknown-user override, in the already-loaded shim.
            impostor = types.ModuleType("aiqt_corpus")
            sys.modules["aiqt_corpus"] = impostor
            with patch.dict(os.environ,
                            {"AIQT_PACK_ROOT":
                             "~no_such_user_tilde_override/pack"}):
                os.environ.pop("GRC_AIQT_PACK", None)
                with self.assertRaises(RuntimeError):
                    mod.ensure_on_path()
            self.assertNotIn(
                "aiqt_corpus", sys.modules,
                "a RuntimeError bootstrap failure must remove the "
                "unmarked pre-existing module "
                "(guards against cleanup skipped on a non-ImportError failure)")
            with self.assertRaises(ModuleNotFoundError):
                importlib.import_module("aiqt_corpus")
            # Routes 2 and 3: _load_verifier raises OSError (aiqt_rules.py
            # missing beside a shim copy) or SyntaxError (corrupted),
            # during the copy's module-level bootstrap.
            for label, exc_type, rules_body in (
                    ("missing-verifier", OSError, None),
                    ("corrupted-verifier", SyntaxError, "def (:\n")):
                with self.subTest(route=label):
                    copy_dir = base / label
                    copy_dir.mkdir()
                    shim = copy_dir / "aiqt_bootstrap.py"
                    shutil.copy2(SKILL_ROOT / "tools" / "aiqt_bootstrap.py",
                                 shim)
                    if rules_body is not None:
                        (copy_dir / "aiqt_rules.py").write_text(
                            rules_body, encoding="utf-8")
                    impostor = types.ModuleType("aiqt_corpus")
                    sys.modules["aiqt_corpus"] = impostor
                    pack = self._repo_pack_copy()
                    with patch.dict(os.environ,
                                    {"AIQT_PACK_ROOT": str(pack)}):
                        os.environ.pop("GRC_AIQT_PACK", None)
                        spec = importlib.util.spec_from_file_location(
                            f"aiqt_bootstrap_nonimp_{exc_type.__name__}",
                            shim)
                        copy = importlib.util.module_from_spec(spec)
                        with self.assertRaises(exc_type):
                            spec.loader.exec_module(copy)
                    self.assertNotIn(
                        "aiqt_corpus", sys.modules,
                        f"a bootstrap failure via the {label} route must "
                        "remove the unmarked pre-existing module "
                        "(guards against cleanup skipped on a non-ImportError failure)")
                    with self.assertRaises(ModuleNotFoundError):
                        importlib.import_module("aiqt_corpus")
            # Routes 4 and 5: BaseException failures that are NOT Exception
            # subclasses -- KeyboardInterrupt and SystemExit -- must behave
            # the same way: in the earlier repository, narrowing the handler
            # to `except Exception` left all 104 tests passing, so these
            # routes pin the breadth: the unmarked module is removed and the
            # SAME exception object propagates unchanged.
            for exc in (KeyboardInterrupt("sentinel-interrupt"),
                        SystemExit("sentinel-exit")):
                with self.subTest(route=type(exc).__name__):
                    impostor = types.ModuleType("aiqt_corpus")
                    sys.modules["aiqt_corpus"] = impostor

                    def interrupting_find(_exc=exc):
                        raise _exc

                    with patch.object(mod, "find_pack_tools",
                                      interrupting_find):
                        with self.assertRaises(type(exc)) as ctx:
                            mod.ensure_on_path()
                    self.assertIs(
                        ctx.exception, exc,
                        "the failure handler must re-raise the SAME "
                        "exception object unchanged "
                        "(guards against a failure handler narrowed below BaseException)")
                    self.assertNotIn(
                        "aiqt_corpus", sys.modules,
                        "a KeyboardInterrupt or SystemExit bootstrap "
                        "failure must remove the unmarked pre-existing "
                        "module (guards against cleanup skipped on a non-ImportError failure, "
                        "a failure handler narrowed below BaseException)")
                    with self.assertRaises(ModuleNotFoundError):
                        importlib.import_module("aiqt_corpus")
        finally:
            sys.modules.pop("aiqt_corpus", None)
            if saved_module is not None:
                sys.modules["aiqt_corpus"] = saved_module
            sys.path[:] = saved_path
            sys.meta_path[:] = saved_meta
            importlib.invalidate_caches()

    def test_failure_does_not_remove_or_unpublish_marked_module(self):
        # In the earlier repository, the failure handler called
        # _remove_refused_module on the module captured as preexisting
        # unconditionally. The helper's checks are object identity, so a
        # racing run that accepted and published the SAME pre-existing
        # verified object had that publication retracted and the module
        # deleted by this run's failure, and a failing re-run removed the
        # marked module an earlier successful run left (fail-closed
        # availability loss, refuting the "left alone" comments). The
        # failure path now removes only an UNMARKED pre-existing module:
        # one carrying the installation marker for the verified bytes is
        # never removed or unpublished by another run's failure.
        import importlib
        from unittest.mock import patch
        pack = self._repo_pack_copy()
        broken = self._fixture_base("aiqt-marked-broken-override-")
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_markedkept")
        saved_module = sys.modules.pop("aiqt_corpus", None)
        saved_path = list(sys.path)
        saved_meta = list(sys.meta_path)
        try:
            with patch.dict(os.environ, {"AIQT_PACK_ROOT": str(pack)}):
                os.environ.pop("GRC_AIQT_PACK", None)
                tools = mod.ensure_on_path()
                verified = sys.modules["aiqt_corpus"]

                # Racing-success case: a racing run's full publication of
                # the SAME pre-existing verified object completes inside
                # this run's window; this run's discovery then fails.
                def racing_then_failing_find():
                    mod._install_verified_corpus(tools)
                    raise ImportError("this run's discovery failed")

                with patch.object(mod, "find_pack_tools",
                                  racing_then_failing_find):
                    with self.assertRaisesRegex(ImportError,
                                                "discovery failed"):
                        mod.ensure_on_path()
                self.assertIs(
                    sys.modules.get("aiqt_corpus"), verified,
                    "a marked, verified module must survive another "
                    "run's failure "
                    "(guards against a failing run unpublishing a verified module)")
                self.assertIs(
                    mod._NAME_GUARD._module, verified,
                    "the racing run's publication of the same object "
                    "must not be retracted by this run's failure "
                    "(guards against a failing run unpublishing a verified module, "
                    "removing or unpublishing a racing publication of the same object)")
                self.assertIs(importlib.import_module("aiqt_corpus"),
                              verified)
                # Failing re-run case: a later run that fails (shapeless
                # strict override) keeps the marked module the earlier
                # successful run left in sys.modules.
                with patch.dict(os.environ,
                                {"AIQT_PACK_ROOT": str(broken)}):
                    with self.assertRaises(ImportError):
                        mod.ensure_on_path()
                self.assertIs(
                    sys.modules.get("aiqt_corpus"), verified,
                    "a failing re-run must not remove the marked module "
                    "an earlier successful run left "
                    "(guards against a failing run unpublishing a verified module)")
                self.assertIs(importlib.import_module("aiqt_corpus"),
                              verified)
        finally:
            sys.modules.pop("aiqt_corpus", None)
            if saved_module is not None:
                sys.modules["aiqt_corpus"] = saved_module
            sys.path[:] = saved_path
            sys.meta_path[:] = saved_meta
            importlib.invalidate_caches()

    def test_failure_path_wording_states_marker_and_identity_semantics(self):
        # "Left alone" held only for a DIFFERENT module object -- the
        # helper's checks are object identity, so the earlier
        # repository's comments ("a module this run (or a racing run)
        # accepted or published meanwhile is left alone"; "A module
        # another thread swapped in or published meanwhile is left
        # alone") were refuted by a racing publication of the same
        # pre-existing object, and its failure-path claims held only for
        # ImportError. The docstrings and comments now state the identity
        # semantics exactly, scope the failure-path removal to an
        # UNMARKED module, and cover failures of any exception type.
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_failurewording")
        source = (SKILL_ROOT / "tools" / "aiqt_bootstrap.py").read_text(
            encoding="utf-8")
        normalized = " ".join(
            line.strip().lstrip("#").strip()
            for line in source.splitlines())
        for stale in (
                "A module another thread swapped in or published "
                "meanwhile is left alone",
                "a module this run (or a racing run) accepted or "
                "published meanwhile is left alone",
                "and a bootstrap failure after a pre-existing module "
                "was seen"):
            self.assertNotIn(
                stale, normalized,
                f"the stale absolute claim {stale!r} must be gone: it "
                "held only for a different module object or only for "
                "ImportError failures (a racing publication of the same object is a disclosed "
                "limit of the identity check; guards against cleanup skipped on a "
                "non-ImportError failure)")
        helper_doc = " ".join(mod._remove_refused_module.__doc__.split())
        self.assertIn("OBJECT IDENTITY", helper_doc,
                      "the helper must state that its checks are object "
                      "identity, which cannot tell a refusal from a racing "
                      "publication of the same object")
        self.assertIn("DIFFERENT module object", helper_doc,
                      "the helper may claim to leave alone only a "
                      "DIFFERENT module object, never any racing "
                      "publication: identity alone cannot tell a refusal "
                      "from a racing publication of the same object")
        marked_doc = " ".join(
            mod._marked_for_verified_bytes.__doc__.split())
        self.assertIn("a failing run unpublishing a verified module", marked_doc,
                      "the marker helper must state why a marked module "
                      "survives another run's failure")
        for where, doc in (("module", " ".join(mod.__doc__.split())),
                           ("ensure_on_path",
                            " ".join(mod.ensure_on_path.__doc__.split()))):
            self.assertIn("cleanup skipped on a non-ImportError failure", doc,
                          f"the {where} docstring must document the "
                          "failure path as covering every exception type")
            self.assertIn("UNMARKED", doc,
                          f"the {where} docstring must scope the "
                          "failure-path removal to an unmarked module")
            self.assertIn("a failing run unpublishing a verified module", doc,
                          f"the {where} docstring must state the "
                          "marked-module guarantee")
        # In the earlier repository, the docstring wording overclaimed
        # the raising-descriptor protection -- "a __dict__ descriptor
        # raising any exception ... is treated as unmarked" -- but
        # _module_marker catches only Exception, so a descriptor raising
        # a BaseException subclass still crashes the read and the entry
        # survives (the same in-process forgery class as the dict-less
        # and raising-descriptor entries). Catching BaseException there
        # would swallow a real KeyboardInterrupt, so the docstrings must
        # instead claim Exception only and disclose the BaseException
        # residual.
        marker_doc = " ".join(mod._module_marker.__doc__.split())
        for where, doc in (("_module_marker", marker_doc),
                           ("_marked_for_verified_bytes", marked_doc)):
            for stale in ("raising any exception",
                          "marker lookup raises is unmarked"):
                self.assertNotIn(
                    stale, doc,
                    f"the {where} docstring, on a namespace read that raises, may not overclaim the "
                    f"protection: {stale!r} must be narrowed to "
                    "``Exception`` "
                    "(the disclosed residual of a descriptor that raises BaseException)")
            for required in ("``Exception``", "``BaseException``",
                             "in-process forgery",
                             "a descriptor that raises BaseException"):
                self.assertIn(
                    required, doc,
                    f"the {where} docstring must disclose the "
                    "BaseException-raising descriptor residual: missing "
                    f"{required!r} "
                    "(the disclosed residual of a descriptor that raises BaseException)")

    def test_refused_midinstall_publication_is_retracted(self):
        # The guard retraction in _remove_refused_module is load-bearing
        # -- a marker-matching module with a FOREIGN origin that appears
        # during execution is kept and PUBLISHED by the mid-install check
        # (marker only) and then refused by the after-installation origin
        # re-check; without the retraction the guard keeps serving the
        # refused module to a later bare-name import after the
        # sys.modules cleanup. In the earlier repository, no test
        # exercised that branch (deleting it left all 100
        # AIQTVendorDigestTests and AIQTCutoverTests green). This test
        # drives the real mid-install publication and re-check refusal
        # and fails when the retraction branch is a no-op.
        import hashlib
        import importlib
        import importlib.machinery
        import types
        from unittest.mock import patch
        pack = self._repo_pack_copy()
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_retraction")
        saved_module = sys.modules.pop("aiqt_corpus", None)
        saved_path = list(sys.path)
        saved_meta = list(sys.meta_path)
        planted = []
        orig_exec = mod._VerifiedSourceLoader.exec_module

        def planting_exec(loader_self, module):
            orig_exec(loader_self, module)
            foreign = types.ModuleType("aiqt_corpus")
            foreign.__dict__[mod._INSTALL_MARKER_ATTR] = hashlib.sha256(
                mod._verified_corpus_source).hexdigest()
            foreign.__spec__ = importlib.machinery.ModuleSpec(
                "aiqt_corpus", None,
                origin="/nonexistent-foreign/aiqt_corpus.py")
            sys.modules["aiqt_corpus"] = foreign
            planted.append(foreign)

        try:
            with patch.dict(os.environ, {"AIQT_PACK_ROOT": str(pack)}):
                os.environ.pop("GRC_AIQT_PACK", None)
                with patch.object(mod._VerifiedSourceLoader, "exec_module",
                                  planting_exec):
                    with self.assertRaisesRegex(ImportError,
                                                "resolves to"):
                        mod.ensure_on_path()
            foreign = planted[0]
            self.assertNotIn(
                "aiqt_corpus", sys.modules,
                "the module refused by the after-installation re-check "
                "must be removed from sys.modules "
                "(guards against a refused module left in sys.modules)")
            self.assertIsNot(
                mod._NAME_GUARD._module, foreign,
                "the mid-install publication of the refused module must "
                "be retracted (guards against a mid-install publication left in the guard, "
                "a guard serving a refused module to a later import)")
            with self.assertRaises(ModuleNotFoundError):
                importlib.import_module("aiqt_corpus")
        finally:
            sys.modules.pop("aiqt_corpus", None)
            if saved_module is not None:
                sys.modules["aiqt_corpus"] = saved_module
            sys.path[:] = saved_path
            sys.meta_path[:] = saved_meta
            importlib.invalidate_caches()

    def test_refused_override_bytes_never_become_the_reference(self):
        # In the earlier repository, _verified() assigned
        # _verified_corpus_source BEFORE _pinned_to_repository() decided
        # whether to admit an override, so on a re-run a self-consistent
        # pack whose release root differs from the repository pin replaced
        # the captured bytes and was then refused; the failure handler then
        # validated the earlier run's verified module against the REFUSED
        # pack's digest, treated it as unmarked, and removed it (an
        # executed probe showed availability loss refuting the "never
        # removed" claims). The bytes are now assigned only after
        # admission, so a refused pack's bytes never become the reference.
        import importlib
        from unittest.mock import patch
        pack = self._repo_pack_copy()
        unpinned = self._standalone_pack(module=b"UNPINNED = True\n")
        mod = load_linter_module("tools/aiqt_bootstrap.py",
                                 "aiqt_bootstrap_refusedbytes")
        saved_module = sys.modules.pop("aiqt_corpus", None)
        saved_path = list(sys.path)
        saved_meta = list(sys.meta_path)
        try:
            with patch.dict(os.environ, {"AIQT_PACK_ROOT": str(pack)}):
                os.environ.pop("GRC_AIQT_PACK", None)
                mod.ensure_on_path()
                verified = sys.modules["aiqt_corpus"]
                captured = mod._verified_corpus_source
                with patch.dict(os.environ,
                                {"AIQT_PACK_ROOT": str(unpinned)}):
                    with self.assertRaisesRegex(ImportError, "unpinned"):
                        mod.ensure_on_path()
                self.assertEqual(
                    mod._verified_corpus_source, captured,
                    "a refused unpinned override's bytes must never "
                    "replace the captured verified bytes "
                    "(guards against a refused override's bytes taken as the reference)")
                self.assertIs(
                    sys.modules.get("aiqt_corpus"), verified,
                    "the earlier run's verified module must survive a "
                    "refused unpinned override's failing re-run "
                    "(guards against a refused override's bytes taken as the reference)")
                self.assertIs(importlib.import_module("aiqt_corpus"),
                              verified)
        finally:
            sys.modules.pop("aiqt_corpus", None)
            if saved_module is not None:
                sys.modules["aiqt_corpus"] = saved_module
            sys.path[:] = saved_path
            sys.meta_path[:] = saved_meta
            importlib.invalidate_caches()

