    def test_library_version_monotonicity_walk_visits_the_rglob_document_set(self) -> None:
        # In the earlier repository the walk used Path.rglob("*.md"); it now uses os.walk so
        # a directory it cannot list is reported. On an intact tree it must visit exactly the
        # documents the rglob walk did, with the same filters: the real corpus, and a fixture
        # with a symlinked directory (not descended), a directory and symlinks named *.md,
        # hidden names and exempt trees. The expected set for the real corpus applies the walk's
        # own exemption rule, lint_common in_exempt_dir, which admits the project documents
        # under .claude and .working (PROJECT_DOCUMENT_DIRS and PROJECT_DOCUMENT_FILES).
        # The fixture's expected set is written out, so it does not depend on that rule. The
        # expected set for the real corpus calls no production exemption predicate either. The
        # rule is written out below: the exempt directory names, the exempt source root, and the
        # project documents admitted below .claude and .working. The fixture checks that rule
        # too.
        from unittest import mock

        mono = load_linter_module(".claude/skills/corpus-management/tools/lint-library-version-monotonicity.py", "mono_walk")

        exempt_names = {".git", "node_modules", "__pycache__", ".claude", ".working", "references",
                        ".ref", ".scratch", ".private"}
        cm = (".claude", "skills", "corpus-management")
        exempt_root = cm + ("src",)
        admitted = (cm + ("registers",), cm + ("specs",), cm + ("docs",), cm + ("tools", "README.md"),
                    cm + ("tests", "README.md"), (".working", "CHANGELOG.md"), (".working", "TODO.md"))

        def exempt(parts):
            if len(parts) > len(exempt_root) and parts[: len(exempt_root)] == exempt_root:
                return True
            waived = next((len(entry) for entry in admitted if parts[: len(entry)] == entry), 0)
            return any(part in exempt_names for part in parts[waived:])

        def rglob_set(root):
            found = set()
            for path in root.rglob("*.md"):
                rel = path.relative_to(root)
                if exempt(rel.parts):
                    continue
                if rel.as_posix() not in ("README.md", ".working/CHANGELOG.md"):
                    found.add(rel.as_posix())
            return found

        fixture = self.tmp / "tree"
        outside = self.tmp / "outside"
        (outside / "deep").mkdir(parents=True)
        (outside / "deep" / "o.md").write_text("o\n", encoding="utf-8")
        for rel in ("README.md", ".working/CHANGELOG.md", "a.md", ".hidden.md", "x.MD", "g/b.md",
                    "g/.h/c.md", "g/dir.md/inner.md", "g/.git/x.md", "g/references/r.md",
                    ".claude/c.md", ".claude/skills/corpus-management/src/z.md", "sub/CHANGELOG.md",
                    ".claude/skills/corpus-management/registers/reg.md", ".working/TODO.md",
                    ".working/notes.md", ".claude/skills/corpus-management/specs/spec.md",
                    ".claude/skills/corpus-management/specs/__pycache__/p.md",
                    ".claude/skills/corpus-management/docs/guide.md",
                    ".claude/skills/corpus-management/docs/references/r.md",
                    ".claude/skills/corpus-management/specsx/n.md"):
            (fixture / rel).parent.mkdir(parents=True, exist_ok=True)
            (fixture / rel).write_text("x\n", encoding="utf-8")
        (fixture / "g" / "linkdir").symlink_to(outside)
        (fixture / "g" / "linkdir.md").symlink_to(outside)
        (fixture / "g" / "linkfile.md").symlink_to(fixture / "a.md")
        (fixture / "g" / "dangling.md").symlink_to(fixture / "missing")
        (fixture / ".claude/skills/corpus-management/src" / "out.md").symlink_to(fixture / "a.md")
        fixture_expected = {
            ".claude/skills/corpus-management/registers/reg.md", ".hidden.md", ".working/TODO.md",
            ".claude/skills/corpus-management/specs/spec.md",
            ".claude/skills/corpus-management/docs/guide.md",
            "a.md", "g/.h/c.md", "g/b.md", "g/dangling.md", "g/dir.md", "g/dir.md/inner.md",
            "g/linkdir.md", "g/linkfile.md", "sub/CHANGELOG.md",
        }
        self.assertEqual(rglob_set(fixture), fixture_expected)
        for root in (REPO_ROOT, fixture):
            expected = rglob_set(root) if root == REPO_ROOT else fixture_expected
            self.assertTrue(expected, root)
            problems = []
            with mock.patch.object(mono, "REPO_ROOT", root):
                walked = [rel for _, rel in mono.walk_current_documents(problems)]
            self.assertEqual(problems, [], root)
            self.assertEqual(len(walked), len(set(walked)), root)
            self.assertEqual(set(walked), expected, root)

    def test_date_cobump_refuses_an_unreadable_base_blob(self) -> None:
        repo = self.repo()
        first = self.commit(repo, {"doc.md": self.doc("1.0.0")})
        self.commit(repo, {"doc.md": self.doc("1.0.1")})
        gate = (sys.executable, str(SKILL_ROOT / "tools" / "check-date-cobump-on-pr.py"), first, "HEAD")
        result = self.run_in(repo, *gate)
        self.assertEqual(result.returncode, 1, result.stdout + result.stderr)  # the stale Date
        self.drop_object(repo, f"{first}:doc.md")
